        let saveDBTimeout = null;
        let isDBSyncPending = false;
        let lastSuccessfulSaveTime = null;
        let lastSaveDestination = 'local'; // 'local' | 'cloud'
        let currentAutoSaveState = 'synced'; // 'saving' | 'local_synced' | 'cloud_synced' | 'error'
        let floatingAutoSaveHideTimer = null;

        function formatAutoSaveTime(dateObj) {
            if (!dateObj) return '';
            const d = (dateObj instanceof Date) ? dateObj : new Date(dateObj);
            if (isNaN(d.getTime())) return '';
            const pad = (n) => String(n).padStart(2, '0');
            const h = pad(d.getHours());
            const m = pad(d.getMinutes());
            const s = pad(d.getSeconds());
            return `${h}:${m}:${s}`;
        }

        function isCloudActive() {
            return typeof window.isCloudSyncActive === 'function' && window.isCloudSyncActive();
        }

        function refreshStudentAutoSaveDisplay() {
            const badge = document.getElementById('studentListAutoSaveBadge');
            if (!badge) return;

            const iconEl = document.getElementById('studentListAutoSaveIcon');
            const titleEl = document.getElementById('studentListAutoSaveTitle');
            const targetEl = document.getElementById('studentListAutoSaveTargetBadge');
            const timeEl = document.getElementById('studentListAutoSaveTime');

            const cloudOn = isCloudActive();
            const timeStr = lastSuccessfulSaveTime ? formatAutoSaveTime(lastSuccessfulSaveTime) : '';

            if (currentAutoSaveState === 'saving') {
                badge.className = 'autosave-indicator-pill autosave-saving';
                if (iconEl) iconEl.innerHTML = '<span class="spin-animation">' + lucideIcon('refresh-cw', {size: 15}) + '</span>';
                if (titleEl) titleEl.textContent = 'جاري الحفظ التلقائي...';
                if (targetEl) {
                    targetEl.textContent = cloudOn ? 'السحابة + الذاكرة المحلية' : 'قاعدة البيانات المحلية';
                }
                if (timeEl) timeEl.textContent = 'جاري حفظ ومزامنة تغييرات التلاميذ...';
                return;
            }

            if (lastSaveDestination === 'cloud' || (cloudOn && lastSuccessfulSaveTime)) {
                badge.className = 'autosave-indicator-pill autosave-synced-cloud';
                if (iconEl) iconEl.innerHTML = lucideIcon('cloud-check', {size: 16});
                if (titleEl) titleEl.textContent = 'متزامن سحابياً ومحلياً';
                if (targetEl) targetEl.textContent = 'سحابة Firestore نشطة';
                if (timeEl) {
                    timeEl.textContent = timeStr ? `تمت المزامنة بنجاح • ${timeStr}` : 'بيانات التلاميذ متزامنة ومحفوظة سحابياً ومحلياً';
                }
            } else {
                badge.className = 'autosave-indicator-pill autosave-synced-local';
                if (iconEl) iconEl.innerHTML = lucideIcon('check-circle', {size: 16});
                if (titleEl) titleEl.textContent = 'تم الحفظ تلقائياً';
                if (targetEl) targetEl.textContent = 'الذاكرة المحلية (IndexedDB/LocalStorage)';
                if (timeEl) {
                    timeEl.textContent = timeStr ? `محفوظ بنجاح • ${timeStr}` : 'جميع بيانات التلاميذ مؤمنة ومحفوظة محلياً';
                }
            }
        }

        function showFloatingAutoSaveIndicator(type, title, subtitle) {
            const floatEl = document.getElementById('floatingAutoSaveIndicator');
            if (!floatEl) return;

            // Only show floating indicator if the main sync bar is scrolled out of view
            const syncBar = document.getElementById('classListSyncStatusBar');
            let shouldShow = true;
            if (syncBar && syncBar.getBoundingClientRect) {
                const rect = syncBar.getBoundingClientRect();
                if (rect.top >= 0 && rect.bottom <= (window.innerHeight || document.documentElement.clientHeight)) {
                    shouldShow = false;
                }
            }

            if (!shouldShow) {
                floatEl.classList.remove('floating-visible');
                return;
            }

            const iconEl = document.getElementById('floatingAutoSaveIcon');
            const titleEl = document.getElementById('floatingAutoSaveText');
            const subEl = document.getElementById('floatingAutoSaveSub');

            floatEl.className = 'floating-autosave-indicator floating-visible ' + 
                (type === 'saving' ? 'floating-saving' : (type === 'cloud' ? 'floating-cloud' : 'floating-synced'));

            if (iconEl) {
                if (type === 'saving') {
                    iconEl.innerHTML = '<span class="spin-animation">' + lucideIcon('refresh-cw', {size: 14}) + '</span>';
                } else if (type === 'cloud') {
                    iconEl.innerHTML = lucideIcon('cloud-check', {size: 14});
                } else {
                    iconEl.innerHTML = lucideIcon('check-circle', {size: 14});
                }
            }

            if (titleEl) titleEl.textContent = title;
            if (subEl) subEl.textContent = subtitle;

            if (floatingAutoSaveHideTimer) {
                clearTimeout(floatingAutoSaveHideTimer);
            }

            if (type !== 'saving') {
                floatingAutoSaveHideTimer = setTimeout(() => {
                    floatEl.classList.remove('floating-visible');
                }, 3500);
            }
        }

        function notifyStudentAutoSave(state, meta) {
            currentAutoSaveState = state;
            const badge = document.getElementById('studentListAutoSaveBadge');
            const iconEl = document.getElementById('studentListAutoSaveIcon');
            const titleEl = document.getElementById('studentListAutoSaveTitle');
            const targetEl = document.getElementById('studentListAutoSaveTargetBadge');
            const timeEl = document.getElementById('studentListAutoSaveTime');

            const cloudOn = isCloudActive();
            const nowTime = (meta && meta.time) ? meta.time : new Date();
            const timeStr = formatAutoSaveTime(nowTime);

            if (state === 'saving') {
                if (badge) {
                    badge.className = 'autosave-indicator-pill autosave-saving';
                    if (iconEl) iconEl.innerHTML = '<span class="spin-animation">' + lucideIcon('refresh-cw', {size: 15}) + '</span>';
                    if (titleEl) titleEl.textContent = 'جاري الحفظ التلقائي...';
                    if (targetEl) targetEl.textContent = cloudOn ? 'السحابة + الذاكرة المحلية' : 'قاعدة البيانات المحلية';
                    if (timeEl) timeEl.textContent = 'جاري تسجيل التغييرات في قاعدة البيانات...';
                }
                showFloatingAutoSaveIndicator('saving', 'جاري الحفظ التلقائي...', 'مزامنة التعديلات');
            } else if (state === 'cloud_synced') {
                lastSuccessfulSaveTime = nowTime;
                lastSaveDestination = 'cloud';
                if (badge) {
                    badge.className = 'autosave-indicator-pill autosave-synced-cloud';
                    if (iconEl) iconEl.innerHTML = lucideIcon('cloud-check', {size: 16});
                    if (titleEl) titleEl.textContent = 'متزامن سحابياً ومحلياً بنجاح';
                    if (targetEl) targetEl.textContent = 'سحابة Firestore + الذاكرة المحلية';
                    if (timeEl) timeEl.textContent = `تم التحديث والحفظ التلقائي • ${timeStr}`;
                }
                showFloatingAutoSaveIndicator('cloud', 'متزامن سحابياً ومحلياً', `تم الحفظ • ${timeStr}`);
            } else if (state === 'local_synced') {
                lastSuccessfulSaveTime = nowTime;
                lastSaveDestination = 'local';
                if (badge) {
                    badge.className = 'autosave-indicator-pill autosave-synced-local';
                    if (iconEl) iconEl.innerHTML = lucideIcon('check-circle', {size: 16});
                    if (titleEl) titleEl.textContent = 'تم الحفظ تلقائياً بنجاح';
                    if (targetEl) targetEl.textContent = 'قاعدة البيانات المحلية (آمنة)';
                    if (timeEl) timeEl.textContent = `محفوظ في الذاكرة المحلية • ${timeStr}`;
                }
                showFloatingAutoSaveIndicator('local', 'تم الحفظ محلياً بنجاح', `محفوظ تلقائياً • ${timeStr}`);
            } else if (state === 'local_synced_cloud_failed') {
                lastSuccessfulSaveTime = nowTime;
                lastSaveDestination = 'local';
                if (badge) {
                    badge.className = 'autosave-indicator-pill autosave-synced-local';
                    if (iconEl) iconEl.innerHTML = lucideIcon('check-circle', {size: 16});
                    if (titleEl) titleEl.textContent = 'تم الحفظ محلياً (السحابة غير متصلة)';
                    if (targetEl) targetEl.textContent = 'محلي فقط';
                    if (timeEl) timeEl.textContent = `بياناتك محفوظة محلياً بأمان • ${timeStr}`;
                }
                showFloatingAutoSaveIndicator('local', 'محفوظ محلياً بأمان', `السحابة غير متصلة • ${timeStr}`);
            } else if (state === 'error') {
                if (badge) {
                    badge.className = 'autosave-indicator-pill autosave-error';
                    if (iconEl) iconEl.innerHTML = lucideIcon('alert-triangle', {size: 16});
                    if (titleEl) titleEl.textContent = 'تنبيه أثناء الحفظ';
                    if (targetEl) targetEl.textContent = 'خطأ تخزين';
                    if (timeEl) timeEl.textContent = (meta && meta.message) || 'تعذر إتمام عملية الحفظ!';
                }
                showFloatingAutoSaveIndicator('saving', 'تنبيه في الحفظ', (meta && meta.message) || 'خطأ في التخزين');
            }
        }

        function triggerManualSync() {
            if (saveDBTimeout) {
                clearTimeout(saveDBTimeout);
                saveDBTimeout = null;
            }
            notifyStudentAutoSave('saving');
            performDBSave();
            if (typeof showAppToast === 'function') {
                const cloudOn = isCloudActive();
                showAppToast(cloudOn ? 'تم حفظ ومزامنة بيانات التلاميذ بنجاح مع السحابة والمحلي.' : 'تم حفظ بيانات التلاميذ في قاعدة البيانات المحلية بنجاح.', 'success');
            }
        }
        window.triggerManualSync = triggerManualSync;

        window.addEventListener('cloudSyncResult', (e) => {
            const detail = e && e.detail;
            if (detail && detail.success) {
                notifyStudentAutoSave('cloud_synced', { time: detail.timestamp || new Date() });
            } else if (detail && !detail.success) {
                notifyStudentAutoSave('local_synced_cloud_failed', { time: new Date(), error: detail.error });
            }
        });

        // =========================================================================
        // منظومة ضغط وإدارة قواعد بيانات IndexedDB والنسخ الاحتياطي المجزأ (Sharded IDB Engine)
        // =========================================================================
        const MathPedagogicalSystemIDB = {
            dbName: 'MathPedagogicalSystemIDB',
            version: 1,
            dbInstance: null,
            MAX_SHARD_CHARS: 140000, // ~140KB لكل كائن فرعي لتجنب حظر الخيط الرئيسي (Main Thread)

            open() {
                return new Promise((resolve) => {
                    if (this.dbInstance) {
                        resolve(this.dbInstance);
                        return;
                    }
                    if (typeof window === 'undefined' || !window.indexedDB) {
                        resolve(null);
                        return;
                    }
                    try {
                        const req = window.indexedDB.open(this.dbName, this.version);
                        req.onupgradeneeded = (e) => {
                            const idb = e.target.result;
                            if (!idb.objectStoreNames.contains('db_chunks')) {
                                idb.createObjectStore('db_chunks', { keyPath: 'chunkId' });
                            }
                            if (!idb.objectStoreNames.contains('compact_backups')) {
                                idb.createObjectStore('compact_backups', { keyPath: 'shardKey' });
                            }
                        };
                        req.onsuccess = (e) => {
                            this.dbInstance = e.target.result;
                            resolve(this.dbInstance);
                        };
                        req.onerror = () => resolve(null);
                    } catch (err) {
                        resolve(null);
                    }
                });
            },

            /**
             * ضغط مفاتيح السجلات المتكررة (الغلبة للحجم في سجلات الغياب والنقط) لتقليص الحجم بنسبة 35%-45% دون فقدان أي حقل
             */
            compressRecordObjects(records) {
                if (!Array.isArray(records)) return [];
                return records.map(r => {
                    if (!r || typeof r !== 'object') return r;
                    const c = {
                        s: r.studentId,
                        c: r.className,
                        d: r.date,
                        p: r.session || r.time || '',
                        st: r.status || 'حاضر',
                        du: r.duration !== undefined ? r.duration : 2,
                        pt: r.part || 'all',
                        hw: r.homework || 'منجز'
                    };
                    if (r.id !== undefined) c.i = r.id;
                    if (r.studentName) c.n = r.studentName;
                    if (r.type) c.t = r.type;
                    if (r.justified) c.j = 1;
                    if (r.reason) c.r = r.reason;
                    if (r.note) c.nt = r.note;
                    if (r.notes) c.m = r.notes;
                    if (r.migratedHoliday) c.mh = 1;
                    if (r.holidayTitle) c.ht = r.holidayTitle;
                    return c;
                });
            },

            decompressRecordObjects(compactRecords) {
                if (!Array.isArray(compactRecords)) return [];
                return compactRecords.map(c => {
                    if (!c || typeof c !== 'object' || c.studentId !== undefined) return c;
                    const rec = {
                        studentId: c.s,
                        className: c.c || '',
                        date: c.d || '',
                        session: c.p || '',
                        status: c.st || 'حاضر',
                        duration: c.du !== undefined ? c.du : 2,
                        part: c.pt || 'all',
                        homework: c.hw || 'منجز'
                    };
                    if (c.i !== undefined) rec.id = c.i;
                    if (c.n) rec.studentName = c.n;
                    if (c.t) rec.type = c.t;
                    if (c.p) rec.time = c.p;
                    if (c.j) rec.justified = true;
                    if (c.r) rec.reason = c.r;
                    if (c.nt) rec.note = c.nt;
                    if (c.m) rec.notes = c.m;
                    if (c.mh) rec.migratedHoliday = true;
                    if (c.ht) rec.holidayTitle = c.ht;
                    return rec;
                });
            },

            /**
             * تقسيم كائن قاعدة البيانات الكبير (db) إلى 8 كائنات مجال أصغر ومستقلة (Domain Chunks) مع حفظ كافة المفاتيح الإضافية
             */
            buildDomainChunks(sourceDb) {
                if (!sourceDb || typeof sourceDb !== 'object') return [];
                const now = Date.now();

                // تنقية بيانات المكتبة من أي بيانات Base64 ضخمة مكررة (تبقى الملفات الثنائية في SchoolLibraryLocalFiles)
                const leanLibrary = Array.isArray(sourceDb.library)
                    ? sourceDb.library.map(item => {
                        if (!item || typeof item !== 'object') return item;
                        const copy = Object.assign({}, item);
                        if (typeof copy.dataUrl === 'string' && copy.dataUrl.length > 65536) {
                            delete copy.dataUrl;
                        }
                        return copy;
                    })
                    : [];

                const knownKeys = new Set([
                    'teacherProfile', 'profile', 'settings', 'absenceThreshold', 'theme', 'examCount',
                    'assignmentCount', 'activityWeight', 'examWeight', 'assignmentWeight', '_lastSavedAt',
                    '_lastSavedTimestamp', '_lastSavedDevice', 'classes', 'classConfig', 'coefConfig',
                    'weeklyHoursConfig', 'classColors', 'classManualOrder', 'classSortPref', 'classUsage',
                    'archivedClasses', 'archivedClassesMeta', 'studentGroups', 'seatingPlans', 'grades',
                    'notes', 'studentNotes', 'customEvaluations', 'remediationPlans', 'mathRemediationPlans',
                    'diagnostic', 'exams', 'upcomingExams', 'examReports', 'makeupExams', 'records',
                    'behaviors', 'positiveBehaviors', 'portfolioNotes', 'portfolioTasks', 'adminFollowUpSlips',
                    'adminAuditTrail', 'lessonLog', 'lessonLogs', 'homework', 'homeworkAgenda', 'exercises',
                    'curriculumEnhancements', 'agenda', 'academicMilestones', 'customMilestones', 'timetable',
                    'timetableCalendarSyncConfig', 'customHolidays', 'officialHolidays', 'teacherLeaves',
                    'holidayMigrationStats', 'tutoring', 'tutoringStudents', 'tutoringSessions', 'supportSessions',
                    'library', 'libraryDriveFolders', 'resources', 'savedProofs', 'mathOlympiadClub',
                    'customPromptTemplates', 'customPromptCategories'
                ]);

                const extraKeys = {};
                Object.keys(sourceDb).forEach(k => {
                    if (!knownKeys.has(k)) {
                        extraKeys[k] = sourceDb[k];
                    }
                });

                return [
                    {
                        chunkId: 'chunk_profile_settings',
                        updatedAt: now,
                        payload: {
                            teacherProfile: sourceDb.teacherProfile || {},
                            profile: sourceDb.profile || {},
                            settings: sourceDb.settings || {},
                            absenceThreshold: sourceDb.absenceThreshold || 10,
                            theme: sourceDb.theme || 'light',
                            examCount: sourceDb.examCount || 3,
                            assignmentCount: sourceDb.assignmentCount || 3,
                            activityWeight: sourceDb.activityWeight ?? 25,
                            examWeight: sourceDb.examWeight ?? 50,
                            assignmentWeight: sourceDb.assignmentWeight ?? 25,
                            _lastSavedAt: sourceDb._lastSavedAt || new Date(now).toISOString(),
                            _lastSavedTimestamp: sourceDb._lastSavedTimestamp || now,
                            _lastSavedDevice: sourceDb._lastSavedDevice || '',
                            _extraKeys: extraKeys
                        }
                    },
                    {
                        chunkId: 'chunk_classes_students',
                        updatedAt: now,
                        payload: {
                            classes: sourceDb.classes || {},
                            classConfig: sourceDb.classConfig || {},
                            coefConfig: sourceDb.coefConfig || {},
                            weeklyHoursConfig: sourceDb.weeklyHoursConfig || {},
                            classColors: sourceDb.classColors || {},
                            classManualOrder: sourceDb.classManualOrder || [],
                            classSortPref: sourceDb.classSortPref || 'default',
                            classUsage: sourceDb.classUsage || {},
                            archivedClasses: sourceDb.archivedClasses || {},
                            archivedClassesMeta: sourceDb.archivedClassesMeta || {},
                            studentGroups: sourceDb.studentGroups || {},
                            seatingPlans: sourceDb.seatingPlans || {}
                        }
                    },
                    {
                        chunkId: 'chunk_grades_evaluations',
                        updatedAt: now,
                        payload: {
                            grades: sourceDb.grades || {},
                            notes: sourceDb.notes || {},
                            studentNotes: sourceDb.studentNotes || {},
                            customEvaluations: sourceDb.customEvaluations || {},
                            remediationPlans: sourceDb.remediationPlans || {},
                            mathRemediationPlans: sourceDb.mathRemediationPlans || {},
                            diagnostic: sourceDb.diagnostic || {},
                            exams: sourceDb.exams || [],
                            upcomingExams: sourceDb.upcomingExams || [],
                            examReports: sourceDb.examReports || {},
                            makeupExams: sourceDb.makeupExams || []
                        }
                    },
                    {
                        chunkId: 'chunk_attendance_behaviors',
                        updatedAt: now,
                        compressed: true,
                        payload: {
                            recordsCompact: this.compressRecordObjects(sourceDb.records || []),
                            behaviors: sourceDb.behaviors || {},
                            positiveBehaviors: sourceDb.positiveBehaviors || [],
                            portfolioNotes: sourceDb.portfolioNotes || {},
                            portfolioTasks: sourceDb.portfolioTasks || {},
                            adminFollowUpSlips: sourceDb.adminFollowUpSlips || [],
                            adminAuditTrail: sourceDb.adminAuditTrail || []
                        }
                    },
                    {
                        chunkId: 'chunk_pedagogical_logs',
                        updatedAt: now,
                        payload: {
                            lessonLog: sourceDb.lessonLog || [],
                            lessonLogs: sourceDb.lessonLogs || [],
                            homework: sourceDb.homework || [],
                            homeworkAgenda: sourceDb.homeworkAgenda || [],
                            exercises: sourceDb.exercises || [],
                            curriculumEnhancements: sourceDb.curriculumEnhancements || {}
                        }
                    },
                    {
                        chunkId: 'chunk_calendar_agenda',
                        updatedAt: now,
                        payload: {
                            agenda: sourceDb.agenda || [],
                            academicMilestones: sourceDb.academicMilestones || [],
                            customMilestones: sourceDb.customMilestones || [],
                            timetable: sourceDb.timetable || {},
                            timetableCalendarSyncConfig: sourceDb.timetableCalendarSyncConfig || {},
                            customHolidays: sourceDb.customHolidays || [],
                            officialHolidays: sourceDb.officialHolidays || [],
                            teacherLeaves: sourceDb.teacherLeaves || [],
                            holidayMigrationStats: sourceDb.holidayMigrationStats || {}
                        }
                    },
                    {
                        chunkId: 'chunk_tutoring_support',
                        updatedAt: now,
                        payload: {
                            tutoring: sourceDb.tutoring || { students: [], expenses: [] },
                            tutoringStudents: sourceDb.tutoringStudents || [],
                            tutoringSessions: sourceDb.tutoringSessions || [],
                            supportSessions: sourceDb.supportSessions || []
                        }
                    },
                    {
                        chunkId: 'chunk_library_resources',
                        updatedAt: now,
                        payload: {
                            library: leanLibrary,
                            libraryDriveFolders: sourceDb.libraryDriveFolders || [],
                            resources: sourceDb.resources || [],
                            savedProofs: sourceDb.savedProofs || [],
                            mathOlympiadClub: sourceDb.mathOlympiadClub || {},
                            customPromptTemplates: sourceDb.customPromptTemplates || [],
                            customPromptCategories: sourceDb.customPromptCategories || []
                        }
                    }
                ];
            },

            /**
             * حفظ الكائنات المجزأة في IndexedDB بالإضافة إلى شظايا نسخ احتياطية مضغوطة وصغيرة عند الخروج/الخمول
             */
            async saveShardedBackup(sourceDb, options = {}) {
                const idb = await this.open();
                if (!idb || !sourceDb) return { savedChunks: 0, savedShards: 0 };

                const chunks = this.buildDomainChunks(sourceDb);
                let savedChunks = 0;
                let savedShards = 0;

                // 1. حفظ الكائنات الـ 8 المستقلة في مخزن db_chunks
                await new Promise((resolve) => {
                    try {
                        const tx = idb.transaction(['db_chunks'], 'readwrite');
                        const store = tx.objectStore('db_chunks');
                        chunks.forEach(ch => {
                            store.put(ch);
                            savedChunks++;
                        });
                        tx.oncomplete = () => resolve(true);
                        tx.onerror = () => resolve(false);
                    } catch (e) {
                        resolve(false);
                    }
                });

                // 2. عند الخروج أو التوقف عن النشاط، حفظ نسخة احتياطية مقسمة إلى شظايا صغيرة (Micro-Shards <= 140KB)
                if (options.createSnapshotShards !== false) {
                    try {
                        const compactSnapshot = {
                            v: 8,
                            ts: Date.now(),
                            reason: options.reason || 'auto',
                            chunks: chunks.map(c => ({ id: c.chunkId, p: c.payload, cmp: !!c.compressed }))
                        };
                        const rawJson = safeStringify(compactSnapshot);
                        const shardSize = this.MAX_SHARD_CHARS;
                        const totalShards = Math.max(1, Math.ceil(rawJson.length / shardSize));

                        await new Promise((resolve) => {
                            try {
                                const tx = idb.transaction(['compact_backups'], 'readwrite');
                                const store = tx.objectStore('compact_backups');
                                store.clear();

                                store.put({
                                    shardKey: 'backup_manifest',
                                    totalShards,
                                    totalBytes: rawJson.length,
                                    reason: options.reason || 'auto',
                                    createdAt: new Date().toISOString(),
                                    timestamp: Date.now()
                                });

                                for (let i = 0; i < totalShards; i++) {
                                    const slice = rawJson.slice(i * shardSize, (i + 1) * shardSize);
                                    store.put({
                                        shardKey: `backup_shard_${i}`,
                                        index: i,
                                        data: slice
                                    });
                                    savedShards++;
                                }
                                tx.oncomplete = () => resolve(true);
                                tx.onerror = () => resolve(false);
                            } catch (e) {
                                resolve(false);
                            }
                        });
                    } catch (err) {}
                }

                return { savedChunks, savedShards };
            },

            /**
             * استرجاع وإعادة تجميع قاعدة البيانات من الكائنات الأصغر في IndexedDB في حال تلف أو فقدان localStorage
             */
            async restoreFromChunks() {
                const idb = await this.open();
                if (!idb) return null;
                return new Promise((resolve) => {
                    try {
                        const tx = idb.transaction(['db_chunks'], 'readonly');
                        const store = tx.objectStore('db_chunks');
                        const req = store.getAll();
                        req.onsuccess = () => {
                            const rows = req.result || [];
                            if (!rows.length) {
                                resolve(null);
                                return;
                            }
                            const restored = {};
                            rows.forEach(row => {
                                if (!row || !row.payload) return;
                                if (row.chunkId === 'chunk_attendance_behaviors' && row.compressed) {
                                    restored.records = this.decompressRecordObjects(row.payload.recordsCompact || []);
                                    restored.behaviors = row.payload.behaviors || {};
                                    restored.positiveBehaviors = row.payload.positiveBehaviors || [];
                                    if (row.payload.portfolioNotes) restored.portfolioNotes = row.payload.portfolioNotes;
                                    if (row.payload.portfolioTasks) restored.portfolioTasks = row.payload.portfolioTasks;
                                    if (row.payload.adminFollowUpSlips) restored.adminFollowUpSlips = row.payload.adminFollowUpSlips;
                                    if (row.payload.adminAuditTrail) restored.adminAuditTrail = row.payload.adminAuditTrail;
                                } else {
                                    const copyPayload = Object.assign({}, row.payload);
                                    if (copyPayload._extraKeys && typeof copyPayload._extraKeys === 'object') {
                                        Object.assign(restored, copyPayload._extraKeys);
                                        delete copyPayload._extraKeys;
                                    }
                                    Object.assign(restored, copyPayload);
                                }
                            });
                            resolve(Object.keys(restored).length > 0 ? restored : null);
                        };
                        req.onerror = () => resolve(null);
                    } catch (e) {
                        resolve(null);
                    }
                });
            }
        };
        window.MathPedagogicalSystemIDB = MathPedagogicalSystemIDB;

        // استرجاع تلقائي من كائنات IndexedDB المجزأة في حال كانت ذاكرة localStorage فارغة أو تعذر الوصول إليها
        (function autoRecoverFromIDBIfNeeded() {
            try {
                const rawLocal = localStorage.getItem('absence_massar_v8_manual');
                if (!rawLocal) {
                    MathPedagogicalSystemIDB.restoreFromChunks().then(restoredDb => {
                        if (restoredDb && restoredDb.classes && Object.keys(restoredDb.classes).length > 0) {
                            Object.assign(db, restoredDb);
                            window.db = db;
                            _recordsCacheDirty = true;
                            try {
                                localStorage.setItem('absence_massar_v8_manual', safeStringify(db));
                            } catch (e) {}
                            if (typeof updateClassSelect === 'function') updateClassSelect();
                            if (typeof renderStudents === 'function') renderStudents();
                            if (typeof updateStats === 'function') updateStats();
                            if (typeof renderHomeIconsLaunchpad === 'function') renderHomeIconsLaunchpad();
                        }
                    }).catch(() => {});
                }
            } catch (e) {}
        })();

        /**
         * تنظيف وضغط الكائنات في الذاكرة الحية (RAM) وإزالة السجلات اليتيمة والمكررة
         */
        function pruneAndOptimizeDatabaseInMemory(targetDb) {
            const report = {
                orphanedGradesRemoved: 0,
                duplicateRecordsRemoved: 0,
                orphanedRecordsRemoved: 0,
                orphanedBehaviorsRemoved: 0,
                transientKeysCleared: 0
            };
            if (!targetDb || typeof targetDb !== 'object') return report;

            try {
                const validClasses = new Set(Object.keys(targetDb.classes || {}));
                const validStudentIds = new Set();

                validClasses.forEach(clsName => {
                    const list = targetDb.classes[clsName];
                    if (Array.isArray(list)) {
                        list.forEach(st => {
                            if (st && st.id !== undefined && st.id !== null) {
                                validStudentIds.add(st.id);
                                validStudentIds.add(String(st.id));
                                // مسح أي خصائص كاش مؤقتة داخل كائن التلميذ
                                if ('_temp' in st) { delete st._temp; report.transientKeysCleared++; }
                                if ('_cache' in st) { delete st._cache; report.transientKeysCleared++; }
                            }
                        });
                    }
                });

                // 1. تنظيف نقط الأقسام أو التلاميذ المحذوفين
                if (targetDb.grades && typeof targetDb.grades === 'object') {
                    Object.keys(targetDb.grades).forEach(clsName => {
                        if (!validClasses.has(clsName)) {
                            delete targetDb.grades[clsName];
                            report.orphanedGradesRemoved++;
                            return;
                        }
                        const classGrades = targetDb.grades[clsName];
                        if (classGrades && typeof classGrades === 'object') {
                            const classStudentSet = new Set(
                                (targetDb.classes[clsName] || []).map(s => String(s.id))
                            );
                            Object.keys(classGrades).forEach(stId => {
                                if (!classStudentSet.has(String(stId))) {
                                    delete classGrades[stId];
                                    report.orphanedGradesRemoved++;
                                }
                            });
                        }
                    });
                }

                // 2. إزالة التكرار والسجلات اليتيمة من سجلات الغياب والتأخر (db.records)
                if (Array.isArray(targetDb.records) && targetDb.records.length > 0) {
                    const seenKeys = new Set();
                    const cleanRecords = [];
                    for (let i = 0; i < targetDb.records.length; i++) {
                        const rec = targetDb.records[i];
                        if (!rec || typeof rec !== 'object') continue;
                        if (rec.className && validClasses.size > 0 && !validClasses.has(rec.className)) {
                            report.orphanedRecordsRemoved++;
                            continue;
                        }
                        if (rec.studentId !== undefined && validStudentIds.size > 0 && !validStudentIds.has(rec.studentId) && !validStudentIds.has(String(rec.studentId))) {
                            report.orphanedRecordsRemoved++;
                            continue;
                        }
                        const dedupKey = `${rec.date || ''}|${rec.className || ''}|${rec.studentId || ''}|${rec.session || rec.time || ''}`;
                        if (seenKeys.has(dedupKey)) {
                            report.duplicateRecordsRemoved++;
                            continue;
                        }
                        seenKeys.add(dedupKey);
                        cleanRecords.push(rec);
                    }
                    if (cleanRecords.length !== targetDb.records.length) {
                        targetDb.records = cleanRecords;
                        _recordsCacheDirty = true;
                    }
                }

                // 3. تنظيف سجلات السلوك اليتيمة (كائن مفهرس بالقسم والتلميذ أو مصفوفة)
                if (targetDb.behaviors && typeof targetDb.behaviors === 'object' && validClasses.size > 0) {
                    if (Array.isArray(targetDb.behaviors)) {
                        const beforeLen = targetDb.behaviors.length;
                        targetDb.behaviors = targetDb.behaviors.filter(b => {
                            if (!b) return false;
                            if (b.studentId !== undefined && !validStudentIds.has(b.studentId) && !validStudentIds.has(String(b.studentId))) {
                                return false;
                            }
                            return true;
                        });
                        report.orphanedBehaviorsRemoved = beforeLen - targetDb.behaviors.length;
                    } else {
                        Object.keys(targetDb.behaviors).forEach(clsName => {
                            if (!validClasses.has(clsName)) {
                                delete targetDb.behaviors[clsName];
                                report.orphanedBehaviorsRemoved++;
                                return;
                            }
                            const clsBehaviors = targetDb.behaviors[clsName];
                            if (clsBehaviors && typeof clsBehaviors === 'object') {
                                const classStudentSet = new Set(
                                    (targetDb.classes[clsName] || []).map(s => String(s.id))
                                );
                                Object.keys(clsBehaviors).forEach(stId => {
                                    if (!classStudentSet.has(String(stId))) {
                                        delete clsBehaviors[stId];
                                        report.orphanedBehaviorsRemoved++;
                                    }
                                });
                            }
                        });
                    }
                }
            } catch (err) {}

            return report;
        }

        /**
         * الدالة الرئيسية لضغط وإدارة قواعد بيانات IndexedDB الحالية بشكل دوري وعند الخمول أو الخروج
         * لتقليل استهلاك الذاكرة وحفظ النسخ الاحتياطية في كائنات أصغر (Sharded Objects)
         */
        let _isIDBCompressionRunning = false;
        async function compressAndManageIndexedDB(options = {}) {
            if (_isIDBCompressionRunning) return null;
            _isIDBCompressionRunning = true;

            const opts = typeof options === 'string' ? { reason: options, silent: true } : (options || {});
            const reason = opts.reason || 'periodic';
            const silent = opts.silent !== false;
            const startTime = performance.now();

            const summary = {
                reason,
                timestamp: new Date().toISOString(),
                memoryPrune: null,
                whiteboardCompression: null,
                orphanedLibraryFilesRemoved: 0,
                shardedBackup: null,
                localStorageTempKeysRemoved: 0,
                durationMs: 0
            };

            try {
                // 1. تنقية وضغط كائن قاعدة البيانات في الذاكرة الحية (RAM)
                summary.memoryPrune = pruneAndOptimizeDatabaseInMemory(db);

                // 2. ضغط قاعدة بيانات السبورة التفاعلية (math_whiteboard_idb) وتحويل PNG إلى WebP وتقليص Undo/Redo
                if (typeof window.compressWhiteboardIndexedDB === 'function') {
                    summary.whiteboardCompression = await window.compressWhiteboardIndexedDB({
                        aggressive: reason === 'exit' || reason === 'idle' || reason === 'visibility_hidden'
                    });
                }

                // 3. تنظيف الملفات المحلية اليتيمة في قاعدة بيانات المكتبة (SchoolLibraryLocalFiles)
                if (window.ResourceDB && typeof window.ResourceDB.pruneOrphanedFiles === 'function') {
                    const validLibIds = new Set();
                    if (Array.isArray(db.library)) {
                        db.library.forEach(item => {
                            if (item && item.id) {
                                validLibIds.add(item.id);
                                validLibIds.add(String(item.id));
                            }
                        });
                    }
                    summary.orphanedLibraryFilesRemoved = await window.ResourceDB.pruneOrphanedFiles(validLibIds);
                }

                // 4. تقسيم وحفظ قاعدة البيانات في كائنات أصغر (Domain Chunks + Micro-Shards) داخل IndexedDB
                summary.shardedBackup = await MathPedagogicalSystemIDB.saveShardedBackup(db, {
                    reason,
                    createSnapshotShards: true
                });

                // 5. تنظيف المفاتيح المؤقتة والكاش الزائد من localStorage
                try {
                    const keysToRemove = [];
                    for (let i = 0; i < localStorage.length; i++) {
                        const k = localStorage.key(i);
                        if (k && k !== 'absence_massar_v8_manual' && (k.includes('_temp') || k.includes('_preview_cache') || k.includes('old_backup_'))) {
                            keysToRemove.push(k);
                        }
                    }
                    keysToRemove.forEach(k => localStorage.removeItem(k));
                    summary.localStorageTempKeysRemoved = keysToRemove.length;
                } catch (e) {}

                summary.durationMs = Math.round(performance.now() - startTime);
                window._lastIDBCompressionStats = summary;

                if (!silent && typeof showAppToast === 'function') {
                    const savedKb = summary.whiteboardCompression
                        ? Math.round((summary.whiteboardCompression.bytesSavedEstimate || 0) / 1024)
                        : 0;
                    showAppToast(
                        `تم ضغط قاعدة البيانات وتجزئة النسخة الاحتياطية (${summary.shardedBackup?.savedChunks || 8} كائنات مجال، توفير ${savedKb} KB) في ${summary.durationMs}ms.`,
                        'success'
                    );
                }
            } catch (err) {
                console.warn('IndexedDB compression & management warning:', err);
            } finally {
                _isIDBCompressionRunning = false;
            }

            return summary;
        }
        window.compressAndManageIndexedDB = compressAndManageIndexedDB;
        window.pruneAndOptimizeDatabaseInMemory = pruneAndOptimizeDatabaseInMemory;

        // جدولة الضبط الدوري، ومراقب التوقف عن النشاط (Idle Detector)، وحفظ الخروج
        (function setupDatabaseCompressionLifecycle() {
            const IDLE_THRESHOLD_MS = 90 * 1000; // 90 ثانية من التوقف عن النشاط
            const PERIODIC_COMPRESS_MS = 8 * 60 * 1000; // كل 8 دقائق بشكل دوري
            let idleCompressionTimer = null;
            let lastActivityThrottle = 0;

            function runWhenBrowserIdle(callback) {
                if (typeof window.requestIdleCallback === 'function') {
                    window.requestIdleCallback(() => callback(), { timeout: 4000 });
                } else {
                    setTimeout(callback, 120);
                }
            }

            function resetUserIdleTimer() {
                const now = Date.now();
                if (now - lastActivityThrottle < 4000) return;
                lastActivityThrottle = now;

                if (idleCompressionTimer) {
                    clearTimeout(idleCompressionTimer);
                }
                idleCompressionTimer = setTimeout(() => {
                    runWhenBrowserIdle(() => {
                        compressAndManageIndexedDB({ reason: 'idle', silent: true });
                    });
                }, IDLE_THRESHOLD_MS);
            }

            ['pointerdown', 'keydown', 'wheel', 'touchstart'].forEach(evtName => {
                window.addEventListener(evtName, resetUserIdleTimer, { passive: true });
            });
            resetUserIdleTimer();

            // تشغيل دوري كل 8 دقائق في الخلفية
            setInterval(() => {
                runWhenBrowserIdle(() => {
                    compressAndManageIndexedDB({ reason: 'periodic', silent: true });
                });
            }, PERIODIC_COMPRESS_MS);

            // عند إخفاء التبويب أو تصغير النافذة
            document.addEventListener('visibilitychange', () => {
                if (document.visibilityState === 'hidden') {
                    if (isDBSyncPending) {
                        performDBSave();
                    }
                    compressAndManageIndexedDB({ reason: 'visibility_hidden', silent: true });
                }
            });

            // عند إغلاق الصفحة أو الخروج
            window.addEventListener('pagehide', () => {
                if (isDBSyncPending) {
                    performDBSave();
                }
                compressAndManageIndexedDB({ reason: 'exit', silent: true });
            });
        })();

        function performDBSave() {
            isDBSyncPending = false;
            let localSuccess = false;
            try {
                if (typeof db === 'object' && db !== null) {
                    db._lastSavedAt = new Date().toISOString();
                    db._lastSavedTimestamp = Date.now();
                    db._lastSavedDevice = navigator.userAgent.includes('Mobile') ? 'هاتف محمول' : (navigator.userAgent.includes('Mac') ? 'جهاز Mac' : 'حاسوب');
                }
                const serialized = safeStringify(db);
                localStorage.setItem('absence_massar_v8_manual', serialized);
                if (db && db._lastSavedAt) {
                    localStorage.setItem('absence_massar_v8_last_saved_time', db._lastSavedAt);
                }
                localSuccess = true;
                lastSuccessfulSaveTime = new Date();
                // حفظ غير متزامن للكائنات المقسمة في IndexedDB دون حظر واجهة المستخدم
                MathPedagogicalSystemIDB.saveShardedBackup(db, {
                    reason: 'autosave',
                    createSnapshotShards: false
                }).catch(() => {});
            } catch (err) {
                console.error("Local storage save error:", err?.message || String(err));
                if (err && (err.name === 'QuotaExceededError' || err.name === 'NS_ERROR_DOM_QUOTA_REACHED' || err.code === 22)) {
                    // محاولة تفريغ الكاش الثانوي وضغط الذاكرة تلقائياً لإتمام الحفظ بأمان
                    try {
                        pruneAndOptimizeDatabaseInMemory(db);
                        const nonEssentialKeys = [];
                        for (let i = 0; i < localStorage.length; i++) {
                            const k = localStorage.key(i);
                            if (k && k !== 'absence_massar_v8_manual' && (k.includes('cache') || k.includes('preview') || k.includes('temp') || k.includes('whiteboard_snapshot') || k.includes('math_whiteboard_state'))) {
                                nonEssentialKeys.push(k);
                            }
                        }
                        nonEssentialKeys.forEach(k => localStorage.removeItem(k));
                        const retrySerialized = safeStringify(db);
                        localStorage.setItem('absence_massar_v8_manual', retrySerialized);
                        localSuccess = true;
                        lastSuccessfulSaveTime = new Date();
                        MathPedagogicalSystemIDB.saveShardedBackup(db, {
                            reason: 'quota_recovery',
                            createSnapshotShards: true
                        }).catch(() => {});
                    } catch (retryErr) {
                        // حتى لو امتلأ localStorage، نحفظ البيانات مجزأة في IndexedDB ذات السعة الكبيرة
                        MathPedagogicalSystemIDB.saveShardedBackup(db, {
                            reason: 'idb_fallback_on_quota',
                            createSnapshotShards: true
                        }).catch(() => {});
                        if (typeof showAppToast === 'function') {
                            showAppToast('تنبيه: امتلأت ذاكرة المتصفح السريعة؛ تم تأمين وحفظ بياناتك في قاعدة بيانات IndexedDB المجزأة.', 'warning');
                        }
                        notifyStudentAutoSave('local_synced', { time: new Date() });
                        return;
                    }
                } else {
                    notifyStudentAutoSave('error', { message: 'تعذر الحفظ في التخزين المحلي!' });
                    return;
                }
            }

            // Continuous background sync to Google Drive if authorized
            if (typeof window.autoSyncToGoogleDrive === 'function') {
                window.autoSyncToGoogleDrive(db);
            }

            const cloudActive = isCloudActive();
            if (window.syncToFirebase && cloudActive) {
                window.syncToFirebase(db).then((res) => {
                    if (res && res.success) {
                        notifyStudentAutoSave('cloud_synced', { time: res.timestamp || new Date() });
                    } else {
                        notifyStudentAutoSave('local_synced_cloud_failed', { 
                            time: lastSuccessfulSaveTime || new Date(),
                            error: res && res.error
                        });
                    }
                }).catch((e) => {
                    notifyStudentAutoSave('local_synced_cloud_failed', { 
                        time: lastSuccessfulSaveTime || new Date(),
                        error: e?.message || String(e)
                    });
                });
            } else if (localSuccess) {
                notifyStudentAutoSave('local_synced', { time: lastSuccessfulSaveTime });
            }
        }

        window.addEventListener('beforeunload', () => {
            if (isDBSyncPending) {
                performDBSave();
            }
            compressAndManageIndexedDB({ reason: 'beforeunload', silent: true });
        });

        window.saveDB = saveDB;
        function saveDB() {
            window.db = db;
            _recordsCacheDirty = true;
            if (activeTab === 'absence') updateStats();
            checkHomeworkAlerts();
            if (typeof checkLessonLogReminders === 'function') checkLessonLogReminders();
            if (typeof updateDashboardAlertBadges === 'function') updateDashboardAlertBadges();
            if (typeof renderHomeIconsLaunchpad === 'function') renderHomeIconsLaunchpad();
            
            try {
                window.dispatchEvent(new CustomEvent('dbUpdated', { detail: db }));
            } catch(e) {}

            notifyStudentAutoSave('saving');

            isDBSyncPending = true;
            if (saveDBTimeout) {
                clearTimeout(saveDBTimeout);
            }
            // Debounce for 400ms to improve UI responsiveness during rapid edits
            saveDBTimeout = setTimeout(performDBSave, 400);
        }
        var saveDb = saveDB;
        window.saveDb = saveDB;
        var saveData = saveDB;
