        // ============================================================
        // نظام وضع الطباعة المخصص لتقرير التلميذ الفردي (Print Mode - A4)
        // ============================================================
        function isStudentPrintModeEnabled() {
            return !!(typeof db !== 'undefined' && db && db.settings && db.settings.studentPrintMode === true);
        }
        window.isStudentPrintModeEnabled = isStudentPrintModeEnabled;

        function getStudentPrintModeOptions() {
            const s = (typeof db !== 'undefined' && db && db.settings) ? db.settings : {};
            const clampMargin = (val, def = 10) => {
                const n = Number(val);
                return Number.isFinite(n) ? Math.max(0, Math.min(30, Math.round(n))) : def;
            };
            return {
                officialHeader: s.printModeOptOfficialHeader !== false,
                progressChart: s.printModeOptProgressChart !== false,
                officialVisas: s.printModeOptOfficialVisas !== false,
                absenceChart: s.printModeOptAbsenceChart !== false,
                pageSize: s.printModePageSize === 'a5' ? 'a5' : 'a4',
                marginPreset: ['normal', 'narrow', 'minimal', 'wide', 'custom'].includes(s.printModeMarginsPreset)
                    ? s.printModeMarginsPreset
                    : 'normal',
                marginTop: clampMargin(s.printModeMarginTop, 10),
                marginBottom: clampMargin(s.printModeMarginBottom, 10),
                marginRight: clampMargin(s.printModeMarginRight, 10),
                marginLeft: clampMargin(s.printModeMarginLeft, 10)
            };
        }
        window.getStudentPrintModeOptions = getStudentPrintModeOptions;

        function getResolvedPrintModeMargins(optsArg) {
            const opts = optsArg || getStudentPrintModeOptions();
            const preset = opts.marginPreset || 'normal';
            let top = 10, right = 10, bottom = 10, left = 10, label = 'قياسية (10 مم)';
            if (preset === 'narrow') {
                top = 6; right = 6; bottom = 6; left = 6;
                label = 'ضيقة (6 مم)';
            } else if (preset === 'minimal') {
                top = 3; right = 4; bottom = 3; left = 4;
                label = 'مدمجة قصوى (3-4 مم)';
            } else if (preset === 'wide') {
                top = 15; right = 15; bottom = 15; left = 15;
                label = 'واسعة رسمية (15 مم)';
            } else if (preset === 'custom') {
                top = Number.isFinite(opts.marginTop) ? opts.marginTop : 10;
                bottom = Number.isFinite(opts.marginBottom) ? opts.marginBottom : 10;
                right = Number.isFinite(opts.marginRight) ? opts.marginRight : 10;
                left = Number.isFinite(opts.marginLeft) ? opts.marginLeft : 10;
                label = `مخصصة (${top}/${right}/${bottom}/${left} مم)`;
            }
            return {
                preset,
                top,
                right,
                bottom,
                left,
                // html2pdf / jsPDF 4-element margin order: [top, left, bottom, right]
                array: [top, left, bottom, right],
                cssPadding: `${top}mm ${right}mm ${bottom}mm ${left}mm`,
                label
            };
        }
        window.getResolvedPrintModeMargins = getResolvedPrintModeMargins;

        function resolveSelectedReportStudent() {
            const reportClassSelect = document.getElementById('reportClassSelect');
            const reportStudentSelect = document.getElementById('reportStudentSelect');
            const barClassSelect = document.getElementById('printModeClassSelect');
            const barStudentSelect = document.getElementById('printModeStudentSelect');

            let className = reportClassSelect ? reportClassSelect.value : '';
            let studentId = reportStudentSelect ? reportStudentSelect.value : '';

            if (className === '__ALL__' && studentId && studentId.includes(':::')) {
                const parts = studentId.split(':::');
                className = parts[0];
                studentId = parts[1];
            } else if (studentId && studentId.includes(':::')) {
                const parts = studentId.split(':::');
                if (!className || className === '__ALL__') className = parts[0];
                studentId = parts[1];
            }

            if ((!className || className === '__ALL__') && barClassSelect && barClassSelect.value) {
                className = barClassSelect.value;
            }
            if (!studentId && barStudentSelect && barStudentSelect.value) {
                studentId = barStudentSelect.value;
            }

            const classList = (className && typeof db !== 'undefined' && db && db.classes && Array.isArray(db.classes[className]))
                ? db.classes[className]
                : [];
            const std = classList.find(s => String(s.id) === String(studentId)) || null;
            return { className, studentId, std };
        }
        window.resolveSelectedReportStudent = resolveSelectedReportStudent;

        function applyPrintModePageSetupToDOM() {
            const opts = getStudentPrintModeOptions();
            const margins = getResolvedPrintModeMargins(opts);
            const sizeUpper = opts.pageSize === 'a5' ? 'A5' : 'A4';

            // Sync selectors in Print Mode Bar
            const barSizeSel = document.getElementById('printModePageSizeSelect');
            const barMarginSel = document.getElementById('printModeMarginsPresetSelect');
            const barCustomBox = document.getElementById('printModeCustomMarginsInline');
            const barTop = document.getElementById('printModeMarginTop');
            const barBottom = document.getElementById('printModeMarginBottom');
            const barRight = document.getElementById('printModeMarginRight');
            const barLeft = document.getElementById('printModeMarginLeft');

            if (barSizeSel) barSizeSel.value = opts.pageSize;
            if (barMarginSel) barMarginSel.value = opts.marginPreset;
            if (barCustomBox) barCustomBox.style.display = opts.marginPreset === 'custom' ? 'inline-flex' : 'none';
            if (barTop) barTop.value = opts.marginTop;
            if (barBottom) barBottom.value = opts.marginBottom;
            if (barRight) barRight.value = opts.marginRight;
            if (barLeft) barLeft.value = opts.marginLeft;

            // Sync selectors in Settings Card
            const setSizeSel = document.getElementById('settingsPrintModePageSize');
            const setMarginSel = document.getElementById('settingsPrintModeMarginsPreset');
            const setCustomRow = document.getElementById('settingsPrintModeCustomMarginsRow');
            const setTop = document.getElementById('settingsPrintMarginTop');
            const setBottom = document.getElementById('settingsPrintMarginBottom');
            const setRight = document.getElementById('settingsPrintMarginRight');
            const setLeft = document.getElementById('settingsPrintMarginLeft');

            if (setSizeSel) setSizeSel.value = opts.pageSize;
            if (setMarginSel) setMarginSel.value = opts.marginPreset;
            if (setCustomRow) setCustomRow.style.display = opts.marginPreset === 'custom' ? 'grid' : 'none';
            if (setTop) setTop.value = opts.marginTop;
            if (setBottom) setBottom.value = opts.marginBottom;
            if (setRight) setRight.value = opts.marginRight;
            if (setLeft) setLeft.value = opts.marginLeft;

            // Apply live CSS variables & classes for WYSIWYG preview in Print Mode
            document.body.classList.toggle('print-mode-size-a5', opts.pageSize === 'a5');
            document.documentElement.style.setProperty('--print-mode-margin-top', `${margins.top}mm`);
            document.documentElement.style.setProperty('--print-mode-margin-right', `${margins.right}mm`);
            document.documentElement.style.setProperty('--print-mode-margin-bottom', `${margins.bottom}mm`);
            document.documentElement.style.setProperty('--print-mode-margin-left', `${margins.left}mm`);

            // Update badge and action button labels
            const badgeText = document.getElementById('printModeBarBadgeText');
            if (badgeText) {
                badgeText.textContent = `وضع الطباعة المخصص (Print Mode - ${sizeUpper})`;
            }
            const printBtnLabel = document.getElementById('printModeDirectPrintBtnLabel');
            if (printBtnLabel) {
                printBtnLabel.textContent = `طباعة الورقة (${sizeUpper}) الآن`;
            }
            const exportPdfBtnLabel = document.getElementById('printModeExportPdfBtnLabel');
            if (exportPdfBtnLabel) {
                exportPdfBtnLabel.textContent = `تصدير PDF (${sizeUpper} · ${margins.label})`;
            }
        }
        window.applyPrintModePageSetupToDOM = applyPrintModePageSetupToDOM;

        function onPrintModePageSetupChange(source) {
            if (!db.settings) db.settings = {};
            const clampMargin = (val, def = 10) => {
                const n = Number(val);
                return Number.isFinite(n) ? Math.max(0, Math.min(30, Math.round(n))) : def;
            };

            if (source === 'bar') {
                const barSizeSel = document.getElementById('printModePageSizeSelect');
                const barMarginSel = document.getElementById('printModeMarginsPresetSelect');
                const barTop = document.getElementById('printModeMarginTop');
                const barBottom = document.getElementById('printModeMarginBottom');
                const barRight = document.getElementById('printModeMarginRight');
                const barLeft = document.getElementById('printModeMarginLeft');

                if (barSizeSel) db.settings.printModePageSize = barSizeSel.value === 'a5' ? 'a5' : 'a4';
                if (barMarginSel) db.settings.printModeMarginsPreset = barMarginSel.value;
                if (barTop) db.settings.printModeMarginTop = clampMargin(barTop.value, 10);
                if (barBottom) db.settings.printModeMarginBottom = clampMargin(barBottom.value, 10);
                if (barRight) db.settings.printModeMarginRight = clampMargin(barRight.value, 10);
                if (barLeft) db.settings.printModeMarginLeft = clampMargin(barLeft.value, 10);
            } else {
                const setSizeSel = document.getElementById('settingsPrintModePageSize');
                const setMarginSel = document.getElementById('settingsPrintModeMarginsPreset');
                const setTop = document.getElementById('settingsPrintMarginTop');
                const setBottom = document.getElementById('settingsPrintMarginBottom');
                const setRight = document.getElementById('settingsPrintMarginRight');
                const setLeft = document.getElementById('settingsPrintMarginLeft');

                if (setSizeSel) db.settings.printModePageSize = setSizeSel.value === 'a5' ? 'a5' : 'a4';
                if (setMarginSel) db.settings.printModeMarginsPreset = setMarginSel.value;
                if (setTop) db.settings.printModeMarginTop = clampMargin(setTop.value, 10);
                if (setBottom) db.settings.printModeMarginBottom = clampMargin(setBottom.value, 10);
                if (setRight) db.settings.printModeMarginRight = clampMargin(setRight.value, 10);
                if (setLeft) db.settings.printModeMarginLeft = clampMargin(setLeft.value, 10);
            }

            saveDB();
            applyPrintModePageSetupToDOM();
            if (typeof updateStudentProgressChart === 'function') {
                updateStudentProgressChart();
            }
            if (typeof showAppToast === 'function') {
                const opts = getStudentPrintModeOptions();
                const m = getResolvedPrintModeMargins(opts);
                showAppToast(
                    `تم ضبط إعدادات التقرير الفردي: حجم ${opts.pageSize.toUpperCase()} · هوامش ${m.label}`,
                    'info'
                );
            }
        }
        window.onPrintModePageSetupChange = onPrintModePageSetupChange;

        function ensureStudentSelectedForPrintMode() {
            const reportClassSelect = document.getElementById('reportClassSelect');
            const reportStudentSelect = document.getElementById('reportStudentSelect');
            if (!reportClassSelect || !reportStudentSelect) return;

            const classNames = Object.keys((db && db.classes) || {}).filter(c => Array.isArray(db.classes[c]) && db.classes[c].length > 0);
            if (classNames.length === 0) return;

            let currentClass = reportClassSelect.value;
            if (!currentClass || currentClass === '__ALL__' || !db.classes[currentClass] || db.classes[currentClass].length === 0) {
                currentClass = classNames[0];
                reportClassSelect.value = currentClass;
                if (typeof generateReport === 'function') {
                    generateReport();
                }
            }

            if (!reportStudentSelect.value && db.classes[currentClass] && db.classes[currentClass].length > 0) {
                const firstStudent = db.classes[currentClass][0];
                if (firstStudent && firstStudent.id) {
                    reportStudentSelect.value = firstStudent.id;
                }
            }
        }

        function syncPrintModeControlBarSelectors() {
            const barClassSelect = document.getElementById('printModeClassSelect');
            const barStudentSelect = document.getElementById('printModeStudentSelect');
            const reportClassSelect = document.getElementById('reportClassSelect');
            const reportStudentSelect = document.getElementById('reportStudentSelect');
            if (!barClassSelect || !barStudentSelect) return;

            const classNames = (typeof getSortedClassNames === 'function')
                ? getSortedClassNames()
                : Object.keys((db && db.classes) || {});

            let activeClass = reportClassSelect ? reportClassSelect.value : '';
            let activeStudent = reportStudentSelect ? reportStudentSelect.value : '';
            if (activeClass === '__ALL__' && activeStudent && activeStudent.includes(':::')) {
                const parts = activeStudent.split(':::');
                activeClass = parts[0];
                activeStudent = parts[1];
            }
            if ((!activeClass || activeClass === '__ALL__') && classNames.length > 0) {
                activeClass = classNames[0];
            }

            barClassSelect.innerHTML = '';
            classNames.forEach(cls => {
                const opt = document.createElement('option');
                opt.value = cls;
                opt.textContent = cls;
                if (cls === activeClass) opt.selected = true;
                barClassSelect.appendChild(opt);
            });

            barStudentSelect.innerHTML = '';
            const students = (activeClass && db && db.classes && db.classes[activeClass]) ? db.classes[activeClass] : [];
            if (students.length === 0) {
                const emptyOpt = document.createElement('option');
                emptyOpt.value = '';
                emptyOpt.textContent = '-- لا يوجد تلاميذ --';
                barStudentSelect.appendChild(emptyOpt);
            } else {
                students.forEach(std => {
                    const opt = document.createElement('option');
                    opt.value = std.id;
                    opt.textContent = `${std.orderNum ? std.orderNum + ' - ' : ''}${std.name}`;
                    if (String(std.id) === String(activeStudent)) opt.selected = true;
                    barStudentSelect.appendChild(opt);
                });
            }
        }
        window.syncPrintModeControlBarSelectors = syncPrintModeControlBarSelectors;

        function onPrintModeClassSelectChange(newClass) {
            if (!newClass) return;
            const reportClassSelect = document.getElementById('reportClassSelect');
            const reportStudentSelect = document.getElementById('reportStudentSelect');
            if (reportClassSelect) {
                reportClassSelect.value = newClass;
                if (typeof generateReport === 'function') {
                    generateReport();
                }
            }
            if (reportStudentSelect && (!reportStudentSelect.value) && db.classes && db.classes[newClass] && db.classes[newClass].length > 0) {
                reportStudentSelect.value = db.classes[newClass][0].id;
            }
            syncPrintModeControlBarSelectors();
            if (typeof updateStudentProgressChart === 'function') {
                updateStudentProgressChart();
            }
        }
        window.onPrintModeClassSelectChange = onPrintModeClassSelectChange;

        function onPrintModeStudentSelectChange(newStudentId) {
            const reportClassSelect = document.getElementById('reportClassSelect');
            const reportStudentSelect = document.getElementById('reportStudentSelect');
            const barClassSelect = document.getElementById('printModeClassSelect');
            if (reportClassSelect && barClassSelect && reportClassSelect.value !== barClassSelect.value) {
                reportClassSelect.value = barClassSelect.value;
                if (typeof generateReport === 'function') {
                    generateReport();
                }
            }
            if (reportStudentSelect) {
                reportStudentSelect.value = newStudentId;
            }
            if (typeof updateStudentProgressChart === 'function') {
                updateStudentProgressChart();
            }
        }
        window.onPrintModeStudentSelectChange = onPrintModeStudentSelectChange;

        function navigatePrintModeStudent(direction) {
            const barStudentSelect = document.getElementById('printModeStudentSelect');
            if (!barStudentSelect || barStudentSelect.options.length === 0) return;
            let nextIdx = barStudentSelect.selectedIndex + (direction >= 0 ? 1 : -1);
            if (nextIdx < 0) nextIdx = barStudentSelect.options.length - 1;
            if (nextIdx >= barStudentSelect.options.length) nextIdx = 0;
            barStudentSelect.selectedIndex = nextIdx;
            onPrintModeStudentSelectChange(barStudentSelect.value);
        }
        window.navigatePrintModeStudent = navigatePrintModeStudent;

        function syncPrintModeUIStateInSettings(enabled) {
            const isEnabled = !!enabled;
            const toggle = document.getElementById('settingsPrintModeToggle');
            if (toggle) toggle.checked = isEnabled;

            const statusBadge = document.getElementById('printModeToggleStatusBadge');
            if (statusBadge) {
                if (isEnabled) {
                    statusBadge.textContent = 'مفعل ✓';
                    statusBadge.style.background = '#ccfbf1';
                    statusBadge.style.color = '#0f766e';
                    statusBadge.style.borderColor = '#5eead4';
                } else {
                    statusBadge.textContent = 'معطل ✕';
                    statusBadge.style.background = '#f1f5f9';
                    statusBadge.style.color = '#64748b';
                    statusBadge.style.borderColor = '#cbd5e1';
                }
            }

            const opts = getStudentPrintModeOptions();
            const chkHeader = document.getElementById('printModeOptOfficialHeader');
            const chkChart = document.getElementById('printModeOptProgressChart');
            const chkVisas = document.getElementById('printModeOptOfficialVisas');
            const chkAbsChart = document.getElementById('printModeOptAbsenceChart');
            if (chkHeader) chkHeader.checked = opts.officialHeader;
            if (chkChart) chkChart.checked = opts.progressChart;
            if (chkVisas) chkVisas.checked = opts.officialVisas;
            if (chkAbsChart) chkAbsChart.checked = opts.absenceChart;

            applyPrintModePageSetupToDOM();

            const headerCheck = document.getElementById('headerPrintModeCheck');
            if (headerCheck) {
                headerCheck.textContent = isEnabled ? 'مفعل ✓' : '';
            }

            const quickBtn = document.getElementById('btnToggleStudentPrintMode');
            const quickBtnText = document.getElementById('btnToggleStudentPrintModeText');
            if (quickBtn && quickBtnText) {
                if (isEnabled) {
                    quickBtn.style.background = 'linear-gradient(135deg, #be123c, #e11d48)';
                    quickBtnText.textContent = 'إنهاء وضع الطباعة المخصص';
                } else {
                    quickBtn.style.background = 'linear-gradient(135deg, #0f766e, #0d9488)';
                    quickBtnText.textContent = 'وضع الطباعة المخصص (Print Mode)';
                }
            }

            document.body.classList.toggle('student-print-mode', isEnabled);
            const controlBar = document.getElementById('studentPrintModeControlBar');
            if (controlBar) {
                controlBar.style.display = isEnabled ? 'flex' : 'none';
            }

            if (isEnabled) {
                if (typeof switchTab === 'function') {
                    const reportsView = document.getElementById('reportsView');
                    if (reportsView && !reportsView.classList.contains('active')) {
                        switchTab('reports');
                    }
                }
                ensureStudentSelectedForPrintMode();
                syncPrintModeControlBarSelectors();
                const progressCard = document.getElementById('studentProgressCard');
                if (progressCard) progressCard.style.display = 'block';
            }

            if (typeof updateStudentProgressChart === 'function') {
                updateStudentProgressChart();
            }
            if (window.renderLucide) window.renderLucide();
        }
        window.syncPrintModeUIStateInSettings = syncPrintModeUIStateInSettings;

        function onPrintModeToggleChange(checked) {
            if (!db.settings) db.settings = {};
            db.settings.studentPrintMode = !!checked;
            saveDB();
            syncPrintModeUIStateInSettings(!!checked);
            if (typeof showAppToast === 'function') {
                const opts = getStudentPrintModeOptions();
                showAppToast(
                    checked
                        ? `تم تفعيل وضع الطباعة المخصص (Print Mode - ${opts.pageSize.toUpperCase()}) وتنسيق تقرير التلميذ للطباعة والتصدير`
                        : 'تم إغلاق وضع الطباعة المخصص والعودة للواجهة الكاملة',
                    checked ? 'success' : 'info'
                );
            }
        }
