        function triggerDirectA4StudentPrint() {
            ensureStudentSelectedForPrintMode();
            updateStudentProgressChart();
            const printArea = document.getElementById('printBehaviorArea');
            if (!printArea) {
                if (typeof showAppToast === 'function') {
                    showAppToast('المرجو اختيار القسم والتلميذ أولاً لطباعة التقرير الفردي', 'warning');
                }
                return;
            }
            const opts = getStudentPrintModeOptions();
            const margins = getResolvedPrintModeMargins(opts);
            const sizeUpper = opts.pageSize === 'a5' ? 'A5' : 'A4';

            // Clone printBehaviorArea and ensure print mode sections match current options
            const clone = printArea.cloneNode(true);
            clone.querySelectorAll('.no-print, button, .student-normal-mode-banner').forEach(el => el.remove());
            const headerInClone = clone.querySelector('.student-print-official-header');
            if (headerInClone) {
                headerInClone.style.display = opts.officialHeader ? 'block' : 'none';
            }
            const chartInClone = clone.querySelector('.student-print-inline-chart-box');
            if (chartInClone) {
                chartInClone.style.display = opts.progressChart ? 'block' : 'none';
            }
            const visasInClone = clone.querySelector('.student-print-visas-section');
            if (visasInClone) {
                visasInClone.style.display = opts.officialVisas ? 'block' : 'none';
            }

            document.body.classList.add('printing-student-report');
            if (typeof window.printDocumentDirectly === 'function') {
                window.printDocumentDirectly(clone.outerHTML, `التقرير الفردي للتلميذ - ${sizeUpper}`, {
                    orientation: 'portrait',
                    pageSize: sizeUpper,
                    margins: margins
                });
                setTimeout(() => {
                    document.body.classList.remove('printing-student-report');
                }, 1200);
            } else {
                window.print();
                setTimeout(() => {
                    document.body.classList.remove('printing-student-report');
                }, 1200);
            }
        }
        window.triggerDirectA4StudentPrint = triggerDirectA4StudentPrint;

