        window.renderAttendanceCardsLivePreview = renderAttendanceCardsLivePreview;

        function updateAttendanceStatusCardLive(statusKey, hex) {
            const theme = getAttendanceStatusColorTheme(statusKey);
            const card = document.getElementById(`attendanceColorCard_${statusKey}`);
            if (card) {
                card.style.borderRight = `4px solid ${theme.solid}`;
                const badge = document.getElementById(`attendanceColorBadge_${statusKey}`);
                if (badge) {
                    badge.style.background = theme.bg;
                    badge.style.color = theme.text;
                    badge.style.borderColor = theme.border;
                }
                const mini = document.getElementById(`attendanceMiniPreview_${statusKey}`);
                if (mini) {
                    mini.style.background = theme.bg;
                    mini.style.borderColor = theme.border;
                    mini.style.borderRight = `4px solid ${theme.solid}`;
                }
                const miniBtn = document.getElementById(`attendanceMiniBtn_${statusKey}`);
                if (miniBtn) {
                    miniBtn.style.background = theme.solid;
                }
                card.querySelectorAll('.class-color-swatch-dot').forEach(btn => {
                    const title = btn.getAttribute('title') || '';
                    btn.classList.toggle('active', title.toLowerCase() === hex.toLowerCase());
                });
            }

            const input = document.getElementById(`color_status_${statusKey}`);
            if (input && input.value.toLowerCase() !== hex.toLowerCase()) {
                input.value = hex;
            }

            const hexLabel = document.getElementById(`attendanceColorHex_${statusKey}`);
            if (hexLabel) {
                hexLabel.textContent = hex;
            }

            renderAttendanceCardsLivePreview();
        }

