        function handleHomeIconsSearch(query) {
            const q = (query || '').trim().toLowerCase();
            const resultsBox = document.getElementById('homeSearchResultsBox');
            const resultsGrid = document.getElementById('homeSearchResultsGrid');
            const queryEcho = document.getElementById('homeSearchQueryEcho');
            const countEl = document.getElementById('homeSearchResultsCount');
            const clearBtn = document.getElementById('homeIconsSearchClear');

            if (!resultsBox || !resultsGrid) return;

            if (clearBtn) clearBtn.style.display = q ? 'inline-block' : 'none';

            if (!q || q.length < 2) {
                resultsBox.style.display = 'none';
                return;
            }

            // Gather all tools from all clusters
            const allTools = [];
            Object.values(HOME_CLUSTERS_DATA).forEach(cl => {
                cl.items.forEach(it => {
                    allTools.push({ ...it, clusterTitle: cl.title });
                });
            });

            const matched = allTools.filter(t => {
                return t.title.toLowerCase().includes(q) ||
                       t.desc.toLowerCase().includes(q) ||
                       t.clusterTitle.toLowerCase().includes(q) ||
                       t.key.toLowerCase().includes(q);
            });

            if (queryEcho) queryEcho.textContent = query;
            if (countEl) countEl.textContent = `${matched.length} نتيجة`;

            if (matched.length === 0) {
                resultsGrid.innerHTML = `
                    <div style="width: 100%; padding: 12px; text-align: center; color: #64748b; font-size: 0.8rem; font-weight: 600;">
                        لم يتم العثور على أي وحدة تطابق "${query}". جرب كلمة أخرى مثل: نقط، غياب، نصوص، ذكاء، جدول...
                    </div>
                `;
            } else {
                resultsGrid.innerHTML = matched.map(m => `
                    <button type="button" onclick="${m.action}; clearHomeIconsSearch();" style="background: #f8fafc; border: 1.5px solid #cbd5e1; border-radius: 10px; padding: 6px 12px; display: inline-flex; align-items: center; gap: 8px; cursor: pointer; font-family: inherit; transition: all 0.18s ease; text-align: right;" onmouseover="this.style.background='#eff6ff'; this.style.borderColor='#3b82f6'; this.style.transform='translateY(-1px)';" onmouseout="this.style.background='#f8fafc'; this.style.borderColor='#cbd5e1'; this.style.transform='translateY(0)';">
                        <span style="color: ${m.color}; display: inline-flex;"><span data-lucide="${m.icon}" data-size="14"></span></span>
                        <div style="display: flex; flex-direction: column; text-align: right;">
                            <span style="font-size: 0.8rem; font-weight: 800; color: #0f172a;">${m.title}</span>
                            <span style="font-size: 0.68rem; color: #64748b;">${m.clusterTitle}</span>
                        </div>
                        <span style="margin-right: 6px; color: #2563eb; display: inline-flex;"><span data-lucide="arrow-left" data-size="12"></span></span>
                    </button>
                `).join('');
            }

            resultsBox.style.display = 'block';
            if (window.renderLucide) window.renderLucide(resultsBox);
        }
        window.handleHomeIconsSearch = handleHomeIconsSearch;

        function clearHomeIconsSearch() {
            const input = document.getElementById('homeIconsSearchInput');
            if (input) input.value = '';
            const clearBtn = document.getElementById('homeIconsSearchClear');
            if (clearBtn) clearBtn.style.display = 'none';
            const resultsBox = document.getElementById('homeSearchResultsBox');
            if (resultsBox) resultsBox.style.display = 'none';
        }
        window.clearHomeIconsSearch = clearHomeIconsSearch;

        function renderHomeIconsLaunchpad() {
            try {
                const classKeys = Object.keys((typeof db !== 'undefined' && db && db.classes) || {});
                const activeClassKeys = classKeys.filter(c => !(db.archivedClasses && (Array.isArray(db.archivedClasses) ? db.archivedClasses.includes(c) : db.archivedClasses[c])));
                const classCount = activeClassKeys.length;
                let studentCount = 0;
                activeClassKeys.forEach(c => {
                    const clsData = db.classes[c];
                    if (Array.isArray(clsData)) {
                        studentCount += clsData.length;
                    } else if (clsData && Array.isArray(clsData.students)) {
                        studentCount += clsData.students.length;
                    }
                });
                const cEl = document.getElementById('homeClassCountText');
                if (cEl) cEl.textContent = `الأقسام: ${classCount} مسجلة`;
                const sEl = document.getElementById('homeStudentsCountText');
                if (sEl) sEl.textContent = `التلاميذ: ${studentCount} تلميذ`;

                // Sync view mode (defaults to 'grouped' for single screen)
                const savedMode = (function() {
                    try { return localStorage.getItem('math_app_home_view_mode') || 'grouped'; }
                    catch(e) { return 'grouped'; }
                })();
                setHomeViewMode(savedMode);

                // Sync alert badges if any
                const homeDashBadge = document.getElementById('homeDashBadge');
                const homeDashBadgeGrouped = document.getElementById('homeDashBadgeGrouped');
                if (homeDashBadge && homeDashBadgeGrouped) {
                    homeDashBadgeGrouped.textContent = homeDashBadge.textContent;
                    homeDashBadgeGrouped.style.display = homeDashBadge.style.display;
                }

                if (typeof renderRecentlyAccessed === 'function') {
                    renderRecentlyAccessed();
                }

                if (window.renderLucide) window.renderLucide();
            } catch(e) {
                console.error("renderHomeIconsLaunchpad error:", e);
            }
        }

