        function recordRecentAccess(key) {
            if (!key || key === 'home') return;
            const meta = RECENT_MODULE_META[key];
            if (!meta) return;

            try {
                let list = JSON.parse(localStorage.getItem('teacher_recent_access') || '[]');
                list = list.filter(item => item.key !== key);
                list.unshift({
                    key: key,
                    name: meta.name,
                    icon: meta.icon,
                    bg: meta.bg,
                    timestamp: Date.now()
                });
                list = list.slice(0, 4);
                localStorage.setItem('teacher_recent_access', JSON.stringify(list));
            } catch (e) {
                console.warn('Could not record recent access', e);
            }
        }
        window.recordRecentAccess = recordRecentAccess;

        function renderRecentlyAccessed() {
            const section = document.getElementById('homeRecentlyAccessedSection');
            const grid = document.getElementById('homeRecentlyAccessedGrid');
            if (!section || !grid) return;

            let list = [];
            try {
                list = JSON.parse(localStorage.getItem('teacher_recent_access') || '[]');
            } catch (e) {
                list = [];
            }

            if (!Array.isArray(list) || list.length === 0) {
                section.style.display = 'none';
                return;
            }

            section.style.display = 'block';
            grid.innerHTML = list.map(item => {
                const clickHandler = item.key === 'teachingMode'
                    ? "toggleInteractiveTeachingMode()"
                    : item.key.startsWith('settings:')
                        ? `openTeacherSettings('${item.key.split(':')[1]}')`
                        : `switchTab('${item.key}')`;

                return `
                    <button type="button" class="recent-access-card" onclick="${clickHandler}" title="${item.name}">
                        <div class="recent-access-icon" style="background: ${item.bg};">
                            <span data-lucide="${item.icon}" data-size="18"></span>
                        </div>
                        <div class="recent-access-info">
                            <span class="recent-access-name">${item.name}</span>
                            <span class="recent-access-time">مستخدم مؤخراً</span>
                        </div>
                        <span class="recent-access-arrow">
                            <span data-lucide="arrow-left" data-size="14"></span>
                        </span>
                    </button>
                `;
            }).join('');

            if (window.renderLucide) window.renderLucide(grid);
        }
        window.renderRecentlyAccessed = renderRecentlyAccessed;

        function clearRecentlyAccessed() {
            try {
                localStorage.removeItem('teacher_recent_access');
            } catch (e) {}
            const section = document.getElementById('homeRecentlyAccessedSection');
            if (section) section.style.display = 'none';
        }
