            if (typeof closeTabletReport === "function") closeTabletReport();
            if (window.renderLucide) window.renderLucide();
            setTimeout(() => { if (window.renderLucide) window.renderLucide(); }, 50);
            activeTab = tab;
            window.activeTab = tab;
            updateActiveTabHeroBanner(tab);

            // ضمان الحصر التام لكافة التنبيهات المنبثقة داخل تبويب التقويم فقط
