        /* --- دوال التمرير الناعم والتحكم في شريط التنقل المثبت --- */
        function scrollToHomeSection(targetId) {
            if (activeTab !== 'absence') {
                switchTab('absence');
            }
            const target = document.getElementById(targetId);
            if (!target) return;

            // حساب الإزاحة مع مراعاة شريط التنقل المثبت في الأعلى
            const navTabs = document.querySelector('.nav-tabs');
            const navHeight = navTabs ? navTabs.offsetHeight : 54;
            const extraOffset = 10;

            const targetRect = target.getBoundingClientRect();
            const absoluteTargetTop = targetRect.top + window.pageYOffset;
            const scrollToY = Math.max(0, absoluteTargetTop - navHeight - extraOffset);

            window.scrollTo({
                top: scrollToY,
                behavior: 'smooth'
            });

            // تحديث الزر النشط في شريط أقسام الصفحة
            document.querySelectorAll('.section-nav-pill').forEach(pill => {
                pill.classList.toggle('active', pill.getAttribute('data-target') === targetId);
            });

            // وميض تأكيد بصري خفيف على القسم المنتقل إليه
            target.classList.add('section-highlight-pulse');
            setTimeout(() => {
                target.classList.remove('section-highlight-pulse');
            }, 1200);
        }

        function scrollToTop() {
            window.scrollTo({
                top: 0,
                behavior: 'smooth'
            });
        }

        // مراقبة التمرير لتثبيت شريط التنقل، إظهار زر الرجوع للأعلى، وتحديث القسم الحالي
        window.addEventListener('scroll', function() {
            const scrollY = window.pageYOffset || document.documentElement.scrollTop;

            // تثبيت شريط التنقل وإبراز ظله
            const navTabs = document.querySelector('.nav-tabs');
            if (navTabs) {
                if (scrollY > 30) {
                    navTabs.classList.add('is-sticky');
                } else {
                    navTabs.classList.remove('is-sticky');
                }
            }

            // إظهار أو إخفاء زر العودة إلى الأعلى
            const btnScrollTop = document.getElementById('btnScrollToTop');
            if (btnScrollTop) {
                if (scrollY > 250) {
                    btnScrollTop.classList.add('visible');
                } else {
                    btnScrollTop.classList.remove('visible');
                }
            }

            // تتبع القسم النشط في الصفحة الرئيسية تلقائياً أثناء التمرير
            if (activeTab === 'absence') {
                const sections = [
                    { id: 'todayScheduleBlock', pill: 'todayScheduleBlock' },
                    { id: 'classConfigSection', pill: 'classConfigSection' },
                    { id: 'statsBarView', pill: 'statsBarView' },
                    { id: 'quickActionsBar', pill: 'quickActionsBar' },
                    { id: 'alertsSectionAnchor', pill: 'alertsSectionAnchor' },
                    { id: 'studentsSectionAnchor', pill: 'studentsSectionAnchor' }
                ];

                const navHeight = navTabs ? navTabs.offsetHeight : 54;
                let currentPillTarget = '';

                for (let i = sections.length - 1; i >= 0; i--) {
                    const el = document.getElementById(sections[i].id);
                    if (el && el.style.display !== 'none') {
                        const rect = el.getBoundingClientRect();
                        if (rect.top <= navHeight + 90) {
                            currentPillTarget = sections[i].pill;
                            break;
                        }
                    }
                }

                if (currentPillTarget) {
                    document.querySelectorAll('.section-nav-pill').forEach(pill => {
                        pill.classList.toggle('active', pill.getAttribute('data-target') === currentPillTarget);
                    });
                }
            }
        }, { passive: true });


        
