        // Notes Logic
        // ============================================
        function refreshNotesClassDropdown() {
            const select = document.getElementById('notesClassSelect');
            if(!select) return;
            const currentVal = select.value;
            select.innerHTML = '<option value="">-- اختر القسم --</option>';
            const sorted = getSortedClasses(true);
            sorted.forEach(cName => {
                const opt = document.createElement('option');
                opt.value = cName;
                opt.textContent = cName;
                select.appendChild(opt);
            });
            if (db.classes[currentVal]) select.value = currentVal;
            refreshNotesStudentDropdown();
        }

        
        // --- Homework Agenda Logic ---
        function renderHomeworkAgenda() {
            const className = document.getElementById('notesClassSelect').value;
            const card = document.getElementById('hwAgendaCard');
            if (!className) {
                if (card) card.style.display = 'none';
                return;
            }
            
            if (card) card.style.display = 'block';
            const list = document.getElementById('hwAgendaList');
            if (!list) return;
            list.innerHTML = '';
            
            if (!db.homeworkAgenda) db.homeworkAgenda = {};
            if (!db.homeworkAgenda[className]) db.homeworkAgenda[className] = [];
            
            let agendas = db.homeworkAgenda[className];
            if (agendas.length === 0) {
                list.innerHTML = '<div style="color: #888; font-size: 0.85rem; text-align: center;">لا توجد مواعيد مجدولة لهذا القسم.</div>';
            } else {
                agendas.sort((a, b) => new Date(a.date) - new Date(b.date)).forEach(item => {
                    const today = new Date();
                    today.setHours(0,0,0,0);
                    const itemDate = new Date(item.date);
                    
                    const diffTime = itemDate - today;
                    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
                    
                    let statusColor = '#333';
                    let statusLabel = '';
                    
                    if (diffDays < 0) {
                        statusColor = 'var(--danger)';
                        statusLabel = '(فات الموعد)';
                    } else if (diffDays === 0) {
                        statusColor = 'var(--warning-dark)';
                        statusLabel = '(اليوم!)';
                    } else if (diffDays <= 2) {
                        statusColor = 'var(--warning-dark)';
                        statusLabel = '(قريباً)';
                    } else {
                        statusColor = 'var(--success-dark)';
                    }
                    
                    const div = document.createElement('div');
                    div.style.cssText = 'background: white; border: 1px solid #e9d5ff; border-radius: 6px; padding: 10px; display: flex; justify-content: space-between; align-items: center; box-shadow: 0 1px 2px rgba(0,0,0,0.05);';
                    div.innerHTML = `
                        <div>
                            <div style="font-weight: bold; color: var(--purple); font-size: 0.9rem;">${item.title}</div>
                            <div style="font-size: 0.8rem; color: ${statusColor}; font-weight: bold;"><span class="ui-icon">${lucideIcon('calendar', {size: 11})}</span> ${item.date} ${statusLabel}</div>
                        </div>
                        <button onclick="deleteHomeworkAgenda('${className}', '${item.id}')" style="background: none; border: none; color: var(--danger); cursor: pointer; font-size: 0.85rem; padding: 4px;" title="حذف الموعد">${lucideIcon('trash2', {size: 12})}</button>
                    `;
                    list.appendChild(div);
                });
            }
        }
        
        let _isAddingHomeworkAgenda = false;
        function addHomeworkAgenda() {
            if (_isAddingHomeworkAgenda) return;
            const className = document.getElementById('notesClassSelect').value;
            const title = document.getElementById('hwAgendaTitle').value.trim();
            const date = document.getElementById('hwAgendaDate').value;
            
            if (!className) {
                alert('الرجاء اختيار القسم أولاً');
                return;
            }
            if (!title || !date) {
                alert('الرجاء إدخال وصف الموعد وتاريخه');
                return;
            }

            _isAddingHomeworkAgenda = true;
            const unlock = () => { setTimeout(() => { _isAddingHomeworkAgenda = false; }, 400); };
            
            if (!db.homeworkAgenda) db.homeworkAgenda = {};
            if (!db.homeworkAgenda[className]) db.homeworkAgenda[className] = [];
            
            db.homeworkAgenda[className].push({
                id: Date.now().toString(),
                title,
                date
            });
            
            saveDB();
            document.getElementById('hwAgendaTitle').value = '';
            document.getElementById('hwAgendaDate').value = '';
            renderHomeworkAgenda();
            checkHomeworkAlerts(); // update home screen alerts
            unlock();
        }
        
        function deleteHomeworkAgenda(className, id) {
            if (confirm('هل أنت متأكد من حذف هذا الموعد؟')) {
                db.homeworkAgenda[className] = db.homeworkAgenda[className].filter(i => i.id !== id);
                saveDB();
                renderHomeworkAgenda();
                checkHomeworkAlerts();
            }
        }
        
        function checkHomeworkAlerts() {
            const container = document.getElementById('agendaHwAlertContainer');
            if (!container) return;
            
            let alertsHtml = '';
            const today = new Date();
            today.setHours(0,0,0,0);
            
            if (db.homeworkAgenda) {
                for (const className in db.homeworkAgenda) {
                    const classItem = db.classes[className] ? className : null;
                    if (!classItem) continue; // skip if class doesn't exist anymore
                    
                    db.homeworkAgenda[className].forEach(item => {
                        const alertId = `${className}_${(item.title || 'hw').replace(/[^a-zA-Z0-9_\u0600-\u06FF]/g, '_')}_${item.date}`;
                        if (db.hiddenAlerts && db.hiddenAlerts['agendaHw_global_' + alertId]) {
                            return;
                        }

                        const itemDate = new Date(item.date);
                        const diffTime = itemDate - today;
                        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
                        
                        if (diffDays >= 0 && diffDays <= 2) {
                            // Upcoming or today
                            let alertColor = diffDays === 0 ? '#dc2626' : '#d97706';
                            let bg = diffDays === 0 ? '#fef2f2' : '#fffbeb';
                            let borderCol = diffDays === 0 ? '#fca5a5' : '#fde68a';
                            let emojiIcon = diffDays === 0 ? lucideIcon('alertoctagon', {size: 13}) : (diffDays === 1 ? lucideIcon('clock', {size: 13}) : lucideIcon('timer', {size: 13}));
                            let label = diffDays === 0 ? 'اليوم' : (diffDays === 1 ? 'غداً' : 'بعد غد');
                            const escapedTitle = (item.title || '').replace(/'/g, "\\'").replace(/"/g, '&quot;');
                            
                            const clsTheme = getClassColorTheme(classItem);
                            alertsHtml += `
                                <div id="alert-item-agendaHw-${alertId}" class="alert-item-card" style="background: ${bg}; border: 1px solid ${borderCol}; border-right: 5px solid ${clsTheme.solid}; margin-bottom: 8px;">
                                    <div class="alert-item-content">
                                        <div class="alert-item-emoji" style="background: white; border: 1px solid ${borderCol}; color: ${alertColor};">
                                            <span>${emojiIcon}</span>
                                        </div>
                                        <div class="alert-item-info">
                                            <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">
                                                <span class="class-color-badge" style="background: ${clsTheme.bg}; color: ${clsTheme.text}; border: 1px solid ${clsTheme.border}; font-size: 0.76rem; padding: 2px 8px;">
                                                    <span class="class-color-dot" style="background: ${clsTheme.solid};"></span>
                                                    ${classItem}
                                                </span>
                                                <strong style="color: ${alertColor}; font-size: 0.92rem;">موعد استحقاق واجب</strong>
                                                <span class="alert-item-badge" style="background: white; color: ${alertColor}; border: 1px solid ${borderCol}; font-size: 0.72rem;">
                                                    ${label}
                                                </span>
                                            </div>
                                            <div style="font-size: 0.82rem; color: #475569; margin-top: 2px;">
                                                ${item.title} <span style="color: #94a3b8;">(${item.date})</span>
                                            </div>
                                        </div>
                                    </div>
                                    <div style="display: flex; align-items: center; gap: 6px;">
                                        <button type="button" class="btn-primary" onclick="switchTab('notes'); document.getElementById('notesClassSelect').value = '${className}'; onNotesClassChange();" style="background: ${alertColor}; font-size: 0.75rem; padding: 5px 10px; border-radius: 6px; width: auto; margin: 0;">التفاصيل</button>
                                        <button type="button" class="btn-hide-single-alert" onclick="hideSingleAlert('agendaHw', '${alertId}', 'global', '${escapedTitle}')" title="إخفاء هذا التنبيه">
                                            <span>${lucideIcon('eyeoff', {size: 11})}</span> إخفاء
                                        </button>
                                    </div>
                                </div>
                            `;
                        }
                    });
                }
            }
            
            if (alertsHtml) {
                container.innerHTML = alertsHtml;
                container.style.display = 'block';
            } else {
                container.style.display = 'none';
                container.innerHTML = '';
            }
        }

        function onNotesClassChange() {
            incrementClassUsage(document.getElementById('notesClassSelect').value);
            currentNotesStudentFilter = null;
            refreshNotesStudentDropdown();
            refreshNotesStudentFilter();
            renderNotes();
            onNotesStudentSelectChange();
        }

        let currentNotesStudentFilter = null;
        let currentSmartRemarkAlternatives = [];
        let currentSmartRemarkIndex = 0;

        function refreshNotesStudentFilter() {
            const className = document.getElementById('notesClassSelect').value;
            const container = document.getElementById('notesStudentFilter');
            const card = document.getElementById('notesFilterCard');
            const countLabel = document.getElementById('notesFilteredStudentCount');
            if (!container || !card) return;
            
            if (!className || !db.classes[className] || db.classes[className].length === 0) {
                card.style.display = 'none';
                return;
            }
            
            card.style.display = 'block';
            if (countLabel) countLabel.textContent = `(${db.classes[className].length} تلميذ)`;
            
            let html = '<button class="nav-tab ' + (currentNotesStudentFilter === null ? 'active' : '') + '" style="padding: 4px 12px; font-size: 0.85rem; border: 1px solid var(--border); border-radius: 16px; min-width: max-content; background: ' + (currentNotesStudentFilter === null ? 'var(--primary)' : 'var(--bg)') + '; color: ' + (currentNotesStudentFilter === null ? 'white' : 'var(--text-muted)') + ';" onclick="setNotesStudentFilter(null)">الكل</button>';
            
            db.classes[className].forEach(std => {
                const isActive = currentNotesStudentFilter === std.id;
                html += '<button class="nav-tab ' + (isActive ? 'active' : '') + '" style="padding: 4px 12px; font-size: 0.85rem;" onclick="setNotesStudentFilter(\'' + std.id + '\')">' + (std.orderNum ? std.orderNum + '. ' : '') + std.name + '</button>';
            });
            
            container.innerHTML = html;
        }
        
        function setNotesStudentFilter(studentId) {
            currentNotesStudentFilter = studentId;
            refreshNotesStudentFilter();
            renderNotes();
        }

        function refreshNotesStudentDropdown() {
            const className = document.getElementById('notesClassSelect').value;
            const select = document.getElementById('notesStudentSelect');
            if (!select) return;
            select.innerHTML = '<option value="">-- ملاحظة عامة للقسم --</option>';
            if (className && db.classes[className]) {
                db.classes[className].forEach(std => {
                    const opt = document.createElement('option');
                    opt.value = std.id;
                    opt.textContent = (std.orderNum ? std.orderNum + '. ' : '') + std.name + (std.massar ? ' (' + std.massar + ')' : '');
                    select.appendChild(opt);
                });
            }
        }

        // =========================================================================
        // محرك التحليل والتركيب البيداغوجي للملاحظات الذكية (Pedagogical Engine)
        // يحلل المواظبة (الغياب/التأخر) + السلوك والواجبات + نقط التحصيل والمعدلات
        // =========================================================================
        function getStudentPedagogicalProfile(className, studentId) {
            if (!className || !studentId || !db.classes[className]) return null;
            const student = db.classes[className].find(s => s.id === studentId);
            if (!student) return null;

            // 1. سجلات المواظبة والغياب
            const records = (db.records || []).filter(r => r.className === className && r.studentId === studentId);
            let absentHours = 0;
            let unexcusedHours = 0;
            let lateCount = 0;
            let missedHw = 0;

            records.forEach(r => {
                const dur = parseFloat(r.duration || r.hours) || 1;
                if (r.status === 'غائب') {
                    absentHours += dur;
                    unexcusedHours += dur;
                } else if (r.status === 'مبرر') {
                    absentHours += dur;
                } else if (r.status === 'متأخر') {
                    lateCount++;
                }
                if (r.homework === 'لم ينجز') {
                    missedHw++;
                }
            });

            // دعم دالة تتبع الواجبات الإضافية إن وجدت
            if (typeof getTotalMissedHomework === 'function') {
                try {
                    const extraMissed = getTotalMissedHomework(studentId, className);
                    if (extraMissed > missedHw) missedHw = extraMissed;
                } catch(e) {}
            }

            // 2. السلوك والانضباط
            const behaviorData = (db.behaviors && db.behaviors[className] && db.behaviors[className][studentId]) 
                ? db.behaviors[className][studentId] 
                : { status: 'منضبط', note: '' };
            const behaviorStatus = behaviorData.status || 'منضبط';
            const behaviorNote = behaviorData.note || '';

            // 3. النقط والتحصيل الدراسي + مؤشر تطور الأداء الرياضي (Indice de Progression)
            const activeSem = window.activeSemester || 's1';
            const gradesObj = (db.grades && db.grades[className] && db.grades[className][studentId]) 
                ? db.grades[className][studentId] 
                : {};
            let avg = null;
            if (typeof calculateStudentAvg === 'function') {
                try {
                    avg = calculateStudentAvg(gradesObj, className, activeSem);
                } catch(e) {
                    console.warn(e);
                }
            }

            const progression = (typeof calculateStudentProgressionIndex === 'function')
                ? calculateStudentProgressionIndex(className, studentId, activeSem)
                : { level: 'insufficient', slope: 0, delta: null, marks: [], sequenceText: '-', label: 'غير متوفر', badge: '-', color: '#64748b', bg: '#f8fafc', border: '#cbd5e1' };

            // تصنيف التحصيل الدراسي
            let academicLevel = 'no_grade';
            if (avg !== null && !isNaN(avg)) {
                if (avg >= 16) academicLevel = 'excellence'; // امتياز
                else if (avg >= 14) academicLevel = 'very_good'; // حسن جداً
                else if (avg >= 12) academicLevel = 'good'; // حسن
                else if (avg >= 10) academicLevel = 'average'; // متوسط / مقبول
                else if (avg >= 8) academicLevel = 'struggling'; // قريب من العتبة / متعثر
                else academicLevel = 'critical'; // تعثر حاد
            }

            // تصنيف المواظبة
            let attendanceLevel = 'excellent';
            if (absentHours > 6 || unexcusedHours >= 4) attendanceLevel = 'severe';
            else if (absentHours >= 3 || lateCount >= 3) attendanceLevel = 'warning';
            else if (absentHours > 0 || lateCount > 0) attendanceLevel = 'acceptable';

            // تصنيف الانضباط
            let disciplineLevel = 'regular';
            if (behaviorStatus === 'متميز') disciplineLevel = 'model';
            else if (behaviorStatus === 'مشوش' || behaviorStatus === 'تنبيه' || behaviorStatus === 'إنذار') disciplineLevel = 'disruptive';
            else if (missedHw >= 2) disciplineLevel = 'hw_neglect';

            return {
                student,
                name: student.name,
                orderNum: student.orderNum || '',
                massar: student.massar || '',
                absentHours,
                unexcusedHours,
                lateCount,
                missedHw,
                behaviorStatus,
                behaviorNote,
                avg,
                academicLevel,
                attendanceLevel,
                disciplineLevel,
                progression
            };
        }
        window.getStudentPedagogicalProfile = getStudentPedagogicalProfile;

        // توليد الملاحظات البيداغوجية المتنوعة وفق الأنماط الرسمية المعتمدة ومؤشر تطور الأداء الرياضي
        function generatePedagogicalRemarks(profile, style = 'balanced') {
            if (!profile) {
                return {
                    primary: 'ملاحظة عامة للقسم: الحرص على المراجعة الدورية وإنجاز الأنشطة المنزلية في مواعيدها.',
                    alternatives: ['تفاعل إيجابي مع الحث على مضاعفة الجهد.'],
                    strengths: [],
                    recommendations: []
                };
            }

            const { name, avg, academicLevel, attendanceLevel, disciplineLevel, absentHours, unexcusedHours, lateCount, missedHw, behaviorStatus, progression } = profile;
            const progLevel = progression ? progression.level : 'insufficient';
            const progSeq = (progression && progression.sequenceText && progression.sequenceText !== '-') ? ` (${progression.sequenceText})` : '';
            const isUpward = (progLevel === 'strong_up' || progLevel === 'steady_up');
            const isDownward = (progLevel === 'sharp_down' || progLevel === 'slight_down');

            let primary = '';
            let alternatives = [];
            let strengths = [];
            let recommendations = [];
            let tag = 'توجيه بيداغوجي';
            let color = '#2563eb';

            // 1. تحديد نقاط القوة والتوصيات (شاملة لمؤشر التطور الرياضي)
            if (academicLevel === 'excellence' || academicLevel === 'very_good') strengths.push('تحصيل دراسي ممتاز واستيعاب متقدم للمفاهيم الرياضية');
            else if (academicLevel === 'good') strengths.push('نتائج طيبة وقدرات استيعابية مشجعة');
            
            if (isUpward) strengths.push(`تطور إيجابي متصاعد في نتائج الفروض المحروسة${progSeq}`);
            if (attendanceLevel === 'excellent') strengths.push('مواظبة تامة وانعدام كلي للغياب');
            if (disciplineLevel === 'model') strengths.push('سلوك قدوة ومشاركة بناءة داخل الفصل');
            else if (disciplineLevel === 'regular') strengths.push('انضباط حسن واحترام لضوابط القسم');

            if (isDownward) recommendations.push(`تدارك التراجع المسجل في الفروض الأخيرة${progSeq} وتكثيف التمرن`);
            if (attendanceLevel === 'severe' || attendanceLevel === 'warning') recommendations.push('وجوب الحضور المنتظم وتجنب الغياب غير المبرر');
            if (missedHw > 0) recommendations.push('الحرص على الإنجاز الدقيق للواجبات والتمارين المنزلية');
            if (academicLevel === 'struggling' || academicLevel === 'critical') recommendations.push('الاستفادة من حصص الدعم الاستدراكي ومراجعة القواعد الأساسية');
            if (disciplineLevel === 'disruptive') recommendations.push('مطلوب مزيد من الهدوء وتفادي تشتيت الانتباه أثناء الشرح');

            // 2. صياغة الملاحظة حسب المستوى الدراسي + مؤشر تطور الأداء + المواظبة والسلوك
            if (academicLevel === 'excellence') {
                tag = 'امتياز وتنويه 🌟';
                color = '#059669';
                if (disciplineLevel === 'disruptive' || missedHw >= 2) {
                    primary = 'نتائج ممتازة وقدرات رياضية عالية، إلا أنه يُرجى إيلاء مزيد من العناية لإنجاز الواجبات المنزلية والحرص على الهدوء التام داخل الفصل.';
                    alternatives = [
                        'تحصيل ممتاز وتفوق باهر، مع ضرورة الالتزام بإنجاز كافة التطبيقات المنزلية في وقتها.',
                        'نتائج مشرفة وقدرات واعدة؛ التزام أكبر بالانضباط الصفي سيضمن استمرار هذا التألق.'
                    ];
                } else if (isUpward) {
                    primary = `تفوق باهر ومسار تصاعدي متميز في الفروض${progSeq} يعكس جدية فائقة ومواظبة نموذجية. هنيئاً مع متمنياتنا بدوام التألق.`;
                    alternatives = [
                        'عمل جاد ومثمر ونسق تصاعدي مشرف في مادة الرياضيات. تلميذ(ة) قدوة ومواظب(ة).',
                        'لوحة شرف وتنويه: ارتقاء مستمر في الأداء وتمكن متين من الكفايات الرياضية المستهدفة.'
                    ];
                } else {
                    primary = 'نتائج ممتازة تعكس جدية فائقة ومواظبة نموذجية وسلوكاً قدوة داخل الفصل. هنيئاً مع متمنياتنا بدوام التميز والتألق.';
                    alternatives = [
                        'عمل جاد ومثمر ونتائج باهرة. تلميذ(ة) متألق(ة) ومواظب(ة)، نرجو له(ا) مستقبلاً مشرقاً.',
                        'تحصيل ممتاز وتفاعل إيجابي مستمر مع احترام كامل لضوابط القسم، واصل(ي) على هذا التميز.',
                        'لوحة شرف وتنويه: تمكن متين من الكفايات المستهدفة وأخلاق عالية ومواظبة تامة.'
                    ];
                }
            } else if (academicLevel === 'very_good') {
                tag = 'حسن جداً وتشجيع 📈';
                color = '#0284c7';
                if (isUpward) {
                    primary = `مستوى حسن جداً وتطور تصاعدي لافت في الفروض${progSeq}. مثابرة ممتازة ومواظبة طيبة؛ واصل(ي) على هذا النسق لبلوغ قمة الامتياز.`;
                    alternatives = [
                        'ارتقاء مستمر ونتائج مرضية جداً تعكس اجتهاداً متزايداً واستيعاباً متيناً للمفاهيم.',
                        'تلميذ(ة) مجد(ة) وفي تحسن متواصل، خطوة واحدة تفصلك عن مراتب الامتياز.'
                    ];
                } else if (isDownward) {
                    primary = `مستوى عام حسن جداً، غير أنه سُجل تراجع نسبي في الفرض الأخير${progSeq}؛ يُرجى استعادة التركيز المعهود للحفاظ على التفوق.`;
                    alternatives = [
                        'قدرات عالية ومستوى جيد جداً، مع ضرورة تدارك الانخفاض الطفيف في آخر فرض بمزيد من التمرن.',
                        'نتائج طيبة جداً تتطلب تثبيت النسق وتفادي التراخي لضمان البقاء ضمن المتفوقين.'
                    ];
                } else {
                    primary = 'مستوى حسن جداً ونتائج مشجعة ومثمرة. مشاركة إيجابية ومواظبة طيبة؛ واصل(ي) على هذا النهج لتحقيق الامتياز.';
                    alternatives = [
                        'عمل جاد ونتائج مرضية جداً، مع إمكانية بلوغ مراتب التفوق بمزيد من التركيز والتعمق.',
                        'تلميذ(ة) مجد(ة) ومواظب(ة)، نتائج حسنة جداً تعكس جهداً ملموساً واستيعاباً موفقاً للمفاهيم.',
                        'تحصيل جيد جداً وانضباط ملحوظ داخل الفصل، نثمن هذه النتائج ونحث على الاستمرار.'
                    ];
                }
            } else if (academicLevel === 'good') {
                tag = isUpward ? 'تطور ملحوظ وتشجيع 📈' : (isDownward ? 'حسن مع تنبيه للتراجع ↘' : 'حسن وحث على التعمق 👍');
                color = isUpward ? '#059669' : (isDownward ? '#d97706' : '#1d4ed8');
                if (isUpward) {
                    primary = `مستوى حسن وتطور إيجابي ملموس من فرض لآخر${progSeq}؛ نثمن هذا المجهود المتصاعد ونحث على مواصلة حل التمارين لبلوغ التميز.`;
                    alternatives = [
                        'منحى تصاعدي مشجع جداً في النتائج يعكس رغبة أكيدة في التحسن، واصل(ي) بنفس العزيمة.',
                        'تحسن تدريجي ومثمر في استيعاب دروس الرياضيات؛ مزيد من التطبيقات سيتوج هذا التطور بالتفوق.'
                    ];
                } else if (isDownward) {
                    primary = `مستوى حسن إجمالاً، لكن يُلاحظ تراجع في نتائج الفروض الأخيرة${progSeq}؛ يلزم تدارك الأمر فوراً ومضاعفة التركيز والتمارين.`;
                    alternatives = [
                        'انطلاقة طيبة أعقبها انخفاض في الأداء؛ نوصي بمراجعة الدروس بانتظام وإنجاز الواجبات لاستعادة النسق.',
                        'إمكانيات حسنة تحتاج إلى يقظة وتدارك التراجع المسجل في الفرض الأخير قبل نهاية الدورة.'
                    ];
                } else if (missedHw > 1) {
                    primary = 'مستوى حسن وتطور ملحوظ في التحصيل، ينبغي فقط الحرص على إنجاز الواجبات والتمارين التطبيقية باستمرار.';
                    alternatives = [
                        'نتائج طيبة ومشجعة يعيق اكتمالها بعض التهاون في الواجبات المنزلية، مطلوب مزيد من الجدية.',
                        'مستوى حسن؛ الاجتهاد في إعداد التمارين مسبقاً سيمكن من الارتقاء إلى درجات التميز.'
                    ];
                } else {
                    primary = 'مستوى حسن ونتائج طيبة ومشجعة. تلميذ(ة) مواظب(ة) وقادر(ة) على تحقيق الأفضل ببذل مزيد من التركيز.';
                    alternatives = [
                        'مشاركة مقبولة وانضباط حسن، يُرجى تدعيم التحصيل بمزيد من التطبيقات المعمقة في المنزل.',
                        'تحصيل حسن ونتائج مرضية تعكس مجهوداً طيباً؛ الحث مستمر على تطوير الأداء نحو الأفضل.'
                    ];
                }
            } else if (academicLevel === 'average') {
                tag = isUpward ? 'تحسن مشجع وتنويه بالمجهود 📈' : (isDownward ? 'تراجع مقلق وحاجة للتدارك 📉' : 'متوسط وحث على مضاعفة الجهد ⚖️');
                color = isUpward ? '#059669' : (isDownward ? '#dc2626' : '#d97706');
                if (isUpward) {
                    primary = `تطور إيجابي لافت في نتائج الفروض${progSeq} يبرهن على جدية التلميذ(ة) ورغبته(ا) في تجاوز الصعوبات. تنويه بالمجهود وحث على الاستمرار.`;
                    alternatives = [
                        `معدل متوسط لكنه مدعوم بمنحى تصاعدي ممتاز${progSeq}؛ واصل(ي) هذا العمل الجاد للوصول إلى نتائج متقدمة.`,
                        'مجهود واضح أثمر تحسناً تدريجياً ملموساً من فرض لآخر؛ نوصي بتثبيت هذا النسق الإيجابي.'
                    ];
                } else if (isDownward) {
                    primary = `رغم استيفاء المعدل، يُسجل تراجع مقلق ومستمر في نتائج الفروض${progSeq}؛ يتطلب الأمر يقظة عاجلة وتكثيف المراجعة وحل التمارين.`;
                    alternatives = [
                        `انخفاض تدريجي في النقط${progSeq} ينذر بالتعثر؛ وجوب تدارك النقص فوراً والالتزام بالواجبات المنزلية.`,
                        'مستوى في تراجع مقارنة ببداية الدورة؛ يلزم مضاعفة الجهد والتركيز داخل الفصل لاستعادة التوازن.'
                    ];
                } else if (absentHours >= 3) {
                    primary = 'مستوى متوسط ومقبول؛ يؤثر كثرة الغياب على نسق استيعاب الدروس. وجوب المواظبة الصارمة وتفادي الغياب.';
                    alternatives = [
                        'نتائج متوسطة تحتاج للمواظبة وتدارك الدروس الفائتة فوراً لتفادي تراكم الصعوبات.',
                        'قدرات طيبة يحد منها الغياب المتكرر؛ نوصي بالحضور المنتظم والتركيز داخل الفصل.'
                    ];
                } else {
                    primary = 'مستوى متوسط ومقبول. تلميذ(ة) يملك إمكانيات واعدة، يتطلب التحصيل مضاعفة الجهد والمواظبة على حل التمارين بانتظام.';
                    alternatives = [
                        'نتائج متوسطة تحتاج إلى تدعيم من خلال تنظيم أوقات المراجعة وتفادي التراخي في حل التمارين.',
                        'جهد ملموس لكن التحصيل ما زال دون القدرات الحقيقية؛ مطلوب مزيد من التركيز وتطوير منهجية العمل.'
                    ];
                }
            } else if (academicLevel === 'struggling') {
                tag = isUpward ? 'بداية تحسن وحث على المثابرة ↗' : 'تنبيه وحاجة للدعم 🛠️';
                color = isUpward ? '#0284c7' : '#ea580c';
                if (isUpward) {
                    primary = `رغم أن المعدل دون العتبة، إلا أن هناك تحسناً ملموساً في الفرض الأخير${progSeq}؛ نشجع هذا المجهود ونوصي بمواصلة الدعم الاستدراكي لتجاوز التعثر.`;
                    alternatives = [
                        'بداية إيجابية لتجاوز الصعوبات وتطور مشجع في النقط؛ مزيد من المثابرة وحل التمارين سيضمن استيفاء المعدل.',
                        'مجهود ملحوظ للارتقاء بالمستوى؛ يوصى بتكثيف التمارين الأساسية والانخراط في حصص الدعم.'
                    ];
                } else if (isDownward) {
                    primary = `تعثر دراسي مصحوب بتراجع مقلق في الفروض${progSeq}؛ يستوجب الانخراط الفوري في حصص الدعم التربوي ومراجعة القواعد الأساسية بجدية.`;
                    alternatives = [
                        'نتائج في انخفاض مستمر دون العتبة؛ يلزم تدارك الأمر بحزم ومتابعة أسرية دقيقة للواجبات والدروس.',
                        'تراكم للصعوبات وتراجع في الأداء؛ نوصي بحضور منتظم ومضاعفة العمل المنزلي لتفادي تفاقم التعثر.'
                    ];
                } else if (absentHours >= 4 || unexcusedHours >= 2) {
                    primary = 'نتائج دون المستوى المطلوب تعزى بالأساس إلى تكرار الغياب وتراكم التعثرات. وجوب المواظبة الصارمة والانخراط الفوري في الدعم الاستدراكي.';
                    alternatives = [
                        'كثرة الغياب تؤثر سلباً ومباشرة على التحصيل؛ مطلوب الحضور المستمر وتدارك الحصص لتجاوز التعثر.',
                        'مستوى مقلق يتطلب تبرير الغياب والالتزام الصارم بالحضور والاستفادة من حصص الدعم.'
                    ];
                } else if (missedHw >= 2) {
                    primary = 'تعثر في التحصيل ناتج عن إهمال إنجاز الواجبات المنزلية والتمارين التطبيقية. يلزم تدارك الأمر بجدية ومتابعة أسرية مستمرة.';
                    alternatives = [
                        'نتائج دون العتبة بسبب قلة التمرن وإهمال الواجبات؛ نوصي بالمواظبة على حل السلاسل والتمارين.',
                        'مستوى ضعيف نسبياً؛ لا بد من مراجعة الدروس بانتظام وإنجاز الواجبات المنزلية بمسؤولية.'
                    ];
                } else {
                    primary = 'تلميذ(ة) خلوق(ة) ومنضبط(ة)، غير أن النتائج دون المأمول. يُوصى بالتركيز على الدعم البيداغوجي وتكثيف حل التمارين لتجاوز الصعوبات.';
                    alternatives = [
                        'مستوى دون العتبة يتطلب استدراكاً عاجلاً ومراجعة منتظمة للمفاهيم الأساسية بمساعدة الأستاذ والأسرة.',
                        'يحتاج إلى مضاعفة الجهد ومتابعة دقيقة داخل الفصل وخارجه لرفع المستوى قبل الامتحانات القادمة.'
                    ];
                }
            } else if (academicLevel === 'critical') {
                tag = 'إنذار تربوي عاجل ⚠️';
                color = '#dc2626';
                if (isUpward) {
                    primary = `تعثر حاد مع تسجيل بادرة تحسن في الفرض الأخير${progSeq}؛ يلزم مضاعفة الجهد بشكل مكثف والانخراط في خطة دعم فردية عاجلة.`;
                } else {
                    primary = 'إنذار تربوي: تعثر دراسي حاد يستدعي تداركاً عاجلاً ويقظة تربوية وتواصلاً مستمراً مع الأسرة للوقوف على أسباب التعثر ومعالجتها.';
                }
                alternatives = [
                    'نتائج مقلقة جداً؛ يستوجب الأمر وضع خطة دعم فردية عاجلة ومواظبة تامة بدون انقطاع لتفادي الرسوب.',
                    'ضعف حاد في التحصيل وتراكم للصعوبات؛ مطلوب الحزم وتحمل المسؤولية وتكثيف المراجعة فوراً.'
                ];
            } else {
                // حالة عدم تسجيل نقط فروض بعد
                tag = 'ملاحظة مواظبة وسلوك 📋';
                color = '#6366f1';
                if (absentHours >= 4) {
                    primary = 'تكرار الغياب يؤثر على سير التعلمات، يرجى تبرير الغياب والالتزام بالحضور المنتظم لضمان حسن الاستيعاب.';
                    alternatives = [
                        'وجوب المواظبة الصارمة وتفادي التأخرات؛ الحضور المنتظم شرط أساسي للنجاح الدراسي.',
                        'مواظبة غير منتظمة؛ يُرجى من الأسرة الكريمة متابعة حضور التلميذ(ة) والتواصل مع الإدارة.'
                    ];
                } else if (disciplineLevel === 'disruptive') {
                    primary = 'تلميذ(ة) حاضر(ة) ومشارك(ة)، لكن يُرجى الحفاظ على الهدوء داخل الفصل وتجنب التشويش على الزملاء.';
                    alternatives = [
                        'مطلوب مزيد من الانضباط والتركيز أثناء الشرح لتوفير بيئة تعليمية مناسبة للجميع.',
                        'تفاعل جيد يعيبه أحياناً تشتت الانتباه؛ نوصي بالهدوء وحسن الاستماع.'
                    ];
                } else {
                    primary = 'تلميذ(ة) منضبط(ة) ومواظب(ة) داخل الفصل ومشارك(ة) في بناء الدرس. نرجو له(ا) كامل التوفيق في الفروض التقويمية القادمة.';
                    alternatives = [
                        'سلوك حسن ومواظبة نموذجية وتفاعل طيب مع التوجيهات التربوية، واصل(ي).',
                        'انضباط مثالي وحرص على متابعة الدروس باهتمام وجدية.'
                    ];
                }
            }

            // تطبيق نمط الصياغة المطلوب (موجز لمسار / توجيهي / شامل) مع مراعاة مؤشر التطور
            if (style === 'concise') {
                if (academicLevel === 'excellence') {
                    primary = isUpward ? 'تفوق باهر وتطور مستمر في الأداء، تلميذ(ة) قدوة.' : 'عمل ممتاز ونتائج باهرة، تلميذ(ة) قدوة ومواظب(ة).';
                } else if (academicLevel === 'very_good') {
                    primary = isUpward ? 'مستوى حسن جداً وتطور متصاعد مشرف، واصل(ي).' : (isDownward ? 'مستوى حسن جداً، يرجى تدارك التراجع الطفيف الأخير.' : 'مستوى حسن جداً، عمل جاد ومواظبة طيبة، واصل(ي).');
                } else if (academicLevel === 'good') {
                    primary = isUpward ? 'مستوى حسن وتطور إيجابي ملموس، واصل(ي) الاجتهاد.' : (isDownward ? 'مستوى حسن، يلزم تدارك التراجع في الفرض الأخير.' : 'مستوى حسن ومشجع، قادر(ة) على الأفضل بمزيد من التركيز.');
                } else if (academicLevel === 'average') {
                    primary = isUpward ? 'تحسن تدريجي مشجع في النتائج، واصل(ي) بنفس العزيمة.' : (isDownward ? 'تراجع مقلق في الفروض الأخيرة، يلزم مضاعفة الجهد فوراً.' : 'مستوى متوسط ومقبول، يحتاج لمضاعفة الجهد وحل التمارين.');
                } else if (academicLevel === 'struggling') {
                    primary = isUpward ? 'بداية تحسن مشجعة، يوصى بمواصلة الدعم لتجاوز التعثر.' : 'نتائج دون المأمول، يوصى بالدعم الاستدراكي والمواظبة التامة.';
                } else if (academicLevel === 'critical') {
                    primary = 'تعثر حاد، يستدعي تداركاً عاجلاً ومتابعة دقيقة مع الأسرة.';
                } else {
                    primary = 'تلميذ(ة) منضبط(ة) ومواظب(ة) داخل الفصل، واصل(ي).';
                }
            } else if (style === 'guidance') {
                if (recommendations.length > 0) {
                    primary += ' • توصيات بيداغوجية: ' + recommendations.join('، ') + '.';
                }
            }

            return {
                primary,
                alternatives,
                strengths,
                recommendations,
                tag,
                color
            };
        }
        window.generatePedagogicalRemarks = generatePedagogicalRemarks;

        // عند تغيير اختيار التلميذ في حقل التدوين
        function onNotesStudentSelectChange() {
            const className = document.getElementById('notesClassSelect').value;
            const studentId = document.getElementById('notesStudentSelect').value;
            const profileCard = document.getElementById('studentPedagogicalProfileCard');
            const smartBox = document.getElementById('smartRemarkBox');
            
            if (!className || !studentId) {
                if (profileCard) profileCard.style.display = 'none';
                if (smartBox) smartBox.style.display = 'none';
                return;
            }

            const profile = getStudentPedagogicalProfile(className, studentId);
            if (!profile) return;

            // عرض بطاقة الملف البيداغوجي المدمج
            if (profileCard) {
                profileCard.style.display = 'block';
                const nameEl = document.getElementById('pedProfileStudentName');
                const orderEl = document.getElementById('pedProfileStudentOrder');
                const gridEl = document.getElementById('pedProfileBadgesGrid');

                if (nameEl) nameEl.textContent = profile.name;
                if (orderEl) orderEl.textContent = profile.orderNum ? ('ترتيب: ' + profile.orderNum) : (profile.massar || '#');

                if (gridEl) {
                    // شارات المعدل، المواظبة، الواجبات، السلوك
                    let avgLabel = profile.avg !== null ? (profile.avg.toFixed(2) + ' / 20') : 'غير مسجل';
                    let avgBg = '#f8fafc', avgColor = '#475569', avgBorder = '#cbd5e1';
                    if (typeof window.getGradeConditionalStyle === 'function' && profile.avg !== null) {
                        const cs = window.getGradeConditionalStyle(profile.avg);
                        avgBg = cs.bg; avgColor = cs.color; avgBorder = cs.border;
                    }

                    let absBg = profile.absentHours === 0 ? '#f0fdf4' : (profile.absentHours <= 2 ? '#fffbeb' : '#fef2f2');
                    let absColor = profile.absentHours === 0 ? '#166534' : (profile.absentHours <= 2 ? '#b45309' : '#991b1b');
                    let absBorder = profile.absentHours === 0 ? '#bbf7d0' : (profile.absentHours <= 2 ? '#fde68a' : '#fecaca');

                    let hwBg = profile.missedHw === 0 ? '#f0fdf4' : '#faf5ff';
                    let hwColor = profile.missedHw === 0 ? '#166534' : '#6b21a8';
                    let hwBorder = profile.missedHw === 0 ? '#bbf7d0' : '#e9d5ff';

                    let behBg = profile.disciplineLevel === 'model' ? '#ecfdf5' : (profile.disciplineLevel === 'disruptive' ? '#fef2f2' : '#f8fafc');
                    let behColor = profile.disciplineLevel === 'model' ? '#065f46' : (profile.disciplineLevel === 'disruptive' ? '#991b1b' : '#334155');
                    let behBorder = profile.disciplineLevel === 'model' ? '#a7f3d0' : (profile.disciplineLevel === 'disruptive' ? '#fecaca' : '#cbd5e1');

                    const prog = profile.progression || { badge: '-', label: 'غير متوفر', sequenceText: '-', bg: '#f8fafc', color: '#475569', border: '#cbd5e1' };

                    gridEl.innerHTML = `
                        <div style="background: ${avgBg}; color: ${avgColor}; border: 1px solid ${avgBorder}; padding: 6px 10px; border-radius: 8px; font-size: 0.76rem; display: flex; flex-direction: column; gap: 2px;">
                            <span style="font-size: 0.68rem; opacity: 0.85;">📊 معدل المراقبة:</span>
                            <span style="font-weight: 900; font-size: 0.88rem;">${avgLabel}</span>
                        </div>
                        <div style="background: ${prog.bg}; color: ${prog.color}; border: 1px solid ${prog.border}; padding: 6px 10px; border-radius: 8px; font-size: 0.76rem; display: flex; flex-direction: column; gap: 2px;" title="مسار الفروض: ${prog.sequenceText}">
                            <span style="font-size: 0.68rem; opacity: 0.85;">📈 مؤشر تطور الأداء:</span>
                            <span style="font-weight: 900; font-size: 0.84rem;">${prog.badge} <small style="font-weight: 700; opacity: 0.9;">(${prog.label})</small></span>
                        </div>
                        <div style="background: ${absBg}; color: ${absColor}; border: 1px solid ${absBorder}; padding: 6px 10px; border-radius: 8px; font-size: 0.76rem; display: flex; flex-direction: column; gap: 2px;">
                            <span style="font-size: 0.68rem; opacity: 0.85;">⏱️ المواظبة والغياب:</span>
                            <span style="font-weight: 800;">${profile.absentHours} س غياب ${profile.lateCount > 0 ? ('(' + profile.lateCount + ' تأخر)') : '✅'}</span>
                        </div>
                        <div style="background: ${hwBg}; color: ${hwColor}; border: 1px solid ${hwBorder}; padding: 6px 10px; border-radius: 8px; font-size: 0.76rem; display: flex; flex-direction: column; gap: 2px;">
                            <span style="font-size: 0.68rem; opacity: 0.85;">📝 الواجبات المنزلية:</span>
                            <span style="font-weight: 800;">${profile.missedHw === 0 ? 'منجزة بالكامل ✅' : ('لم ينجز: ' + profile.missedHw + ' ⚠️')}</span>
                        </div>
                        <div style="background: ${behBg}; color: ${behColor}; border: 1px solid ${behBorder}; padding: 6px 10px; border-radius: 8px; font-size: 0.76rem; display: flex; flex-direction: column; gap: 2px;">
                            <span style="font-size: 0.68rem; opacity: 0.85;">🌟 حالة السلوك:</span>
                            <span style="font-weight: 800;">${profile.behaviorStatus}</span>
                        </div>
                    `;
                }
            }

            // توليد الملاحظة الذكية المقترحة
            const remarkObj = generatePedagogicalRemarks(profile, 'balanced');
            if (smartBox) {
                smartBox.style.display = 'block';
                const textEl = document.getElementById('smartRemarkText');
                if (textEl) textEl.textContent = remarkObj.primary;
                currentSmartRemarkAlternatives = [remarkObj.primary, ...(remarkObj.alternatives || [])];
                currentSmartRemarkIndex = 0;
            }

            if (window.renderLucide) window.renderLucide();
        }
        window.onNotesStudentSelectChange = onNotesStudentSelectChange;

        // تدوير الصياغات البديلة
        function cycleAlternativeRemark() {
            if (!currentSmartRemarkAlternatives || currentSmartRemarkAlternatives.length <= 1) return;
            currentSmartRemarkIndex = (currentSmartRemarkIndex + 1) % currentSmartRemarkAlternatives.length;
            const textEl = document.getElementById('smartRemarkText');
            if (textEl) {
                textEl.textContent = currentSmartRemarkAlternatives[currentSmartRemarkIndex];
                textEl.style.transition = 'background-color 0.3s';
                textEl.style.backgroundColor = '#ecfdf5';
                setTimeout(() => { if (textEl) textEl.style.backgroundColor = 'rgba(255,255,255,0.7)'; }, 400);
            }
        }
        window.cycleAlternativeRemark = cycleAlternativeRemark;

        // تطبيق الملاحظة المقترحة في حقل التدوين
        function applySmartRemark(customText) {
            const textEl = document.getElementById('smartRemarkText');
            const targetText = customText || (textEl ? textEl.textContent.trim() : '');
            const input = document.getElementById('newNoteText');
            if (!input || !targetText) return;
            input.value = targetText;
            input.focus();
            input.style.borderColor = 'var(--primary)';
            if (typeof showNotification === 'function') {
                showNotification('تم اعتماد الملاحظة الآلية بنجاح في حقل التدوين', 'success');
            }
        }
        window.applySmartRemark = applySmartRemark;

        // نسخ الملاحظة الذكية للحافظة
        function copySmartRemark() {
            const textEl = document.getElementById('smartRemarkText');
            const text = textEl ? textEl.textContent.trim() : '';
            if (!text) return;
            if (navigator && navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(text).then(() => {
                    if (typeof showNotification === 'function') showNotification('تم نسخ الملاحظة للحافظة', 'success');
                    else alert('تم نسخ الملاحظة للحافظة');
                });
            } else {
                alert(text);
            }
        }
        window.copySmartRemark = copySmartRemark;

        // إدراج عبارة تربوية سريعة من البنك
        function insertPedPhrase(phrase) {
            const input = document.getElementById('newNoteText');
            if (!input) return;
            const current = input.value.trim();
            if (current) {
                input.value = current + ' ' + phrase;
            } else {
                input.value = phrase;
            }
            input.focus();
        }
        window.insertPedPhrase = insertPedPhrase;

        // مسح حقل التدوين
        function clearNoteInput() {
            const input = document.getElementById('newNoteText');
            if (input) input.value = '';
            const select = document.getElementById('notesStudentSelect');
            if (select) {
                select.value = '';
                onNotesStudentSelectChange();
            }
        }
        window.clearNoteInput = clearNoteInput;

        // =========================================================================
        // نافذة التوليد الجماعي لملاحظات القسم دفعة واحدة (Batch Class Remarks Modal)
        // =========================================================================
        let currentBatchRemarksData = [];

        function openBatchClassRemarksModal() {
            const className = document.getElementById('notesClassSelect').value;
            if (!className) {
                alert('يرجى اختيار القسم أولاً من القائمة المنسدلة.');
                return;
            }
            if (!db.classes[className] || db.classes[className].length === 0) {
                alert('لا يوجد تلاميذ مسجلون في هذا القسم حالياً.');
                return;
            }

            const modal = document.getElementById('batchClassRemarksModal');
            if (!modal) return;
            modal.style.display = 'flex';

            const subTitle = document.getElementById('batchModalClassSubtitle');
            if (subTitle) subTitle.textContent = `توليد واقتراح ملاحظات بيداغوجية موجهة لقسم: «${className}» (${db.classes[className].length} تلميذ)`;

            regenerateAllBatchRemarks();
            if (window.renderLucide) window.renderLucide();
        }
        window.openBatchClassRemarksModal = openBatchClassRemarksModal;

        function closeBatchClassRemarksModal() {
            const modal = document.getElementById('batchClassRemarksModal');
            if (modal) modal.style.display = 'none';
        }
        window.closeBatchClassRemarksModal = closeBatchClassRemarksModal;

        function regenerateAllBatchRemarks() {
            const className = document.getElementById('notesClassSelect').value;
            if (!className || !db.classes[className]) return;

            const styleSelect = document.getElementById('batchRemarksStyleSelect');
            const style = styleSelect ? styleSelect.value : 'balanced';

            const tbody = document.getElementById('batchClassRemarksTableBody');
            if (!tbody) return;
            tbody.innerHTML = '';
            currentBatchRemarksData = [];

            const students = db.classes[className];
            students.forEach((std, idx) => {
                const profile = getStudentPedagogicalProfile(className, std.id);
                if (!profile) return;

                const remarkObj = generatePedagogicalRemarks(profile, style);
                const prog = profile.progression || { badge: '-', label: 'غير متوفر', sequenceText: '-', bg: '#f8fafc', color: '#475569', border: '#cbd5e1' };
                currentBatchRemarksData.push({
                    studentId: std.id,
                    orderNum: std.orderNum || (idx + 1),
                    name: std.name,
                    massar: std.massar || '',
                    avg: profile.avg,
                    progression: prog,
                    absentHours: profile.absentHours,
                    lateCount: profile.lateCount,
                    missedHw: profile.missedHw,
                    behaviorStatus: profile.behaviorStatus,
                    remark: remarkObj.primary,
                    alternatives: remarkObj.alternatives || []
                });

                let avgText = profile.avg !== null ? (profile.avg.toFixed(2) + ' / 20') : '-';
                let avgStyle = 'background: #f8fafc; color: #475569; border: 1px solid #cbd5e1;';
                if (typeof window.getGradeConditionalStyle === 'function' && profile.avg !== null) {
                    const cs = window.getGradeConditionalStyle(profile.avg);
                    avgStyle = cs.cssText || `background: ${cs.bg}; color: ${cs.color}; border: 1px solid ${cs.border}; font-weight: 800;`;
                }

                const tr = document.createElement('tr');
                tr.style.borderBottom = '1px solid #e2e8f0';
                tr.style.backgroundColor = (idx % 2 === 0) ? '#ffffff' : '#f8fafc';

                tr.innerHTML = `
                    <td style="padding: 8px 10px; text-align: center; font-weight: 800; color: #475569;">${profile.orderNum || (idx + 1)}</td>
                    <td style="padding: 8px 10px; font-weight: 800; color: #0f172a;">
                        ${profile.name}
                        ${profile.massar ? `<div style="font-size: 0.7rem; color: #64748b; font-weight: normal;">${profile.massar}</div>` : ''}
                    </td>
                    <td style="padding: 8px 10px; text-align: center;">
                        <span style="display: inline-block; padding: 2px 7px; border-radius: 6px; font-size: 0.78rem; font-weight: 800; ${avgStyle}">
                            ${avgText}
                        </span>
                        <div style="margin-top: 4px;">
                            <span style="display: inline-block; padding: 1px 6px; border-radius: 5px; font-size: 0.68rem; font-weight: 800; background: ${prog.bg}; color: ${prog.color}; border: 1px solid ${prog.border};" title="مسار الفروض: ${prog.sequenceText}">
                                ${prog.badge} ${prog.label}
                            </span>
                        </div>
                    </td>
                    <td style="padding: 8px 10px; text-align: center; font-size: 0.78rem;">
                        <span style="color: ${profile.absentHours > 0 ? '#dc2626' : '#15803d'}; font-weight: 800;">${profile.absentHours} س غياب</span>
                        ${profile.lateCount > 0 ? `<div style="color: #d97706; font-size: 0.7rem;">${profile.lateCount} تأخر</div>` : ''}
                    </td>
                    <td style="padding: 8px 10px; text-align: center; font-size: 0.78rem;">
                        <span style="color: #334155; font-weight: 700;">${profile.behaviorStatus}</span>
                        ${profile.missedHw > 0 ? `<div style="color: #7c3aed; font-size: 0.7rem; font-weight: bold;">أهمل ${profile.missedHw} واجب</div>` : ''}
                    </td>
                    <td style="padding: 6px 10px;">
                        <textarea id="batchRemarkInput_${std.id}" onchange="updateBatchRemarkData('${std.id}', this.value)" style="width: 100%; min-height: 48px; padding: 6px 8px; border-radius: 6px; border: 1px solid #cbd5e1; font-family: 'Cairo', sans-serif; font-size: 0.8rem; line-height: 1.4; resize: vertical; background: #fff;">${remarkObj.primary}</textarea>
                    </td>
                    <td style="padding: 8px 10px; text-align: center;">
                        <button type="button" onclick="cycleBatchRowAlternative('${std.id}')" title="اقتراح بديل لهذه الملاحظة" style="background: #e0f2fe; color: #0284c7; border: 1px solid #bae6fd; border-radius: 6px; padding: 4px 8px; font-size: 0.74rem; cursor: pointer; font-weight: bold;">
                            بديل 🔄
                        </button>
                    </td>
                `;
                tbody.appendChild(tr);
            });

            const summaryEl = document.getElementById('batchRemarksSummaryStats');
            if (summaryEl) summaryEl.textContent = `تم توليد الملاحظات بنجاح لـ ${students.length} تلميذ وفق نمط (${style})`;
        }
        window.regenerateAllBatchRemarks = regenerateAllBatchRemarks;

        function updateBatchRemarkData(studentId, val) {
            const item = currentBatchRemarksData.find(d => d.studentId === studentId);
            if (item) item.remark = val.trim();
        }
        window.updateBatchRemarkData = updateBatchRemarkData;

        function cycleBatchRowAlternative(studentId) {
            const item = currentBatchRemarksData.find(d => d.studentId === studentId);
            if (!item || !item.alternatives || item.alternatives.length === 0) return;
            const input = document.getElementById('batchRemarkInput_' + studentId);
            if (!input) return;

            const pool = [item.remark, ...item.alternatives];
            const currentIdx = pool.indexOf(input.value.trim());
            const nextIdx = (currentIdx + 1) % pool.length;
            const nextVal = pool[nextIdx];
            input.value = nextVal;
            item.remark = nextVal;
            input.style.backgroundColor = '#ecfdf5';
            setTimeout(() => { if (input) input.style.backgroundColor = '#ffffff'; }, 350);
        }
        window.cycleBatchRowAlternative = cycleBatchRowAlternative;

        // حفظ جميع الملاحظات في سجل ملاحظات التطبيق
        function saveAllBatchRemarksToNotes() {
            const className = document.getElementById('notesClassSelect').value;
            if (!className) return;

            if (!db.notes[className]) db.notes[className] = [];
            const now = new Date();
            const dateStr = now.toLocaleDateString('en-GB') + ' ' + now.toLocaleTimeString('en-GB', { hour: '2-digit', minute:'2-digit' });

            let addedCount = 0;
            currentBatchRemarksData.forEach(item => {
                const text = item.remark ? item.remark.trim() : '';
                if (text) {
                    db.notes[className].push({
                        id: Date.now().toString() + '_' + Math.random().toString(36).substr(2, 5),
                        date: dateStr,
                        text: text,
                        studentId: item.studentId
                    });
                    addedCount++;
                }
            });

            saveDB();
            renderNotes();
            closeBatchClassRemarksModal();
            if (typeof showNotification === 'function') {
                showNotification(`تم اعتماد وحفظ ${addedCount} ملاحظة تربوية في سجل ملاحظات القسم بنجاح`, 'success');
            } else {
                alert(`تم حفظ ${addedCount} ملاحظة تربوية بنجاح.`);
            }
        }
        window.saveAllBatchRemarksToNotes = saveAllBatchRemarksToNotes;

        // نسخ الملاحظات بصيغة جدول لمسار أو Excel
        function copyBatchRemarksForMassar() {
            if (!currentBatchRemarksData || currentBatchRemarksData.length === 0) {
                alert('لا توجد بيانات ملاحظات للنسخ.');
                return;
            }

            let tsv = 'الترتيب\tرقم مسار\tاسم التلميذ\tالمعدل\tمؤشر التطور\tالملاحظة التربوية\n';
            currentBatchRemarksData.forEach(d => {
                const avgText = d.avg !== null ? d.avg.toFixed(2) : '';
                const progText = (d.progression && d.progression.badge !== '-') ? `${d.progression.badge} (${d.progression.label})` : '-';
                tsv += `${d.orderNum}\t${d.massar}\t${d.name}\t${avgText}\t${progText}\t${d.remark}\n`;
            });

            if (navigator && navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(tsv).then(() => {
                    if (typeof showNotification === 'function') {
                        showNotification('تم نسخ جدول الملاحظات بنجاح! يمكنك الآن لصقه مباشرة في مسار أو ملف Excel', 'success');
                    } else {
                        alert('تم نسخ جدول الملاحظات للحافظة.');
                    }
                }).catch(() => {
                    prompt('انسخ الجدول أدناه يدوياً:', tsv);
                });
            } else {
                prompt('انسخ الجدول أدناه يدوياً:', tsv);
            }
        }
        window.copyBatchRemarksForMassar = copyBatchRemarksForMassar;

        // تصدير كشف الملاحظات والنقط بصيغة إكسيل مسار الرسمي (.xlsx)
        function exportBatchRemarksMassarExcel() {
            const className = document.getElementById('notesClassSelect')?.value || document.getElementById('classSelect')?.value;
            if (!className || !db.classes || !db.classes[className] || db.classes[className].length === 0) {
                alert('يرجى اختيار قسم يحتوي على تلاميذ أولاً.');
                return;
            }
            if (typeof XLSX === 'undefined') {
                alert('مكتبة Excel غير متوفرة حالياً.');
                return;
            }

            if (!currentBatchRemarksData || currentBatchRemarksData.length === 0) {
                regenerateAllBatchRemarks();
            }

            const activeSem = window.activeSemester || 's1';
            const semLabel = activeSem === 's2' ? 'الدورة الثانية' : 'الدورة الأولى';
            const examCount = (typeof getExamsCountForClass === 'function') ? getExamsCountForClass(className) : 3;
            const pYear = (db.teacherProfile && db.teacherProfile.academicYear) || '2026 / 2027';
            const pSchool = (db.teacherProfile && db.teacherProfile.school) || 'الثانوية التأهيلية';
            const pName = (db.teacherProfile && db.teacherProfile.name) || 'أستاذ مادة الرياضيات';

            const rows = [
                ['المملكة المغربية - وزارة التربية الوطنية والتعليم الأولي والرياضة'],
                ['المؤسسة التعليمية:', pSchool, '', 'السنة الدراسية:', pYear],
                ['المادة: الرياضيات (Mathématiques)', 'القسم:', className, 'الدورة:', semLabel, 'الأستاذ(ة):', pName],
                []
            ];

            const headers = ['الرقم الترتيبي', 'رقم مسار', 'النسب والاسم الكامل', 'الفرض 1', 'الفرض 2'];
            if (examCount >= 3) headers.push('الفرض 3');
            if (examCount === 4) headers.push('الفرض 4');
            headers.push('معدل الدورة', 'مؤشر التطور الرياضي', 'مسار النقط', 'المواظبة (س غياب)', 'السلوك', 'الملاحظة التربوية (مسار)');
            rows.push(headers);

            currentBatchRemarksData.forEach((d, idx) => {
                const g = getStudentGradesBySemester(className, d.studentId, activeSem);
                const f1 = (g && g.f1 !== undefined && g.f1 !== '' && !isNaN(g.f1)) ? parseFloat(g.f1) : '';
                const f2 = (g && g.f2 !== undefined && g.f2 !== '' && !isNaN(g.f2)) ? parseFloat(g.f2) : '';
                const f3 = (g && g.f3 !== undefined && g.f3 !== '' && !isNaN(g.f3)) ? parseFloat(g.f3) : '';
                const f4 = (g && g.f4 !== undefined && g.f4 !== '' && !isNaN(g.f4)) ? parseFloat(g.f4) : '';
                const avgVal = (d.avg !== null && !isNaN(d.avg)) ? parseFloat(d.avg.toFixed(2)) : '';
                const progLabel = d.progression ? `${d.progression.badge} (${d.progression.label})` : '-';
                const seqText = d.progression ? d.progression.sequenceText : '-';

                const row = [
                    d.orderNum || (idx + 1),
                    d.massar || '',
                    d.name || '',
                    f1,
                    f2
                ];
                if (examCount >= 3) row.push(f3);
                if (examCount === 4) row.push(f4);
                row.push(avgVal, progLabel, seqText, d.absentHours || 0, d.behaviorStatus || 'منضبط', d.remark || '');
                rows.push(row);
            });

            const ws = XLSX.utils.aoa_to_sheet(rows);
            ws['!cols'] = [
                { wch: 10 }, { wch: 14 }, { wch: 28 },
                { wch: 10 }, { wch: 10 },
                ...(examCount >= 3 ? [{ wch: 10 }] : []),
                ...(examCount === 4 ? [{ wch: 10 }] : []),
                { wch: 12 }, { wch: 20 }, { wch: 18 }, { wch: 14 }, { wch: 12 }, { wch: 48 }
            ];
            const wb = XLSX.utils.book_new();
            XLSX.utils.book_append_sheet(wb, ws, className.replace(/[\\\/\?\*\[\]]/g, '_').substring(0, 31));
            const filename = `مسار_النقط_والملاحظات_${className}_${activeSem}.xlsx`;
            XLSX.writeFile(wb, filename);
            if (typeof showNotification === 'function') {
                showNotification(`تم تصدير ملف إكسيل مسار للنقط والملاحظات (${filename}) بنجاح!`, 'success');
            }
        }
        window.exportBatchRemarksMassarExcel = exportBatchRemarksMassarExcel;

        // طباعة كشف ملاحظات القسم
        function printBatchClassRemarks() {
            const className = document.getElementById('notesClassSelect').value;
            if (!currentBatchRemarksData || currentBatchRemarksData.length === 0) return;

            const printWindow = window.open('', '_blank');
            if (!printWindow) {
                alert('يرجى السماح بفتح النوافذ المنبثقة للطباعة.');
                return;
            }

            let rowsHtml = '';
            currentBatchRemarksData.forEach(d => {
                const avgText = d.avg !== null ? d.avg.toFixed(2) : '-';
                rowsHtml += `
                    <tr>
                        <td style="border: 1px solid #333; padding: 6px; text-align: center;">${d.orderNum}</td>
                        <td style="border: 1px solid #333; padding: 6px; text-align: center;">${d.massar || '-'}</td>
                        <td style="border: 1px solid #333; padding: 6px; font-weight: bold;">${d.name}</td>
                        <td style="border: 1px solid #333; padding: 6px; text-align: center; font-weight: bold;">${avgText}</td>
                        <td style="border: 1px solid #333; padding: 6px; text-align: center;">${d.absentHours} س</td>
                        <td style="border: 1px solid #333; padding: 6px; text-align: center;">${d.behaviorStatus}</td>
                        <td style="border: 1px solid #333; padding: 6px; text-align: right;">${d.remark}</td>
                    </tr>
                `;
            });

            const html = `
                <!DOCTYPE html>
                <html dir="rtl" lang="ar">
                <head>
                    <meta charset="utf-8">
                    <title>كشف الملاحظات والتوجيهات التربوية - ${className}</title>
                    <style>
                        body { font-family: 'Cairo', 'Segoe UI', Tahoma, sans-serif; padding: 20px; direction: rtl; }
                        h2, h3 { margin: 5px 0; }
                        table { width: 100%; border-collapse: collapse; margin-top: 15px; font-size: 12px; }
                        th { background-color: #f1f5f9; border: 1px solid #333; padding: 8px; text-align: center; }
                        @media print {
                            body { padding: 0; }
                            @page { size: A4 portrait; margin: 12mm; }
                        }
                    </style>
                </head>
                <body>
                    <div style="text-align: center; margin-bottom: 20px; border-bottom: 2px solid #000; padding-bottom: 10px;">
                        <h2>المملكة المغربية - وزارة التربية الوطنية والتعليم الأولي والرياضة</h2>
                        <h3>كشف الملاحظات والتوجيهات التربوية (مسار وبيان النتائج)</h3>
                        <p style="margin: 0; font-size: 13px;">القسم: <strong>${className}</strong> | تاريخ الاستخراج: ${new Date().toLocaleDateString('ar-MA')}</p>
                    </div>
                    <table>
                        <thead>
                            <tr>
                                <th style="width: 40px;">#</th>
                                <th style="width: 100px;">رقم مسار</th>
                                <th style="width: 180px;">اسم التلميذ(ة)</th>
                                <th style="width: 60px;">المعدل</th>
                                <th style="width: 60px;">الغياب</th>
                                <th style="width: 80px;">السلوك</th>
                                <th>الملاحظة البيداغوجية والتوجيه التربوي</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${rowsHtml}
                        </tbody>
                    </table>
                    <div style="margin-top: 30px; display: flex; justify-content: space-between; font-weight: bold;">
                        <span>توقيع الأستاذ(ة):</span>
                        <span>تأشيرة السيد الحارس العام للخارجية / الإدارة:</span>
                    </div>
                    <script>window.onload = function() { window.print(); };</script>
                </body>
                </html>
            `;

            printWindow.document.write(html);
            printWindow.document.close();
        }
        window.printBatchClassRemarks = printBatchClassRemarks;

        function renderNotes() {
            const className = document.getElementById('notesClassSelect').value;
            const container = document.getElementById('notesListContainer');
            if (!className) {
                container.style.display = 'none';
                return;
            }
            container.style.display = 'block';
            
            const searchQ = (document.getElementById('notesSearchInput') ? document.getElementById('notesSearchInput').value : '').toLowerCase().trim();
            const typeFilter = document.getElementById('notesTypeFilter') ? document.getElementById('notesTypeFilter').value : 'all';
            const list = document.getElementById('notesList');
            const countBadge = document.getElementById('notesCountBadge');
            list.innerHTML = '';
            
            if (!db.notes[className]) db.notes[className] = [];
            
            let filteredNotes = db.notes[className];
            if (currentNotesStudentFilter) {
                filteredNotes = filteredNotes.filter(n => n.studentId === currentNotesStudentFilter);
            }
            if (typeFilter === 'general') {
                filteredNotes = filteredNotes.filter(n => !n.studentId);
            } else if (typeFilter === 'student') {
                filteredNotes = filteredNotes.filter(n => !!n.studentId);
            }
            if (searchQ) {
                filteredNotes = filteredNotes.filter(n => {
                    const matchesText = n.text && n.text.toLowerCase().includes(searchQ);
                    let matchesStudent = false;
                    if (n.studentId && db.classes[className]) {
                        const std = db.classes[className].find(s => s.id === n.studentId);
                        if (std && std.name) matchesStudent = std.name.toLowerCase().includes(searchQ);
                    }
                    return matchesText || matchesStudent;
                });
            }
            
            if (countBadge) countBadge.textContent = `${filteredNotes.length} ملاحظة`;

            if (filteredNotes.length === 0) {
                list.innerHTML = '<div style="text-align: center; color: var(--text-muted); font-size: 0.9rem; padding: 20px; background: #f8fafc; border-radius: 8px; border: 1px dashed #cbd5e1;">لا توجد ملاحظات مسجلة مطابقة للبحث أو الفلترة الحالية.</div>';
                return;
            }
            
            filteredNotes.slice().reverse().forEach(note => {
                const div = document.createElement('div');
                div.style.backgroundColor = '#ffffff';
                div.style.border = '1.5px solid #e2e8f0';
                div.style.borderRadius = '10px';
                div.style.padding = '14px';
                div.style.position = 'relative';
                div.style.boxShadow = '0 1px 3px rgba(0,0,0,0.02)';
                
                let studentNameTag = '<span style="background: #e0f2fe; color: #0369a1; border: 1px solid #bae6fd; padding: 2px 8px; border-radius: 6px; font-size: 0.72rem; font-weight: 800;">ملاحظة عامة للقسم</span>';
                if (note.studentId) {
                    const std = (db.classes[className] || []).find(s => s.id === note.studentId);
                    if (std) {
                        studentNameTag = `<span style="background: #e0e7ff; color: #4338ca; border: 1px solid #c7d2fe; padding: 2px 8px; border-radius: 6px; font-size: 0.72rem; font-weight: 800; display: inline-flex; align-items: center; gap: 4px;">${lucideIcon('user', {size: 11})} ${std.name}</span>`;
                    }
                }
                
                div.innerHTML = `
                    <div style="font-size: 0.75rem; color: #64748b; margin-bottom: 8px; display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid #f1f5f9; padding-bottom: 6px;">
                        <div style="display: flex; gap: 8px; align-items: center; flex-wrap: wrap;">
                            <span style="display: inline-flex; align-items: center; gap: 4px; font-weight: 600;">${lucideIcon('calendar', {size: 12})} ${note.date}</span>
                            ${studentNameTag}
                        </div>
                        <div style="display: flex; gap: 6px; align-items: center;">
                            <button type="button" class="hide-in-presentation" onclick="copyNoteTextToClipboard('${note.id}', '${className}')" style="background: #f1f5f9; border: 1px solid #cbd5e1; color: #475569; cursor: pointer; font-size: 0.75rem; padding: 3px 8px; border-radius: 5px; font-weight: bold; display: inline-flex; align-items: center; gap: 4px;" title="نسخ الملاحظة">${lucideIcon('copy', {size: 12})} نسخ</button>
                            <button class="hide-in-presentation" onclick="deleteNote('${className}', '${note.id}')" style="background: none; border: none; color: #ef4444; cursor: pointer; font-size: 0.85rem; padding: 3px;" title="حذف الملاحظة">${lucideIcon('trash2', {size: 13})}</button>
                        </div>
                    </div>
                    <div id="noteTextContent_${note.id}" style="font-size: 0.92rem; color: #1e293b; white-space: pre-wrap; line-height: 1.6; font-family: 'Cairo', sans-serif;">${note.text}</div>
                `;
                list.appendChild(div);
            });

            if (window.renderLucide) window.renderLucide();
        }

        function copyNoteTextToClipboard(noteId, className) {
            const notes = db.notes[className] || [];
            const note = notes.find(n => n.id === noteId);
            if (!note || !note.text) return;
            if (navigator && navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(note.text).then(() => {
                    if (typeof showNotification === 'function') showNotification('تم نسخ نص الملاحظة للحافظة', 'success');
                });
            } else {
                alert(note.text);
            }
        }
        window.copyNoteTextToClipboard = copyNoteTextToClipboard;

        let _isAddingNote = false;
        function addNote() {
            if (_isAddingNote) return;
            const className = document.getElementById('notesClassSelect').value;
            const studentId = document.getElementById('notesStudentSelect').value;
            const input = document.getElementById('newNoteText');
            const text = input ? input.value.trim() : '';
            if (!className) {
                alert('يرجى اختيار القسم أولاً.');
                return;
            }
            if (!text) {
                alert('يرجى كتابة نص الملاحظة أو اعتماد الملاحظة المقترحة أولاً.');
                return;
            }

            _isAddingNote = true;
            const unlock = () => { setTimeout(() => { _isAddingNote = false; }, 400); };
            
            if (!db.notes[className]) db.notes[className] = [];
            
            const now = new Date();
            const dateStr = now.toLocaleDateString('en-GB') + ' ' + now.toLocaleTimeString('en-GB', { hour: '2-digit', minute:'2-digit' });
            
            db.notes[className].push({
                id: Date.now().toString(),
                date: dateStr,
                text: text,
                studentId: studentId
            });
            
            saveDB();
            input.value = '';
            document.getElementById('notesStudentSelect').value = '';
            onNotesStudentSelectChange();
            renderNotes();
            if (typeof showNotification === 'function') {
                showNotification('تمت إضافة الملاحظة وحفظها بنجاح', 'success');
            }
            unlock();
        }

        function deleteNote(className, noteId) {
            if (!confirm('هل أنت متأكد من حذف هذه الملاحظة؟')) return;
            if (db.notes[className]) {
                db.notes[className] = db.notes[className].filter(n => n.id !== noteId);
                saveDB();
                renderNotes();
            }
        }
        
        function searchNotes() {
            renderNotes();
        }

        window.onNotesClassChange = onNotesClassChange;
        window.onNotesStudentSelectChange = onNotesStudentSelectChange;
        window.setNotesStudentFilter = setNotesStudentFilter;
