        window.getSortedClasses = getSortedClasses;
        function getSortedClasses(includeArchived = false) {
            let classes = Object.keys(db.classes || {});
            if (!includeArchived) {
                if (!db.archivedClasses) db.archivedClasses = [];
                classes = classes.filter(c => !db.archivedClasses.includes(c));
            }
            
            const sortPref = db.classSortPref || 'alphabetical';
            if (sortPref === 'frequency') {
                const usage = db.classUsage || {};
                classes.sort((a, b) => (usage[b] || 0) - (usage[a] || 0));
            } else if (sortPref === 'manual') {
                const order = db.classManualOrder || [];
                classes.sort((a, b) => {
                    const idxA = order.indexOf(a);
                    const idxB = order.indexOf(b);
                    if (idxA === -1 && idxB === -1) return a.localeCompare(b, 'ar');
                    if (idxA === -1) return 1;
                    if (idxB === -1) return -1;
                    return idxA - idxB;
                });
            } else {
                classes.sort((a, b) => a.localeCompare(b, 'ar'));
            }
            return classes;
        }

        function incrementClassUsage(className) {
            if (!className) return;
            if (!db.classUsage) db.classUsage = {};
            db.classUsage[className] = (db.classUsage[className] || 0) + 1;
            saveDB();
        }

        function toggleManualClassSortUI() {
            const val = document.getElementById('settingsClassSort').value;
            const container = document.getElementById('manualClassSortContainer');
            if (val === 'manual') {
                container.style.display = 'flex';
                renderManualClassSort();
            } else {
                container.style.display = 'none';
            }
        }

        function renderManualClassSort() {
            const container = document.getElementById('manualClassSortContainer');
            container.innerHTML = '';
            
            let classes = Object.keys(db.classes || {}).filter(c => !(db.archivedClasses || []).includes(c));
            const order = db.classManualOrder || [];
            classes.sort((a, b) => {
                const idxA = order.indexOf(a);
                const idxB = order.indexOf(b);
                if (idxA === -1 && idxB === -1) return a.localeCompare(b, 'ar');
                if (idxA === -1) return 1;
                if (idxB === -1) return -1;
                return idxA - idxB;
            });
            db.classManualOrder = classes;

            classes.forEach((cls, index) => {
                const item = document.createElement('div');
                item.style.cssText = 'display: flex; justify-content: space-between; align-items: center; background: white; padding: 8px 12px; border: 1px solid #cbd5e1; border-radius: 6px;';
                item.innerHTML = `
                    <span style="font-weight: 600; font-size: 0.9rem; color: #1e293b;">${cls}</span>
                    <div style="display: flex; gap: 4px;">
                        <button type="button" onclick="moveClassManualOrder(${index}, -1)" ${index === 0 ? 'disabled style="opacity: 0.5"' : ''} style="background: none; border: none; cursor: pointer; color: #64748b; padding: 4px;">${lucideIcon('arrow-up', {size: 14})}</button>
                        <button type="button" onclick="moveClassManualOrder(${index}, 1)" ${index === classes.length - 1 ? 'disabled style="opacity: 0.5"' : ''} style="background: none; border: none; cursor: pointer; color: #64748b; padding: 4px;">${lucideIcon('arrow-down', {size: 14})}</button>
                    </div>
                `;
                container.appendChild(item);
            });
            lucide.createIcons();
        }

        function moveClassManualOrder(index, direction) {
            const order = db.classManualOrder || [];
            if (index + direction < 0 || index + direction >= order.length) return;
            const temp = order[index];
            order[index] = order[index + direction];
            order[index + direction] = temp;
            db.classManualOrder = order;
            renderManualClassSort();
        }

