                function getOpts(selected) {
                    let opts = `<option value="">-- فارغ --</option>`;
                    for (let c in db.classes) {
                        opts += `<option value="${c}" ${selected === c ? 'selected' : ''}>${c}</option>`;
                    }
                    return opts;
                }

                function getTypeOpts(selected) {
                    const types = ["درس", "تمرين", "تقويم", "نشاط"];
                    let opts = '<option value="">النوع</option>';
                    types.forEach(t => {
                        opts += `<option value="${t}" ${selected === t ? 'selected' : ''}>${t}</option>`;
                    });
                    return opts;
                }

                function getTimeOpts(selected, isMorning=true) {
                    const times = isMorning 
                        ? ["08:00", "08:30", "09:00", "09:30", "10:00", "10:30", "11:00", "11:30", "12:00", "12:30"] 
                        : ["13:00", "13:30", "14:00", "14:30", "15:00", "15:30", "16:00", "16:30", "17:00", "17:30", "18:00"];
                    if (selected && !times.includes(selected)) {
                        times.unshift(selected);
                    }
                    let opts = '';
                    times.forEach(t => {
                        opts += `<option value="${t}" ${selected === t ? 'selected' : ''}>${t}</option>`;
                    });
                    return opts;
                }

