                        summaryHtml += `<span style="background:#ffedd5; color:#c2410c; padding:3px 6px; border-radius:4px; font-size:0.7rem; margin-left:4px; display:inline-flex; align-items:center; margin-bottom:4px;">م${idx+1}: ${item.c}${badge}</span>`;
