        window.toggleBatchClassAccordion = toggleBatchClassAccordion;
        window.toggleBatchStudentGroup = toggleBatchStudentGroup;
        window.updateBatchClassName = updateBatchClassName;
        window.updateBatchClassExamCount = updateBatchClassExamCount;
        window.removeBatchClass = removeBatchClass;
