                    hmTitle.style.textAlign = 'center';
                    hmTitle.style.marginTop = '24px';
                    hmTitle.style.color = '#ea580c';
                    container.appendChild(hmTitle);

                    const hmClone = heatmapCardEl.cloneNode(true);
                    hmClone.style.display = 'block';
                    hmClone.style.boxShadow = 'none';
                    hmClone.style.border = '1px solid #fed7aa';
                    hmClone.style.margin = '10px auto 25px auto';
                    container.appendChild(hmClone);
