        let tokenClient;
        let gapiInited = false;
        let gisInited = false;
        let calendarSyncInProgress = false;

        function initGoogleApi() {
            if (window.google && window.google.accounts && !gisInited) {
                tokenClient = google.accounts.oauth2.initTokenClient({
                    client_id: '198994308173-e380b2dhmmsocm7j4aiv2l5p8sk39mte.apps.googleusercontent.com',
                    scope: 'https://www.googleapis.com/auth/calendar.events',
                    callback: (tokenResponse) => {
                        if (tokenResponse && tokenResponse.access_token) {
                            performCalendarSync(tokenResponse.access_token);
                        }
                    },
                });
                gisInited = true;
            }
        }

        async function syncWithGoogleCalendar() {
            if (!gisInited) {
                initGoogleApi();
            }
            if (!gisInited) {
                alert("لم يتم تحميل مكتبة Google بنجاح. يرجى التأكد من اتصالك بالإنترنت وتحديث الصفحة.");
                return;
            }
            if (calendarSyncInProgress) return;
            
            if (!db.events || db.events.length === 0) {
                alert("لا توجد أحداث في التقويم لتصديرها.");
                return;
            }

            tokenClient.requestAccessToken({prompt: 'consent'});
        }

        async function performCalendarSync(accessToken) {
            calendarSyncInProgress = true;
            showLoading("جاري تصدير الأحداث إلى Google Calendar...");
            
            try {
                let successCount = 0;
                // export future events or events from today
                const today = new Date();
                today.setHours(0,0,0,0);
                
                const eventsToExport = db.events.filter(e => {
                    const evtDate = new Date(e.date);
                    return evtDate.getTime() >= today.getTime();
                });
                
                if (eventsToExport.length === 0) {
                    hideLoading();
                    alert("لا توجد أحداث قادمة لتصديرها.");
                    calendarSyncInProgress = false;
                    return;
                }

                for (const evt of eventsToExport) {
                    if (evt.googleEventId) continue; // Skip already exported
                    
                    const evtDate = new Date(evt.date);
                    // Create an all-day event
                    const startStr = formatLocalDate(evtDate);
                    const endDate = new Date(evtDate);
                    endDate.setDate(endDate.getDate() + 1);
                    const endStr = formatLocalDate(endDate);
                    
                    const eventBody = {
                        summary: evt.title,
                        description: "تم التصدير من منصة تتبع الغياب (AI Studio). نوع الحدث: " + (evt.type || "عام"),
                        start: {
                            date: startStr,
                            timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone
                        },
                        end: {
                            date: endStr,
                            timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone
                        }
                    };
                    
                    const response = await fetch("https://www.googleapis.com/calendar/v3/calendars/primary/events", {
                        method: "POST",
                        headers: {
                            "Authorization": `Bearer ${accessToken}`,
                            "Content-Type": "application/json"
                        },
                        body: JSON.stringify(eventBody)
                    });
                    
                    if (response.ok) {
                        const data = await response.json();
                        evt.googleEventId = data.id; // Mark as exported
                        successCount++;
                    }
                }
                
                saveDB();
                hideLoading();
                
                if (successCount > 0) {
                    alert(`تم تصدير ${successCount} أحداث جديدة إلى Google Calendar بنجاح.`);
                } else {
                    alert("جميع الأحداث القادمة مصدرة مسبقاً.");
                }
                
            } catch (error) {
                console.error("Error syncing with Google Calendar:", error);
                hideLoading();
                alert("حدث خطأ أثناء مزامنة التقويم. يرجى المحاولة لاحقاً.");
            }
            
            calendarSyncInProgress = false;
        }

        // ==========================================================================
        // Automated Calendar Daily WhatsApp Reminder Scheduling System (08:00 AM)
        // ==========================================================================
        function getCalendarWhatsappConfig() {
            if (!db.calendarWhatsappReminder) {
                db.calendarWhatsappReminder = {
                    enabled: true,
                    time: '08:00',
                    phone: (db.teacherProfile && (db.teacherProfile.phone || db.teacherProfile.whatsapp)) || '',
                    countryCode: '+212',
                    includeExams: true,
                    includeMeetings: true,
                    includeTasks: true,
                    includeHolidays: true,
                    includeTimetable: true,
                    lastNotifiedDate: ''
                };
            }
            if (typeof db.calendarWhatsappReminder.enabled !== 'boolean') db.calendarWhatsappReminder.enabled = true;
            if (!db.calendarWhatsappReminder.time) db.calendarWhatsappReminder.time = '08:00';
            if (!db.calendarWhatsappReminder.countryCode) db.calendarWhatsappReminder.countryCode = '+212';
            return db.calendarWhatsappReminder;
        }

        function cleanWhatsappPhoneNumber(rawPhone, countryCode = '+212') {
            if (!rawPhone) return '';
            let cleaned = String(rawPhone).replace(/[\s\-\(\)\.]/g, '');
            if (cleaned.startsWith('+')) {
                return cleaned.substring(1);
            }
            if (cleaned.startsWith('00')) {
                return cleaned.substring(2);
            }
            const cCode = String(countryCode).replace(/[\s\+]/g, '');
            if (cleaned.startsWith('0')) {
                return cCode + cleaned.substring(1);
            }
            if (cleaned.startsWith(cCode)) {
                return cleaned;
            }
            return cCode + cleaned;
        }

        function getTodayDateString(d) {
            const dateObj = d || (typeof getAppNow === 'function' ? getAppNow() : new Date());
            const year = dateObj.getFullYear();
            const month = String(dateObj.getMonth() + 1).padStart(2, '0');
            const day = String(dateObj.getDate()).padStart(2, '0');
            return `${year}-${month}-${day}`;
        }

        function getTodayCalendarSummaryData(targetDateStr) {
            const dateStr = targetDateStr || getTodayDateString();
            const [y, m, d] = dateStr.split('-').map(Number);
            const targetDateObj = new Date(y, m - 1, d);

            const DAY_NAMES = ['الأحد', 'الإثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'];
            const MONTH_NAMES = ['يناير', 'فبراير', 'مارس', 'أبريل', 'ماي', 'يونيو', 'يوليوز', 'غشت', 'شتنبر', 'أكتوبر', 'نونبر', 'دجنبر'];
            
            const dayName = DAY_NAMES[targetDateObj.getDay()];
            const monthName = MONTH_NAMES[targetDateObj.getMonth()];
            const formattedDateArabic = `${dayName} ${d} ${monthName} ${y}`;

            ensureCalendarEvents();
            const allCalendarEvts = (db.calendarEvents || []).concat(db.events || []);
            const dayEvents = allCalendarEvts.filter(ev => ev.date === dateStr);

            const exams = [];
            const meetings = [];
            const tasks = [];
            const holidays = [];

            dayEvents.forEach(ev => {
                const title = (ev.title || '').trim();
                const type = (ev.type || '').toLowerCase();
                
                if (type === 'exam' || /فرض|امتحان|مراقبة|اختبار|évaluation|contrôle|examen/i.test(title)) {
                    exams.push(title);
                } else if (type === 'meeting' || /اجتماع|لقاء|مجلس|ندوة|تنسيق|réunion|conseil/i.test(title)) {
                    meetings.push(title);
                } else if (type === 'task' || type === 'homework' || /واجب|مهمة|تمرين|تصحيح|دفتر|devoir|cahier|tâche/i.test(title)) {
                    tasks.push(title);
                } else if (type === 'holiday' || type === 'other' || ev.isOfficial || /عطلة|عيد|ذكرى|فترة بينية|vacance|fête/i.test(title)) {
                    holidays.push(title);
                } else {
                    tasks.push(title);
                }
            });

            // Timetable classes for today
            const timetableClasses = [];
            if (db.timetable && db.timetable[dayName]) {
                const tt = db.timetable[dayName];
                if (tt.morningClass && tt.morningClass.trim()) {
                    timetableClasses.push(`الفترة الصباحية: قسم ${tt.morningClass.trim()} (${tt.morningHours || 2} س)`);
                }
                if (tt.eveningClass && tt.eveningClass.trim()) {
                    timetableClasses.push(`الفترة المسائية: قسم ${tt.eveningClass.trim()} (${tt.eveningHours || 2} س)`);
                }
                ['m1', 'm2', 'e1', 'e2'].forEach(slot => {
                    if (tt[slot + '_class'] && tt[slot + '_class'].trim()) {
                        timetableClasses.push(`${tt[slot + '_class'].trim()} (${tt[slot + '_time'] || ''})`);
                    }
                });
            }

            return {
                dateStr,
                formattedDateArabic,
                dayName,
                exams,
                meetings,
                tasks,
                holidays,
                timetableClasses,
                totalCount: exams.length + meetings.length + tasks.length + holidays.length + timetableClasses.length
            };
        }

        function generateCalendarWhatsappMessage(targetDateStr) {
            const cfg = getCalendarWhatsappConfig();
            const data = getTodayCalendarSummaryData(targetDateStr);
            const teacherName = (db.teacherProfile && db.teacherProfile.name) ? db.teacherProfile.name.trim() : 'الأستاذ(ة)';
            const schoolName = (db.teacherProfile && db.teacherProfile.school) ? db.teacherProfile.school.trim() : '';
            const schedTime = cfg.time || '08:00';

            let msg = `🔔 *تذكير يومي تلقائي بمهام اليوم - التقويم السنوي*\n`;
            msg += `━━━━━━━━━━━━━━━━━━━━━\n`;
            msg += `📅 *اليوم:* ${data.formattedDateArabic}\n`;
            msg += `👨‍🏫 *الأستاذ(ة):* ${teacherName}\n`;
            if (schoolName) {
                msg += `🏫 *المؤسسة:* ${schoolName}\n`;
            }
            msg += `⏰ *توقيت الإشعار التلقائي:* ${schedTime} صباحاً\n`;
            msg += `━━━━━━━━━━━━━━━━━━━━━\n\n`;

            let hasSections = false;

            // Exams
            if (cfg.includeExams !== false) {
                if (data.exams.length > 0) {
                    hasSections = true;
                    msg += `🔴 *الفروض والامتحانات المبرمجة:*\n`;
                    data.exams.forEach(item => {
                        msg += `  • ${item}\n`;
                    });
                    msg += `\n`;
                }
            }

            // Meetings
            if (cfg.includeMeetings !== false) {
                if (data.meetings.length > 0) {
                    hasSections = true;
                    msg += `🔵 *الاجتماعات واللقاءات البيداغوجية:*\n`;
                    data.meetings.forEach(item => {
                        msg += `  • ${item}\n`;
                    });
                    msg += `\n`;
                }
            }

            // Tasks
            if (cfg.includeTasks !== false) {
                if (data.tasks.length > 0) {
                    hasSections = true;
                    msg += `🟣 *الواجبات والمهام المدرسية:*\n`;
                    data.tasks.forEach(item => {
                        msg += `  • ${item}\n`;
                    });
                    msg += `\n`;
                }
            }

            // Holidays
            if (cfg.includeHolidays !== false) {
                if (data.holidays.length > 0) {
                    hasSections = true;
                    msg += `🟢 *العطل والمناسبات الرسمية:*\n`;
                    data.holidays.forEach(item => {
                        msg += `  • ${item}\n`;
                    });
                    msg += `\n`;
                }
            }

            // Timetable Classes
            if (cfg.includeTimetable !== false) {
                if (data.timetableClasses.length > 0) {
                    hasSections = true;
                    msg += `📚 *حصص التدريس المبرمجة لليوم:*\n`;
                    data.timetableClasses.forEach(item => {
                        msg += `  • ${item}\n`;
                    });
                    msg += `\n`;
                }
            }

            if (!hasSections) {
                msg += `✨ *ملاحظة:* لا توجد أي فروض، اجتماعات، أو واجبات خاصة مسجلة في التقويم لهذا اليوم.\n\n`;
            }

            msg += `━━━━━━━━━━━━━━━━━━━━━\n`;
            msg += `✨ *نتمنى لكم يوماً تربوياً مباركاً ومثمراً بالتوفيق والنجاح!*`;

            return {
                text: msg,
                summary: data
            };
        }

        function playNotificationChime() {
            try {
                const AudioContextClass = window.AudioContext || window.webkitAudioContext;
                if (!AudioContextClass) return;
                const ctx = new AudioContextClass();
                const now = ctx.currentTime;
                
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.type = 'sine';
                
                // Two-tone bell melody (D5 -> A5)
                osc.frequency.setValueAtTime(587.33, now);
                osc.frequency.setValueAtTime(880, now + 0.12);
                
                gain.gain.setValueAtTime(0.2, now);
                gain.gain.exponentialRampToValueAtTime(0.001, now + 0.6);
                
                osc.connect(gain);
                gain.connect(ctx.destination);
                
                osc.start(now);
                osc.stop(now + 0.65);
            } catch (e) {
                console.log('Audio chime not supported or muted');
            }
        }

