        // Daily 8:00 AM Scheduler Engine
        var calendarWhatsappSchedulerInterval = null;

        function checkCalendarWhatsappScheduler() {
            const cfg = getCalendarWhatsappConfig();
            if (!cfg || cfg.enabled === false) return;

            const now = new Date();
            const currentHour = now.getHours();
            const currentMinute = now.getMinutes();
            const todayStr = getTodayDateString(now);

            const [targetH, targetM] = (cfg.time || '08:00').split(':').map(Number);
            const schedHour = isNaN(targetH) ? 8 : targetH;
            const schedMinute = isNaN(targetM) ? 0 : targetM;

            // Check if current time has reached or passed scheduled time today
            const hasReachedTime = (currentHour > schedHour) || (currentHour === schedHour && currentMinute >= schedMinute);

            if (hasReachedTime && cfg.lastNotifiedDate !== todayStr) {
                cfg.lastNotifiedDate = todayStr;
                saveDB();
                triggerDaily8AmWhatsappAlert(todayStr);
            }
        }

        function initCalendarWhatsappScheduler() {
            syncCalendarWhatsappUI();
            if (calendarWhatsappSchedulerInterval) {
                clearInterval(calendarWhatsappSchedulerInterval);
            }
            // Check every 30 seconds
            calendarWhatsappSchedulerInterval = setInterval(checkCalendarWhatsappScheduler, 30000);
            // Check immediately on startup
            setTimeout(checkCalendarWhatsappScheduler, 2000);
        }

        // Expose functions to window
        window.getCalendarWhatsappConfig = getCalendarWhatsappConfig;
        window.openCalendarWhatsappModal = openCalendarWhatsappModal;
        window.closeCalendarWhatsappModal = closeCalendarWhatsappModal;
        window.updateCalendarWaModalPreview = updateCalendarWaModalPreview;
        window.saveCalendarWhatsappSettings = saveCalendarWhatsappSettings;
        window.copyCalendarWaMessage = copyCalendarWaMessage;
        window.copyCalendarWaMessageFromAlert = copyCalendarWaMessageFromAlert;
        window.sendTodayWhatsappReminderNow = sendTodayWhatsappReminderNow;
        window.requestWaNotificationPermission = requestWaNotificationPermission;
        window.closeDaily8AmAlert = closeDaily8AmAlert;
        window.syncCalendarWhatsappUI = syncCalendarWhatsappUI;
        window.triggerDaily8AmWhatsappAlert = triggerDaily8AmWhatsappAlert;

        // Initialize scheduler on load
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', initCalendarWhatsappScheduler);
        } else {
            initCalendarWhatsappScheduler();
        }


        function showTabletReport(className, studentId) {
            if (window.innerWidth < 992) {
                // If on mobile, just jump to the full report view
                jumpToIndividualReport(className, studentId);
                return;
            }

            // Enable tablet split mode
            document.body.classList.add('tablet-split-mode');
            
            const std = (db.classes[className] || []).find(s => s.id === studentId);
            if (!std) return;

            const content = document.getElementById('tabletReportContent');
            
            const today = new Date();
            const firstDay = new Date(today.getFullYear(), today.getMonth(), 1);
            const dateFrom = formatLocalDate(firstDay);
            const dateTo = formatLocalDate(today);

            const stdRecords = db.records.filter(r => r.studentId === studentId && r.className === className);
            const absentHours = stdRecords.filter(r => r.status === 'غائب' || r.status === 'مبرر').reduce((sum, r) => sum + (r.duration || 1), 0);
            const justifiedHours = stdRecords.filter(r => r.status === 'مبرر').reduce((sum, r) => sum + (r.duration || 1), 0);
            const unjustifiedHours = stdRecords.filter(r => r.status === 'غائب').reduce((sum, r) => sum + (r.duration || 1), 0);
            const lateCount = stdRecords.filter(r => r.status === 'متأخر').length;
            const missedHw = stdRecords.filter(r => r.homework === 'لم ينجز').length;

            const behaviorData = (db.behaviors[className] && db.behaviors[className][studentId]) ? db.behaviors[className][studentId] : { status: 'منضبط', note: '' };
            let statusColor = '#16a34a';
            if (behaviorData.status === 'تنبيه') statusColor = '#ea580c';
            else if (behaviorData.status === 'مشوش') statusColor = '#dc2626';

            const grades = (db.grades[className] && db.grades[className][studentId]) ? db.grades[className][studentId] : {};
            const examCount = getExamsCountForClass(className);
            const avg = calculateStudentAvg(grades, className);
            const coef = getSubjectCoefForClass(className);
            const weightedAvg = avg !== null ? (avg * coef).toFixed(2) : '-';

            content.innerHTML = `
                <div style="text-align: center; margin-bottom: 15px;">
                    <div style="width: 50px; height: 50px; border-radius: 50%; background: #e0e7ff; color: #4338ca; display: flex; align-items: center; justify-content: center; font-size: 1.5rem; font-weight: bold; margin: 0 auto 10px;">
                        ${std.name.charAt(0)}
                    </div>
                    <h4 style="color: var(--text-dark); margin: 0; font-size: 1.1rem;">${std.name}</h4>
                    <div style="font-size: 0.8rem; color: var(--text-muted); margin-top: 4px;">الرقم الترتيبي: ${std.orderNum} | رقم مسار: ${std.massar || '-'}</div>
                </div>

                <div style="background: #f8fafc; padding: 12px; border-radius: 8px; border: 1px solid #e2e8f0; margin-bottom: 15px;">
                    <h5 style="color: var(--primary); margin: 0 0 10px; font-size: 0.9rem;">السلوك والمواظبة العام</h5>
                    <div style="display: flex; justify-content: space-between; margin-bottom: 6px; font-size: 0.85rem;">
                        <span style="color: var(--text-muted);">السلوك:</span>
                        <span style="font-weight: bold; color: ${statusColor};">${behaviorData.status}</span>
                    </div>
                    ${behaviorData.note ? `<div style="font-size: 0.8rem; color: #64748b; background: #fff; padding: 6px; border-radius: 4px; border: 1px dashed #cbd5e1; margin-bottom: 8px;">"${behaviorData.note}"</div>` : ''}
                    
                    <div style="display: flex; justify-content: space-between; margin-bottom: 6px; font-size: 0.85rem;">
                        <span style="color: var(--text-muted);">إجمالي الغياب:</span>
                        <span style="font-weight: bold; color: ${absentHours > 0 ? 'var(--danger)' : 'var(--text-dark)'};">${absentHours} س</span>
                    </div>
                    <div style="display: flex; justify-content: space-between; margin-bottom: 6px; font-size: 0.85rem;">
                        <span style="color: var(--text-muted);">غير مبرر / مبرر:</span>
                        <span style="font-weight: bold; color: var(--text-dark);">${unjustifiedHours} / ${justifiedHours}</span>
                    </div>
                    <div style="display: flex; justify-content: space-between; margin-bottom: 6px; font-size: 0.85rem;">
                        <span style="color: var(--text-muted);">التأخرات:</span>
                        <span style="font-weight: bold; color: ${lateCount > 0 ? '#f59e0b' : 'var(--text-dark)'};">${lateCount}</span>
                    </div>
                    <div style="display: flex; justify-content: space-between; font-size: 0.85rem;">
                        <span style="color: var(--text-muted);">إخلال بالواجب:</span>
                        <span style="font-weight: bold; color: ${missedHw > 0 ? '#b91c1c' : 'var(--text-dark)'};">${missedHw}</span>
                    </div>
                </div>

                <div style="background: #f8fafc; padding: 12px; border-radius: 8px; border: 1px solid #e2e8f0; margin-bottom: 15px;">
                    <h5 style="color: var(--primary); margin: 0 0 10px; font-size: 0.9rem;">النتائج والتقييم الأكاديمي</h5>
                    <div style="display: flex; justify-content: space-between; margin-bottom: 6px; font-size: 0.85rem;">
                        <span style="color: var(--text-muted);">المعدل الفصلي:</span>
                        <span style="font-weight: bold; color: ${avg >= 10 ? 'var(--success)' : (avg !== null ? 'var(--danger)' : 'var(--text-dark)')};">${avg !== null ? avg.toFixed(2) : '-'} / 20</span>
                    </div>
                    ${coef > 1 ? `<div style="display: flex; justify-content: space-between; margin-bottom: 6px; font-size: 0.85rem;">
                        <span style="color: var(--text-muted);">المعدل بالمعامل (x${coef}):</span>
                        <span style="font-weight: bold; color: var(--text-dark);">${weightedAvg}</span>
                    </div>` : ''}
                </div>

                <div style="display: flex; gap: 8px; flex-wrap: wrap;">
                    <button class="btn-primary" onclick="jumpToIndividualReport('${className}', '${std.id}')" style="flex: 1; font-size: 0.8rem; padding: 8px;">عرض التقرير الكامل</button>
                    <button type="button" class="btn-secondary" onclick="if(window.openShareRecordModal) window.openShareRecordModal({ type: 'student', className: '${className}', studentId: '${std.id}', studentName: '${escapeHtml(std.name)}' })" style="padding: 8px 12px; font-size: 0.8rem; background: #fdf4ff; border: 1.5px solid #f0abfc; color: #86198f; font-weight: 800; border-radius: 6px; cursor: pointer; display: inline-flex; align-items: center; gap: 4px;" title="مشاركة السجل مع الزملاء عبر رمز QR أو رابط مباشر مشفر">
                        <span class="ui-icon" style="margin: 0;"><span data-lucide="qr-code" data-size="14"></span></span>
                        <span>مشاركة (QR)</span>
                    </button>
                </div>
            `;

            if (window.renderLucide) window.renderLucide();
            
            // smooth scroll top 
            document.getElementById('tabletReportPane').scrollTo({ top: 0, behavior: 'smooth' });
        }

        function closeTabletReport() {
            document.body.classList.remove('tablet-split-mode');
        }


