        function onLessonLogClassSelectChanged(className) {
            if (typeof renderLessonLogs === 'function') {
                renderLessonLogs();
            }
            autoAlignLessonLogWithTimetable(null, { isClassChange: true, showToast: false });
        }

        function onLessonLogDateChanged() {
            const dateVal = document.getElementById('lessonLogDate')?.value;
            const tag = document.getElementById('lessonLogDayTag');

            if (dateVal) {
                const day = getArabicDayName(dateVal);
                if (tag) tag.textContent = day || 'تاريخ محدد';
            } else {
                if (tag) tag.textContent = 'اليوم الحالي';
            }

            // مواءمة الحصة آلياً فور تغيير التاريخ
            autoAlignLessonLogWithTimetable(null, { isDateChange: true, showToast: false });

            if (typeof renderCalendarExamSuggestions === 'function') {
                const sType = document.getElementById('lessonLogSessionType')?.value;
                if (sType === 'controle') {
                    renderCalendarExamSuggestions();
                }
            }
        }

        function syncSessionFromTimetable() {
            autoAlignLessonLogWithTimetable(null, { showToast: true, force: true, userTriggered: true });
        }

        function setLessonLogAsRemedialSupport() {
            const typeSelect = document.getElementById('lessonLogSessionType');
            if (typeSelect) {
                typeSelect.value = 'soutien';
                onLessonLogSessionTypeChanged('soutien');
            }
            const remedialBox = document.getElementById('lessonLogRemedialBox');
            if (remedialBox) remedialBox.style.display = 'block';
            const outOfScheduleCheck = document.getElementById('lessonLogOutOfScheduleCheck');
            if (outOfScheduleCheck) outOfScheduleCheck.checked = true;
            showAppToast('تم تحويل الحصة إلى حصة دعم واستدراك خارج الجدول الرسمي 💡', 'info');
        }

        function updateLessonLogStats(className) {
            if (!className) return;
            if (!db.lessonLogs) db.lessonLogs = {};
            const logs = db.lessonLogs[className] || [];

            const totalSessionsEl = document.getElementById('statClassTotalSessions');
            const totalHoursEl = document.getElementById('statClassTotalHours');
            const extraSupportEl = document.getElementById('statClassExtraSupportSessions');
            const lastDateEl = document.getElementById('statClassLastDate');
            const lastLessonEl = document.getElementById('statClassLastLesson');
            const nextSessionBadge = document.getElementById('lessonLogNextSessionBadge');

            if (totalSessionsEl) totalSessionsEl.textContent = logs.length;

            let totalHours = 0;
            let extraSupportCount = 0;
            let extraSupportHours = 0;

            logs.forEach(l => {
                const dur = parseFloat(l.duration);
                const actualH = (!isNaN(dur) ? dur : 2);
                totalHours += actualH;
                if (l.isExtraSession || l.isRemedial || l.outOfSchedule || l.sessionType === 'soutien' || l.sessionType === 'rattrapage') {
                    extraSupportCount++;
                    extraSupportHours += actualH;
                }
            });
            if (totalHoursEl) totalHoursEl.textContent = `${totalHours} س`;
            if (extraSupportEl) extraSupportEl.textContent = `${extraSupportCount} (${extraSupportHours}س)`;

            if (logs.length > 0) {
                // sort chronologically to find latest
                const sorted = [...logs].sort((a, b) => (b.date || '').localeCompare(a.date || ''));
                if (lastDateEl) lastDateEl.textContent = sorted[0].date || '-';
                if (lastLessonEl) lastLessonEl.textContent = sorted[0].number || sorted[0].title || 'درس مسجل';
            } else {
                if (lastDateEl) lastDateEl.textContent = 'لا توجد حصص';
                if (lastLessonEl) lastLessonEl.textContent = 'لا يوجد';
            }

            if (nextSessionBadge) {
                nextSessionBadge.textContent = `الحصة القادمة المقترحة: #${logs.length + 1}`;
            }

            // Auto suggest next session number in form if not editing
            if (!window._editingLessonLog) {
                const sessionNumInput = document.getElementById('lessonLogSessionNum');
                if (sessionNumInput && !sessionNumInput.value) {
                    sessionNumInput.value = logs.length + 1;
                }
            }
        }

        // --- Enhanced Multiple Axes & Paragraphs Management (كل محور به فقرات ومحتوى خاص ولون مخصص) ---
        const LESSON_PARAGRAPH_TYPES = {
            'construct': { label: '🏗️ نشاط بناء (مفهوم / خاصية)', badge: 'نشاط بناء', color: '#1d4ed8', bg: '#eff6ff', border: '#bfdbfe' },
            'application': { label: '📐 تطبيق (أمثلة وتطبيق مباشر)', badge: 'تطبيق', color: '#166534', bg: '#f0fdf4', border: '#bbf7d0' },
            'synthesis': { label: '🧩 تمرين توليفي (مسألة توليفية)', badge: 'تمرين توليفي', color: '#7c3aed', bg: '#faf5ff', border: '#ddd6fe' },
            'evaluation': { label: '⚡ تقويم تكويني ودعم', badge: 'تقويم تكويني', color: '#dc2626', bg: '#fef2f2', border: '#fecaca' },
            'summary': { label: '📝 خلاصة وقاعدة رياضية', badge: 'خلاصة وقاعدة', color: '#334155', bg: '#f8fafc', border: '#cbd5e1' },
            // Mappings for full backward compatibility
            'activity': { label: '🏗️ نشاط بناء (مفهوم / خاصية)', badge: 'نشاط بناء', color: '#1d4ed8', bg: '#eff6ff', border: '#bfdbfe' },
            'property': { label: '🏗️ نشاط بناء (مبرهنة وخاصية)', badge: 'نشاط بناء', color: '#1d4ed8', bg: '#eff6ff', border: '#bfdbfe' },
            'exercise': { label: '📐 تطبيق (تمرين تطبيقي)', badge: 'تطبيق', color: '#166534', bg: '#f0fdf4', border: '#bbf7d0' },
            'example': { label: '📐 تطبيق (أمثلة نموذجية)', badge: 'تطبيق', color: '#166534', bg: '#f0fdf4', border: '#bbf7d0' },
            'problem': { label: '🧩 تمرين توليفي (مسألة توليفية)', badge: 'تمرين توليفي', color: '#7c3aed', bg: '#faf5ff', border: '#ddd6fe' }
        };

        const AXIS_COLOR_PALETTES = [
            { id: 'white', label: 'كلاسيكي (أبيض)', bg: '#ffffff', border: '#cbd5e1' },
            { id: 'blue', label: 'أزرق سماوي', bg: '#eff6ff', border: '#bfdbfe' },
            { id: 'green', label: 'أخضر نعناعي', bg: '#f0fdf4', border: '#bbf7d0' },
            { id: 'amber', label: 'كهرماني دافئ', bg: '#fffbeb', border: '#fde68a' },
            { id: 'purple', label: 'بنفسجي هادئ', bg: '#faf5ff', border: '#ddd6fe' },
            { id: 'rose', label: 'وردي لطيف', bg: '#fff1f2', border: '#fecdd3' },
            { id: 'cyan', label: 'سماوي مائي', bg: '#ecfeff', border: '#a5f3fc' }
        ];

        function setLessonLogAxisColor(dotEl, bg, border) {
            const axisCard = dotEl.closest('.lesson-log-axis-card');
            if (!axisCard) return;
            axisCard.style.backgroundColor = bg;
            axisCard.style.borderColor = border || '#cbd5e1';
            axisCard.dataset.color = bg;
            const parentBar = dotEl.closest('.axis-color-picker-bar');
            if (parentBar) {
                parentBar.querySelectorAll('.axis-color-dot').forEach(d => d.classList.remove('active'));
                dotEl.classList.add('active');
                const colorInp = parentBar.querySelector('.axis-color-input-btn');
                if (colorInp) colorInp.value = bg.length === 7 ? bg : '#ffffff';
            }
            updateLessonLogTitleHidden();
        }

        function setLessonLogAxisCustomColor(colorInp) {
            const axisCard = colorInp.closest('.lesson-log-axis-card');
            if (!axisCard) return;
            const bg = colorInp.value || '#ffffff';
            axisCard.style.backgroundColor = bg;
            axisCard.style.borderColor = '#93c5fd';
            axisCard.dataset.color = bg;
            const parentBar = colorInp.closest('.axis-color-picker-bar');
            if (parentBar) {
                parentBar.querySelectorAll('.axis-color-dot').forEach(d => d.classList.remove('active'));
            }
            updateLessonLogTitleHidden();
        }

        function renumberLessonLogSubparagraphs(axisCard) {
            if (!axisCard) return;
            const axisNum = axisCard.dataset.axisIndex || '1';
            const subCards = axisCard.querySelectorAll('.axis-subparagraph-card');
            subCards.forEach((sc, sIdx) => {
                const badge = sc.querySelector('.subparagraph-badge');
                if (badge) badge.textContent = `فرعية ${axisNum}.${sIdx + 1}`;
            });
        }

        function getLessonLogAxesStructured() {
            const container = document.getElementById('lessonLogAxesContainer');
            if (!container) return [];
            const axisCards = container.querySelectorAll('.lesson-log-axis-card');
            const structured = [];

            axisCards.forEach((axisCard, aIdx) => {
                const titleInput = axisCard.querySelector('.lesson-log-axis-title-input');
                const axisTitle = titleInput ? titleInput.value.trim() : '';
                const axisColor = axisCard.dataset.color || '#ffffff';
                const techNotes = axisCard.querySelector('.axis-tech-general-notes')?.value?.trim() || '';
                
                // Multi-session in same axis attributes
                const continuationMode = axisCard.querySelector('.axis-continuation-mode-select')?.value;
                const isContinuation = (continuationMode === 'continuation') || (axisCard.dataset.isContinuation === 'true');
                const parentAxisNum = parseInt(axisCard.dataset.parentAxisNum || 0) || null;
                const sessionIndexInAxis = parseInt(axisCard.dataset.sessionIndexInAxis || 0) || (isContinuation ? 2 : 1);
                const axisStage = axisCard.querySelector('.axis-stage-select')?.value || axisCard.dataset.axisStage || (isContinuation ? 'applications' : 'construct');
                const parentAxisTitle = axisCard.dataset.parentAxisTitle || (isContinuation ? axisTitle : '');

                const paragraphs = [];

                const pCards = axisCard.querySelectorAll('.axis-paragraph-card');
                pCards.forEach((pCard, pIdx) => {
                    const pTitleInput = pCard.querySelector('.paragraph-title-input');
                    const pTypeSelect = pCard.querySelector('.paragraph-type-select');
                    const pContentInput = pCard.querySelector('.paragraph-content-textarea');
                    const pTechInput = pCard.querySelector('.paragraph-tech-input');
                    const pResourceTitle = pCard.querySelector('.paragraph-resource-title-input')?.value?.trim() || '';
                    const pResourceLink = pCard.querySelector('.paragraph-resource-link-input')?.value?.trim() || '';

                    const pTitle = pTitleInput ? pTitleInput.value.trim() : '';
                    const pType = pTypeSelect ? pTypeSelect.value : 'construct';
                    const pContent = pContentInput ? pContentInput.value.trim() : '';
                    const pTech = pTechInput ? pTechInput.value.trim() : '';

                    if (pTitle || pContent || pTech || pResourceLink || pResourceTitle) {
                        paragraphs.push({
                            id: pCard.dataset.pId || `p_${aIdx + 1}_${pIdx + 1}`,
                            title: pTitle,
                            type: pType,
                            content: pContent,
                            techContent: pTech,
                            resourceTitle: pResourceTitle,
                            resourceLink: pResourceLink
                        });
                    }
                });

                const subParagraphs = [];
                const subCards = axisCard.querySelectorAll('.axis-subparagraph-card');
                subCards.forEach((sc, sIdx) => {
                    const sTitle = sc.querySelector('.subparagraph-title-input')?.value?.trim() || '';
                    const sType = sc.querySelector('.subparagraph-type-select')?.value || 'tech';
                    const sContent = sc.querySelector('.subparagraph-content-textarea')?.value?.trim() || '';
                    if (sTitle || sContent) {
                        subParagraphs.push({
                            id: sc.dataset.subId || `sub_${aIdx + 1}_${sIdx + 1}`,
                            title: sTitle,
                            type: sType,
                            content: sContent
                        });
                    }
                });

                if (axisTitle || paragraphs.length > 0 || subParagraphs.length > 0 || techNotes || isContinuation) {
                    structured.push({
                        id: axisCard.dataset.axisId || `axis_${aIdx + 1}`,
                        title: axisTitle,
                        color: axisColor,
                        techNotes: techNotes,
                        isContinuation: isContinuation,
                        parentAxisNum: parentAxisNum,
                        sessionIndexInAxis: sessionIndexInAxis,
                        axisStage: axisStage,
                        parentAxisTitle: parentAxisTitle,
                        paragraphs: paragraphs.length > 0 ? paragraphs : [
                            {
                                id: `p_${aIdx + 1}_1`,
                                title: '',
                                type: 'construct',
                                content: '',
                                techContent: ''
                            }
                        ],
                        subParagraphs: subParagraphs
                    });
                }
            });

            return structured;
        }

        function getLessonLogAxesValues() {
            const structured = getLessonLogAxesStructured();
            if (structured.length > 0) {
                return structured.map(a => a.title).filter(Boolean);
            }
            const fallback = document.getElementById('lessonLogTitle')?.value?.trim();
            return fallback ? [fallback] : [];
        }

        const LESSON_AXIS_STAGES = {
            'construct': { label: 'بناء المفهوم والبرهان', badge: '🏗️ بناء المفهوم' },
            'applications': { label: 'تطبيقات وأمثلة موجهة', badge: '📐 تطبيقات' },
            'exercises': { label: 'تمارين وتثبيت المكتسبات', badge: '✏️ تمارين وتثبيت' },
            'synthesis': { label: 'مسائل توليفية وتعميق', badge: '🎯 مسألة وتعميق' },
            'evaluation': { label: 'تقويم تكويني ودعم', badge: '⚡ تقويم ودعم' }
        };

        /**
         * تنقية النصوص البيداغوجية لدفتر النصوص من العبارات الآلية المكررة (مثل استكمال حصة / الحصة الثانية في هذا المحور)
         */
        function cleanPedagogicalLogText(text, stripEmojis = false) {
            if (!text) return '';
            let cleaned = String(text);
            // حذف عبارات (استكمال - الحصة 2 في هذا المحور) أو (استكمال - حصة 2) أو (الحصة الثانية في هذا المحور)
            cleaned = cleaned.replace(/\(\s*استكمال\s*[-–—:]?\s*(?:الحصة|حصة)?\s*\d*[^)]*\)/gi, '');
            cleaned = cleaned.replace(/\(\s*(?:الحصة|حصة)\s*(?:الأولى|الثانية|الثالثة|الرابعة|الخامسة|\d+)\s*(?:في\s*هذا\s*المحور|في\s*نفس\s*المحور|من\s*أصل\s*\d+[^)]*)\s*\)/gi, '');
            cleaned = cleaned.replace(/(?:[-–—•|]\s*)?(?:استكمال\s+المحور\s*:\s*الحصة\s*\d+(?:\s*من\s*\d+)?)/gi, '');
            cleaned = cleaned.replace(/(?:[-–—•|]\s*)?(?:استكمال\s+حصة|استكمال\s+الحصة|الحصة\s+الثانية\s+في\s+هذا\s+المحور|الحصة\s+الثالثة\s+في\s+هذا\s+المحور|حصة\s+\d+\s+في\s+(?:هذا|نفس)\s+المحور)/gi, '');
            cleaned = cleaned.replace(/^\s*📌?\s*مرحلة الإنجاز في هذا المحور\s*:.*$/gm, '');
            cleaned = cleaned.replace(/استكمال ومتابعة أنشطة\s*:\s*/g, 'أنشطة وتطبيقات: ');
            cleaned = cleaned.replace(/استكمال بناء المفاهيم والخاصيات ومتابعة الأنشطة المبرمجة للمحور\.?/g, 'بناء المفاهيم والخاصيات المؤطرة وإنجاز الأنشطة التطبيقية المبرمجة.');

            if (stripEmojis) {
                cleaned = cleaned.replace(/[🏗️📐✏️🎯⚡⚙️💡🎥📝📌🔄⏳🎬🔗📚📖🔍✅]/g, '');
                // تحويل(🏗️ بناء مفهوم) إلى (بناء مفهوم)
                cleaned = cleaned.replace(/\(\s+/g, '(').replace(/\s+\)/g, ')');
            }

            // تنظيف الفراغات والأسطر الفارغة الزائدة
            cleaned = cleaned.replace(/[ \t]{2,}/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
            return cleaned;
        }
        window.cleanPedagogicalLogText = cleanPedagogicalLogText;

        function compileAxesToSummary() {
            const axes = getLessonLogAxesStructured();
            if (!axes || axes.length === 0) return '';
            const sections = [];

            axes.forEach((ax, aIdx) => {
                const axNum = ax.parentAxisNum || (aIdx + 1);
                const cleanTitle = cleanPedagogicalLogText(ax.title || '');
                const axTitle = cleanTitle ? `المحور ${axNum}: ${cleanTitle}` : `المحور ${axNum}`;

                const lines = [`【 ${axTitle} 】`];

                if (ax.paragraphs && ax.paragraphs.length > 0) {
                    ax.paragraphs.forEach((p, pIdx) => {
                        const pNum = `${axNum}.${pIdx + 1}`;
                        const typeInfo = LESSON_PARAGRAPH_TYPES[p.type] || LESSON_PARAGRAPH_TYPES.construct;
                        const cleanPTitle = cleanPedagogicalLogText(p.title || '');
                        const pHead = cleanPTitle
                            ? `  • فقرة ${pNum}: ${cleanPTitle} (${typeInfo.label || typeInfo.badge})`
                            : `  • فقرة ${pNum} (${typeInfo.label || typeInfo.badge})`;
                        lines.push(pHead);
                        if (p.content && p.content.trim()) {
                            lines.push(`    - المضامين والأنشطة: ${cleanPedagogicalLogText(p.content.trim())}`);
                        }
                        if (p.techContent && p.techContent.trim()) {
                            lines.push(`    - إضاءات ديداكتيكية وتقنية: ${cleanPedagogicalLogText(p.techContent.trim())}`);
                        }
                    });
                }

                if (ax.subParagraphs && ax.subParagraphs.length > 0) {
                    lines.push('  • فقرات فرعية وتقنية:');
                    ax.subParagraphs.forEach((sub, sIdx) => {
                        const subNum = `${axNum}.${sIdx + 1}`;
                        lines.push(`    - فرعية ${subNum}: ${cleanPedagogicalLogText(sub.title || 'فقرة فرعية')} : ${cleanPedagogicalLogText(sub.content || '')}`);
                    });
                }

                if (ax.techNotes && ax.techNotes.trim()) {
                    lines.push(`  • توجيهات وملاحظات بيداغوجية: ${cleanPedagogicalLogText(ax.techNotes.trim())}`);
                }

                sections.push(lines.join('\n'));
            });

            return sections.join('\n\n');
        }

        function normalizeLessonTitle(title) {
            if (!title) return '';
            return String(title).trim().replace(/[إأآا]/g, 'ا').replace(/ة/g, 'ه').replace(/\s+/g, ' ').toLowerCase();
        }

        function getLessonAxesSequenceInfo(className) {
            if (!className || !db || !db.lessonLogs || !db.lessonLogs[className]) {
                return { byLogId: {}, lessonsMap: {}, lessonTitles: [] };
            }
            const logs = [...db.lessonLogs[className]];
            // Sort chronologically ascending
            logs.sort((a, b) => {
                const da = new Date(a.date || 0);
                const db = new Date(b.date || 0);
                if (da - db !== 0) return da - db;
                return (parseInt(a.sessionNum || 0) || 0) - (parseInt(b.sessionNum || 0) || 0);
            });

            const lessonsMap = {};
            const byLogId = {};

            logs.forEach(log => {
                const rawTitle = (log.number || log.title || 'درس غير محدد').trim();
                const normKey = normalizeLessonTitle(rawTitle);
                if (!lessonsMap[normKey]) {
                    lessonsMap[normKey] = {
                        title: rawTitle,
                        normKey: normKey,
                        sessions: [],
                        totalAxes: 0,
                        distinctAxes: [],
                        axes: []
                    };
                }
                lessonsMap[normKey].sessions.push(log);

                const logAxes = Array.isArray(log.axes) ? log.axes : [];
                const logAxesInfo = [];

                logAxes.forEach((ax, aIdx) => {
                    const axisObj = (typeof ax === 'object' && ax !== null) ? ax : { title: String(ax) };
                    const axTitle = (axisObj.title || '').trim();
                    const normAxisTitle = normalizeLessonTitle(axTitle);

                    // Check if this axis matches an existing distinct axis in this lesson
                    let matchedDistinctAxis = null;
                    if (normAxisTitle) {
                        matchedDistinctAxis = lessonsMap[normKey].distinctAxes.find(da => {
                            if (da.normTitle === normAxisTitle) return true;
                            if (axisObj.parentAxisTitle && normalizeLessonTitle(axisObj.parentAxisTitle) === da.normTitle) return true;
                            if (axisObj.parentAxisNum && da.globalAxisNum === axisObj.parentAxisNum) return true;
                            return false;
                        });
                    }

                    let globalAxisNum;
                    let sessionIndexInAxis;
                    let isContinuation = false;
                    let previousSessionInfo = null;

                    if (matchedDistinctAxis) {
                        // Continuation / subsequent session in the same axis!
                        globalAxisNum = matchedDistinctAxis.globalAxisNum;
                        matchedDistinctAxis.sessions.push({
                            logId: log.id,
                            sessionNum: log.sessionNum,
                            date: log.date,
                            timeSlot: log.timeSlot,
                            duration: log.duration || '2',
                            lessonTitle: rawTitle,
                            axisTitle: axTitle,
                            stage: axisObj.axisStage || 'applications',
                            paragraphsCount: Array.isArray(axisObj.paragraphs) ? axisObj.paragraphs.length : 0
                        });
                        sessionIndexInAxis = matchedDistinctAxis.sessions.length;
                        isContinuation = true;
                        previousSessionInfo = matchedDistinctAxis.sessions[matchedDistinctAxis.sessions.length - 2] || null;
                    } else {
                        // New distinct axis in this lesson
                        globalAxisNum = lessonsMap[normKey].distinctAxes.length + 1;
                        sessionIndexInAxis = 1;
                        isContinuation = (axisObj.isContinuation === true && (axisObj.sessionIndexInAxis > 1));
                        if (isContinuation && axisObj.sessionIndexInAxis) {
                            sessionIndexInAxis = axisObj.sessionIndexInAxis;
                        }
                        const newDistinct = {
                            globalAxisNum,
                            title: axTitle || `المحور ${globalAxisNum}`,
                            normTitle: normAxisTitle,
                            lessonTitle: rawTitle,
                            normKey: normKey,
                            sessions: [{
                                logId: log.id,
                                sessionNum: log.sessionNum,
                                date: log.date,
                                timeSlot: log.timeSlot,
                                duration: log.duration || '2',
                                lessonTitle: rawTitle,
                                axisTitle: axTitle,
                                stage: axisObj.axisStage || 'construct',
                                paragraphsCount: Array.isArray(axisObj.paragraphs) ? axisObj.paragraphs.length : 0
                            }]
                        };
                        lessonsMap[normKey].distinctAxes.push(newDistinct);
                        matchedDistinctAxis = newDistinct;
                    }

                    const info = {
                        globalAxisNum,
                        localAxisNum: aIdx + 1,
                        lessonTitle: lessonsMap[normKey].title,
                        normKey,
                        logId: log.id,
                        sessionNum: log.sessionNum,
                        date: log.date,
                        timeSlot: log.timeSlot,
                        axis: axisObj,
                        isContinuation,
                        sessionIndexInAxis,
                        axisStage: axisObj.axisStage || (sessionIndexInAxis > 1 ? 'applications' : 'construct'),
                        previousSession: previousSessionInfo,
                        distinctAxisRef: matchedDistinctAxis
                    };

                    logAxesInfo.push(info);
                    lessonsMap[normKey].axes.push(info);
                });

                byLogId[log.id] = {
                    lessonTitle: lessonsMap[normKey].title,
                    normKey,
                    axesInfo: logAxesInfo
                };
            });

            // Finalize totalAxes for each lesson as count of DISTINCT axes and attach totalSessions
            Object.values(lessonsMap).forEach(l => {
                l.totalAxes = l.distinctAxes.length;
                l.axes.forEach(info => {
                    if (info.distinctAxisRef) {
                        info.axisTotalSessions = info.distinctAxisRef.sessions.length;
                        info.allSessionsOfAxis = info.distinctAxisRef.sessions;
                    } else {
                        info.axisTotalSessions = 1;
                    }
                });
            });

            const lessonTitles = Object.values(lessonsMap).map(l => ({
                title: l.title,
                normKey: l.normKey,
                sessionsCount: l.sessions.length,
                axesCount: l.totalAxes
            }));

            return { byLogId, lessonsMap, lessonTitles };
        }

        // --- Annual Curriculum Distribution & Axes Progress Calculation Engine (مؤشر تقدم إنجاز محاور التوزيع السنوي) ---
