        let _mathSymbolActiveCategory = 'all';

        function openMathSymbolsPaletteModal() {
            const modal = document.getElementById('mathSymbolsPaletteModal');
            if (!modal) return;
            modal.style.display = 'flex';
            const searchInput = document.getElementById('mathSymbolSearchInput');
            if (searchInput) {
                searchInput.value = '';
                setTimeout(() => searchInput.focus(), 120);
            }
            _mathSymbolActiveCategory = 'all';
            renderMathSymbolsPalette('all', '');
            if (window.renderLucide) window.renderLucide(modal);
            if (window.lucide) window.lucide.createIcons();
        }

        function closeMathSymbolsPaletteModal() {
            const modal = document.getElementById('mathSymbolsPaletteModal');
            if (modal) modal.style.display = 'none';
        }

        function filterMathSymbolCategory(cat) {
            _mathSymbolActiveCategory = cat;
            const buttons = document.querySelectorAll('#mathSymbolCatFilters button');
            buttons.forEach(btn => btn.classList.remove('active'));
            const activeBtn = event && event.target ? event.target : null;
            if (activeBtn) activeBtn.classList.add('active');
            const searchVal = document.getElementById('mathSymbolSearchInput')?.value || '';
            renderMathSymbolsPalette(cat, searchVal);
        }

        function filterMathSymbols() {
            const searchVal = document.getElementById('mathSymbolSearchInput')?.value || '';
            renderMathSymbolsPalette(_mathSymbolActiveCategory, searchVal);
        }

        function renderMathSymbolsPalette(category, search) {
            const container = document.getElementById('mathSymbolsGrid');
            if (!container) return;

            const q = (search || '').trim().toLowerCase();
            const filtered = MATH_SYMBOLS_DATABASE.filter(item => {
                if (category !== 'all' && item.category !== category) return false;
                if (q) {
                    const str = `${item.symbol} ${item.name} ${item.latex || ''}`.toLowerCase();
                    if (!str.includes(q)) return false;
                }
                return true;
            });

            if (filtered.length === 0) {
                container.innerHTML = `
                    <div style="grid-column: 1 / -1; text-align: center; padding: 30px; color: #64748b;">
                        <span style="font-size: 2rem; display: block; margin-bottom: 6px;">🔍</span>
                        <div style="font-weight: 800; color: #334155;">لا يوجد رمز يطابق البحث</div>
                    </div>
                `;
                return;
            }

            container.innerHTML = filtered.map(item => {
                const safeSym = item.symbol.replace(/"/g, '&quot;');
                const safeName = item.name.replace(/"/g, '&quot;');
                return `
                    <div style="background: #f8fafc; border: 1.5px solid #e2e8f0; border-radius: 9px; padding: 8px 10px; display: flex; flex-direction: column; align-items: center; justify-content: center; cursor: pointer; transition: all 0.2s;" onmouseover="this.style.background='#eff6ff'; this.style.borderColor='#93c5fd'; this.style.transform='translateY(-2px)';" onmouseout="this.style.background='#f8fafc'; this.style.borderColor='#e2e8f0'; this.style.transform='none';" onclick="copyMathSymbol('${safeSym}', '${safeName}')" title="انقر لنسخ: ${safeName}">
                        <div style="font-size: 1.35rem; font-weight: 900; color: #1e3a8a; font-family: 'Times New Roman', serif; margin-bottom: 4px; text-align: center; min-height: 32px; display: flex; align-items: center; justify-content: center;">
                            ${item.symbol}
                        </div>
                        <div style="font-size: 0.68rem; color: #475569; text-align: center; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; width: 100%; font-weight: 700;">
                            ${item.name}
                        </div>
                    </div>
                `;
            }).join('');
        }

        function copyMathSymbol(symbol, name) {
            if (navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(symbol).then(() => {
                    showToast(`✅ تم نسخ الرمز (${symbol}) للحافظة! جاهز للصق المباشر في وثائقك.`, 'success');
                }).catch(() => {
                    fallbackCopyText(symbol);
                });
            } else {
                fallbackCopyText(symbol);
            }
        }

