        window.openPedagogicalLibraryPickerForParagraph = openPedagogicalLibraryPickerForParagraph;
        window.closePedagogicalLibraryPickerModal = closePedagogicalLibraryPickerModal;
        window.renderLibraryPickerItems = renderLibraryPickerItems;
        window.selectLibraryItemForParagraph = selectLibraryItemForParagraph;
        window.playLessonVideoModal = playLessonVideoModal;
        window.closeLessonVideoPlayerModal = closeLessonVideoPlayerModal;
        window.openParagraphResourceDirectly = openParagraphResourceDirectly;
        window.openPedagogicalLibraryPickerForSavedParagraph = openPedagogicalLibraryPickerForSavedParagraph;
        window.previewCurrentParagraphResource = previewCurrentParagraphResource;
        window.cleanLessonLogDuplicates = cleanLessonLogDuplicates;
        window.copyCahierDeTextesSummaryText = copyCahierDeTextesSummaryText;

        // Lesson Axes Reordering Across Sessions
        window.openReorderLessonAxesModal = openReorderLessonAxesModal;
        window.closeReorderLessonAxesModal = closeReorderLessonAxesModal;
        window.onReorderModalLessonChanged = onReorderModalLessonChanged;
        window.renderReorderModalAxesList = renderReorderModalAxesList;
        window.onReorderAxisTitleChanged = onReorderAxisTitleChanged;
        window.moveReorderAxis = moveReorderAxis;
        window.moveReorderAxisToTop = moveReorderAxisToTop;
        window.moveReorderAxisToBottom = moveReorderAxisToBottom;
        window.reassignReorderAxisSession = reassignReorderAxisSession;
        window.autoSequenceLessonAxesChronologically = autoSequenceLessonAxesChronologically;
        window.addNewAxisInReorderModal = addNewAxisInReorderModal;
