        window.onAxisDragEnd = onAxisDragEnd;
        window.saveReorderedLessonAxes = saveReorderedLessonAxes;
        window.onLessonLogNumberChanged = onLessonLogNumberChanged;
        window.updateLessonLogLessonsDatalist = updateLessonLogLessonsDatalist;
        window.updateLessonLogNumberHint = updateLessonLogNumberHint;
