        window.renderDashboardFocusModeCockpit = renderDashboardFocusModeCockpit;

        function getDashboardAtRiskStudents(opts = {}) {
            const filter = { ..._dashboardFilter, ...opts };
            const classes = Object.keys(db.classes || {});
            const rawList = [];
            const thresholdVal = filter.threshold === 'threshold' 
                ? (parseFloat(db.absenceThreshold) || 10) 
                : (parseFloat(filter.threshold) || 3);
            
            const records = db.records || [];
            let totalAbsentHoursSum = 0;
            const classStatsMap = {};

            // احتساب إجمالي ساعات الغياب التراكمية لجميع الأقسام ومقارنة التغير بالشهر السابق
            let grandTotalAbsenceHours = 0;
            let currentMonthAbsenceHours = 0;
            let previousMonthAbsenceHours = 0;

            const nowObj = (typeof getAppNow === 'function') ? getAppNow() : new Date();
            const curYear = nowObj.getFullYear();
            const curMonthNum = nowObj.getMonth(); // 0-based
            const curMonthPrefix = `${curYear}-${String(curMonthNum + 1).padStart(2, '0')}`;

            const prevMonthDate = new Date(curYear, curMonthNum - 1, 1);
            const prevMonthPrefix = `${prevMonthDate.getFullYear()}-${String(prevMonthDate.getMonth() + 1).padStart(2, '0')}`;

            for (let i = 0; i < records.length; i++) {
                const rec = records[i];
                if (rec && (rec.status === 'غائب' || rec.status === 'مبرر')) {
                    // استثناء الغياب المسجل في أيام العطل المدرسية الرسمية ورخص الأستاذ المعفاة تلقائياً
                    if (typeof isAbsenceDisabledOnDate === 'function' && isAbsenceDisabledOnDate(rec.date, rec.session)) {
                        continue;
                    }
                    const dur = (parseFloat(rec.duration) || 1);
                    grandTotalAbsenceHours += dur;
                    if (rec.date && typeof rec.date === 'string') {
                        if (rec.date.startsWith(curMonthPrefix)) {
                            currentMonthAbsenceHours += dur;
                        } else if (rec.date.startsWith(prevMonthPrefix)) {
                            previousMonthAbsenceHours += dur;
                        }
                    }
                }
            }

            let momPercentChange = 0;
            let momChangeType = 'flat'; // 'up', 'down', 'flat', 'new'
            if (previousMonthAbsenceHours > 0) {
                momPercentChange = Math.round(((currentMonthAbsenceHours - previousMonthAbsenceHours) / previousMonthAbsenceHours) * 100);
                if (momPercentChange > 0) {
                    momChangeType = 'up';
                } else if (momPercentChange < 0) {
                    momChangeType = 'down';
                } else {
                    momChangeType = 'flat';
                }
            } else if (currentMonthAbsenceHours > 0) {
                momPercentChange = 100;
                momChangeType = 'new';
            } else {
                momPercentChange = 0;
                momChangeType = 'flat';
            }

            classes.forEach(c => {
                classStatsMap[c] = { total: 0, dual: 0, absence: 0, behavior: 0, hwLate: 0 };
            });

            classes.forEach(className => {
                const studentList = db.classes[className] || [];
                const classBehaviors = (db.behaviors && db.behaviors[className]) || {};

                studentList.forEach(std => {
                    const studentId = std.id;

                    let unjustifiedHours = 0;
                    let justifiedHours = 0;
                    let lateCount = 0;
                    let lastAbsentDate = '';

                    for (let i = 0; i < records.length; i++) {
                        const r = records[i];
                        if (r.studentId === studentId && r.className === className) {
                            if (r.status === 'غائب') {
                                unjustifiedHours += (r.duration || 1);
                                if (!lastAbsentDate || r.date > lastAbsentDate) lastAbsentDate = r.date;
                            } else if (r.status === 'مبرر') {
                                justifiedHours += (r.duration || 1);
                                if (!lastAbsentDate || r.date > lastAbsentDate) lastAbsentDate = r.date;
                            } else if (r.status === 'متأخر') {
                                lateCount++;
                            }
                        }
                    }

                    const totalAbsent = unjustifiedHours + justifiedHours;
                    const missedHw = typeof getTotalMissedHomework === 'function' ? getTotalMissedHomework(studentId, className) : 0;

                    const beh = classBehaviors[studentId] || { status: 'منضبط', note: '' };
                    const behaviorStatus = beh.status || 'منضبط';
                    const behaviorNote = beh.note || '';

                    const isFrequentAbsence = totalAbsent >= thresholdVal && totalAbsent > 0;
                    const isDisruptive = (behaviorStatus === 'مشوش');
                    const isWarning = (behaviorStatus === 'تنبيه');
                    const isBadBehavior = isDisruptive || isWarning;
                    const isDual = isFrequentAbsence && isBadBehavior;
                    const isHwLate = (lateCount >= 3 || missedHw >= 3);

                    let severity = 0;
                    let severityKey = '';
                    let severityLabel = '';
                    let severityBadgeClass = '';

                    if (isDual) {
                        severity = 4;
                        severityKey = 'both';
                        severityLabel = 'حرج جداً: غياب متكرر وسلوك غير منضبط';
                        severityBadgeClass = 'dash-badge-danger';
                    } else if (isDisruptive) {
                        severity = 3;
                        severityKey = 'behavior';
                        severityLabel = 'سلوك مشوش يستدعي تدخلاً';
                        severityBadgeClass = 'dash-badge-danger';
                    } else if (totalAbsent >= (parseFloat(db.absenceThreshold) || 10)) {
                        severity = 3;
                        severityKey = 'absence';
                        severityLabel = `تجاوز عتبة الغياب (${totalAbsent} س)`;
                        severityBadgeClass = 'dash-badge-danger';
                    } else if (isFrequentAbsence) {
                        severity = 2;
                        severityKey = 'absence';
                        severityLabel = `تراكم غيابات (${totalAbsent} س)`;
                        severityBadgeClass = 'dash-badge-warning';
                    } else if (isWarning) {
                        severity = 2;
                        severityKey = 'behavior';
                        severityLabel = 'تنبيه سلوكي مسجل';
                        severityBadgeClass = 'dash-badge-warning';
                    } else if (isHwLate) {
                        severity = 1;
                        severityKey = 'hw_late';
                        severityLabel = (lateCount >= 3 && missedHw >= 3) 
                            ? 'إهمال واجبات وتأخر متكرر' 
                            : (missedHw >= 3 ? `إهمال واجبات (${missedHw} مرات)` : `تأخرات متكررة (${lateCount} مرات)`);
                        severityBadgeClass = 'dash-badge-info';
                    }

                    if (severity > 0) {
                        totalAbsentHoursSum += totalAbsent;
                        if (classStatsMap[className]) {
                            classStatsMap[className].total++;
                            if (isDual) classStatsMap[className].dual++;
                            if (isFrequentAbsence) classStatsMap[className].absence++;
                            if (isBadBehavior) classStatsMap[className].behavior++;
                            if (isHwLate) classStatsMap[className].hwLate++;
                        }

                        rawList.push({
                            id: studentId,
                            name: std.name,
                            gender: std.gender || 'M',
                            phone: std.phone || std.parentPhone || '',
                            className: className,
                            unjustifiedHours,
                            justifiedHours,
                            totalAbsent,
                            lastAbsentDate,
                            lateCount,
                            missedHw,
                            behaviorStatus,
                            behaviorNote,
                            isFrequentAbsence,
                            isDisruptive,
                            isWarning,
                            isBadBehavior,
                            isDual,
                            isHwLate,
                            severity,
                            severityKey,
                            severityLabel,
                            severityBadgeClass
                        });
                    }
                });
            });

            const stats = {
                totalCount: rawList.length,
                dualCount: rawList.filter(s => s.isDual).length,
                absenceCount: rawList.filter(s => s.isFrequentAbsence).length,
                behaviorCount: rawList.filter(s => s.isBadBehavior).length,
                hwLateCount: rawList.filter(s => s.isHwLate).length,
                totalAbsentHoursSum,
                classStatsMap,
                grandTotalAbsenceHours,
                currentMonthAbsenceHours,
                previousMonthAbsenceHours,
                momPercentChange,
                momChangeType,
                curMonthPrefix,
                prevMonthPrefix
            };

            let filtered = rawList.slice();

            if (filter.category === 'both') {
                filtered = filtered.filter(s => s.isDual);
            } else if (filter.category === 'absence') {
                filtered = filtered.filter(s => s.isFrequentAbsence);
            } else if (filter.category === 'behavior') {
                filtered = filtered.filter(s => s.isBadBehavior);
            } else if (filter.category === 'hw_late') {
                filtered = filtered.filter(s => s.isHwLate);
            }

            if (filter.class && filter.class !== 'all') {
                filtered = filtered.filter(s => s.className === filter.class);
            }

            if (filter.search && filter.search.trim()) {
                const q = filter.search.trim().toLowerCase();
                filtered = filtered.filter(s => 
                    (s.name && s.name.toLowerCase().includes(q)) ||
                    (s.id && String(s.id).toLowerCase().includes(q)) ||
                    (s.className && s.className.toLowerCase().includes(q)) ||
                    (s.behaviorNote && s.behaviorNote.toLowerCase().includes(q))
                );
            }

            if (filter.sort === 'severity') {
                filtered.sort((a, b) => (b.severity - a.severity) || (b.totalAbsent - a.totalAbsent) || a.name.localeCompare(b.name, 'ar'));
            } else if (filter.sort === 'absence') {
                filtered.sort((a, b) => (b.totalAbsent - a.totalAbsent) || (b.severity - a.severity) || a.name.localeCompare(b.name, 'ar'));
            } else if (filter.sort === 'behavior') {
                const rank = { 'مشوش': 3, 'تنبيه': 2, 'منضبط': 1 };
                filtered.sort((a, b) => ((rank[b.behaviorStatus] || 0) - (rank[a.behaviorStatus] || 0)) || (b.totalAbsent - a.totalAbsent));
            } else if (filter.sort === 'class') {
                filtered.sort((a, b) => a.className.localeCompare(b.className, 'ar') || (b.severity - a.severity));
            } else if (filter.sort === 'name') {
                filtered.sort((a, b) => a.name.localeCompare(b.name, 'ar'));
            }

            return { students: filtered, allAtRisk: rawList, stats };
        }

        function updateDashboardAlertBadges() {
            try {
                const { stats } = getDashboardAtRiskStudents();
                const total = stats ? stats.totalCount : 0;
                const dual = stats ? stats.dualCount : 0;

                let delayedAdminCount = 0;
                if (typeof window.getAdminFollowUpMetrics === 'function') {
                    try {
                        delayedAdminCount = window.getAdminFollowUpMetrics().delayedCount || 0;
                    } catch(err) {}
                }
                const grandTotalAlerts = total + delayedAdminCount;

                const navBadge = document.getElementById('navDashboardAlertCount');
                if (navBadge) {
                    if (grandTotalAlerts > 0) {
                        navBadge.textContent = grandTotalAlerts > 99 ? '99+' : grandTotalAlerts;
                        navBadge.style.display = 'inline-block';
                    } else {
                        navBadge.style.display = 'none';
                    }
                }

                const navDashAlertBadge = document.getElementById('navDashAlertBadge');
                if (navDashAlertBadge) {
                    if (grandTotalAlerts > 0) {
                        navDashAlertBadge.textContent = grandTotalAlerts > 99 ? '99+' : grandTotalAlerts;
                        navDashAlertBadge.style.display = 'inline-block';
                    } else {
                        navDashAlertBadge.style.display = 'none';
                    }
                }

                const homeDashBadge = document.getElementById('homeDashBadge');
                const homeDashBadgeGrouped = document.getElementById('homeDashBadgeGrouped');
                if (homeDashBadge) {
                    if (grandTotalAlerts > 0) {
                        homeDashBadge.textContent = grandTotalAlerts > 99 ? '99+' : grandTotalAlerts;
                        homeDashBadge.style.display = 'inline-block';
                    } else {
                        homeDashBadge.style.display = 'none';
                    }
                }
                if (homeDashBadgeGrouped) {
                    if (grandTotalAlerts > 0) {
                        homeDashBadgeGrouped.textContent = grandTotalAlerts > 99 ? '99+' : grandTotalAlerts;
                        homeDashBadgeGrouped.style.display = 'inline-block';
                    } else {
                        homeDashBadgeGrouped.style.display = 'none';
                    }
                }

                const headerBadge = document.getElementById('headerDashboardAlertBadge');
                if (headerBadge) {
                    if (grandTotalAlerts > 0) {
                        headerBadge.textContent = grandTotalAlerts > 99 ? '99+' : grandTotalAlerts;
                        headerBadge.style.display = 'inline-flex';
                        if (delayedAdminCount > 0) {
                            headerBadge.style.background = '#dc2626';
                            headerBadge.title = `يوجد ${delayedAdminCount} كشف متابعة تأخر رد الإدارة عنه لأكثر من 48 ساعة`;
                        }
                    } else {
                        headerBadge.style.display = 'none';
                    }
                }

                const banner = document.getElementById('dashboardAlertBanner');
                if (banner) {
                    banner.style.display = 'none';
                }
            } catch(e) {
                console.error("updateDashboardAlertBadges error:", e);
            }
        }

        /* ==========================================================================
           شريط تقدم الموسم الدراسي وأداة حالة الطقس والتنقل في لوحة القيادة
           ========================================================================== */

        // 1. حساب واسترجاع تواريخ الموسم الدراسي
        function getSchoolYearDates() {
            const now = (typeof getAppNow === 'function') ? getAppNow() : new Date();
            const currYear = now.getFullYear();
            const currMonth = now.getMonth(); // 0-indexed: 0=Jan, 8=Sept

            // الافتراضي المغربي الرسمي: يبدأ 01 شتنبر وينتهي 30 يونيو
            let defaultStartYear = currYear;
            let defaultEndYear = currYear + 1;
            if (currMonth < 7) {
                defaultStartYear = currYear - 1;
                defaultEndYear = currYear;
            }

            const defaultStartStr = `${defaultStartYear}-09-01`;
            const defaultEndStr = `${defaultEndYear}-06-30`;

            const startStr = (db.settings && db.settings.schoolYearStart) ? db.settings.schoolYearStart : defaultStartStr;
            const endStr = (db.settings && db.settings.schoolYearEnd) ? db.settings.schoolYearEnd : defaultEndStr;

            const label = (db.teacherProfile && db.teacherProfile.academicYear) 
                ? db.teacherProfile.academicYear 
                : `${defaultStartYear}/${defaultEndYear}`;

            return {
                startStr,
                endStr,
                label,
                defaultStartStr,
                defaultEndStr
            };
        }
        window.getSchoolYearDates = getSchoolYearDates;

        function renderSchoolYearProgress() {
            const card = document.getElementById('dashSchoolYearProgressCard');
            if (!card) return;

            try {
                const dates = getSchoolYearDates();
                const now = (typeof getAppNow === 'function') ? getAppNow() : new Date();
                
                const startDate = new Date(dates.startStr + 'T00:00:00');
                const endDate = new Date(dates.endStr + 'T23:59:59');

                if (isNaN(startDate.getTime()) || isNaN(endDate.getTime()) || endDate <= startDate) {
                    return;
                }

                const totalMs = endDate.getTime() - startDate.getTime();
                const totalDays = Math.max(1, Math.round(totalMs / (1000 * 60 * 60 * 24)));

                let elapsedDays = 0;
                if (now > startDate) {
                    const elapsedMs = Math.min(now.getTime() - startDate.getTime(), totalMs);
                    elapsedDays = Math.max(0, Math.round(elapsedMs / (1000 * 60 * 60 * 24)));
                }

                const remainingDays = Math.max(0, totalDays - elapsedDays);
                const pctElapsed = Math.min(100, Math.max(0, (elapsedDays / totalDays) * 100));
                const pctRemaining = Math.max(0, 100 - pctElapsed);

                const formatArDate = (d) => {
                    try {
                        const day = String(d.getDate()).padStart(2, '0');
                        const month = String(d.getMonth() + 1).padStart(2, '0');
                        const year = d.getFullYear();
                        return `${day}/${month}/${year}`;
                    } catch(e) {
                        return d.toISOString().slice(0, 10);
                    }
                };

                // Updating UI elements
                const badgeEl = document.getElementById('dashSchoolYearBadge');
                if (badgeEl) badgeEl.textContent = dates.label;

                const pctRemainingEl = document.getElementById('dashSchoolYearPctRemaining');
                if (pctRemainingEl) pctRemainingEl.textContent = pctRemaining.toFixed(1);

                const daysRemainingBadgeEl = document.getElementById('dashSchoolYearDaysRemainingText');
                if (daysRemainingBadgeEl) {
                    daysRemainingBadgeEl.textContent = `${remainingDays} يوماً متبقية`;
                }

                const daysElapsedTextEl = document.getElementById('dashSchoolYearDaysElapsedText');
                if (daysElapsedTextEl) daysElapsedTextEl.textContent = elapsedDays;

                const pctElapsedTextEl = document.getElementById('dashSchoolYearPctElapsedText');
                if (pctElapsedTextEl) pctElapsedTextEl.textContent = pctElapsed.toFixed(1);

                const progressFillEl = document.getElementById('dashSchoolYearProgressFill');
                if (progressFillEl) {
                    progressFillEl.style.width = `${pctElapsed.toFixed(1)}%`;
                }

                const startEl = document.getElementById('dashSchoolYearStartDate');
                if (startEl) startEl.textContent = formatArDate(startDate);

                const endEl = document.getElementById('dashSchoolYearEndDate');
                if (endEl) endEl.textContent = formatArDate(endDate);

                const elapsedEl = document.getElementById('dashSchoolYearDaysElapsed');
                if (elapsedEl) elapsedEl.textContent = `${elapsedDays} يوم (${pctElapsed.toFixed(0)}%)`;

                const remainingEl = document.getElementById('dashSchoolYearDaysRemaining');
                if (remainingEl) remainingEl.textContent = `${remainingDays} يوم (${pctRemaining.toFixed(0)}%)`;

            } catch (err) {
                console.error("renderSchoolYearProgress error:", err);
            }
        }
        window.renderSchoolYearProgress = renderSchoolYearProgress;

        function openSchoolYearDatesModal() {
            const dates = getSchoolYearDates();
            const startInput = document.getElementById('schoolYearStartInput');
            const endInput = document.getElementById('schoolYearEndInput');
            if (startInput) startInput.value = dates.startStr;
            if (endInput) endInput.value = dates.endStr;

            const modal = document.getElementById('schoolYearDatesModal');
            if (modal) {
                modal.style.display = 'flex';
                if (window.renderLucide) window.renderLucide();
                if (window.lucide && typeof window.lucide.createIcons === 'function') window.lucide.createIcons({ root: modal });
            }
        }
        window.openSchoolYearDatesModal = openSchoolYearDatesModal;

        function closeSchoolYearDatesModal() {
            const modal = document.getElementById('schoolYearDatesModal');
            if (modal) modal.style.display = 'none';
        }
        window.closeSchoolYearDatesModal = closeSchoolYearDatesModal;

        function applyPresetSchoolYearDates(preset) {
            const dates = getSchoolYearDates();
            const startInput = document.getElementById('schoolYearStartInput');
            const endInput = document.getElementById('schoolYearEndInput');
            if (!startInput || !endInput) return;

            const now = (typeof getAppNow === 'function') ? getAppNow() : new Date();
            const currYear = now.getFullYear();
            const currMonth = now.getMonth();
            let startYear = (currMonth < 7) ? currYear - 1 : currYear;
            let endYear = startYear + 1;

            if (preset === 'extended') {
                startInput.value = `${startYear}-09-01`;
                endInput.value = `${endYear}-07-10`;
            } else {
                startInput.value = `${startYear}-09-01`;
                endInput.value = `${endYear}-06-30`;
            }
        }
        window.applyPresetSchoolYearDates = applyPresetSchoolYearDates;

        function saveSchoolYearDatesFromModal() {
            const startInput = document.getElementById('schoolYearStartInput');
            const endInput = document.getElementById('schoolYearEndInput');
            if (!startInput || !endInput) return;

            const startVal = startInput.value;
            const endVal = endInput.value;

            if (!startVal || !endVal) {
                if (typeof showNotification === 'function') showNotification('يرجى تحديد تاريخ البداية والنهاية للموسم الدراسي.', 'warning');
                return;
            }

            if (new Date(endVal) <= new Date(startVal)) {
                if (typeof showNotification === 'function') showNotification('تاريخ نهاية الموسم يجب أن يكون بعد تاريخ البداية.', 'warning');
                return;
            }

            if (!db.settings) db.settings = {};
            db.settings.schoolYearStart = startVal;
            db.settings.schoolYearEnd = endVal;
            saveDB();

            closeSchoolYearDatesModal();
            renderSchoolYearProgress();
            if (typeof showNotification === 'function') {
                showNotification('تم تحديث تواريخ الموسم الدراسي وشريط التقدم بنجاح!', 'success');
            }
        }
        window.saveSchoolYearDatesFromModal = saveSchoolYearDatesFromModal;

        // 2. أداة حالة الطقس والتنقل والأجواء الصفية
