            'تمارة': { lat: 33.9267, lon: -6.9122 },
            'سطات': { lat: 33.0017, lon: -7.6166 },
            'بركان': { lat: 34.9167, lon: -2.3167 },
            'الخميسات': { lat: 33.8156, lon: -6.0667 },
